import { Question } from './types';

// ══════════════════════════════════════════════════════════════
// PHYSICS — 150 unique questions (50 easy, 50 medium, 50 hard)
// ══════════════════════════════════════════════════════════════
const physicsPool: Question[] = [
  // ── EASY (50) ──
  { id: 'p_e1', difficulty: 'easy', question: 'What is the SI unit of force?', options: ['Joule', 'Newton', 'Watt', 'Pascal'], correctIndex: 1, explanation: 'The Newton (N) is the SI unit of force, named after Sir Isaac Newton.' },
  { id: 'p_e2', difficulty: 'easy', question: 'Which particle has a negative charge?', options: ['Proton', 'Neutron', 'Electron', 'Photon'], correctIndex: 2, explanation: 'Electrons carry a negative charge of approximately -1.6 × 10⁻¹⁹ coulombs.' },
  { id: 'p_e3', difficulty: 'easy', question: 'What type of energy does a moving car have?', options: ['Potential', 'Kinetic', 'Thermal', 'Chemical'], correctIndex: 1, explanation: 'Kinetic energy is the energy of motion, calculated as ½mv².' },
  { id: 'p_e4', difficulty: 'easy', question: 'What instrument measures electric current?', options: ['Voltmeter', 'Ammeter', 'Ohmmeter', 'Barometer'], correctIndex: 1, explanation: 'An ammeter measures the flow of electric current in amperes.' },
  { id: 'p_e5', difficulty: 'easy', question: 'What is the speed of light in vacuum?', options: ['3×10⁶ m/s', '3×10⁸ m/s', '3×10¹⁰ m/s', '3×10⁴ m/s'], correctIndex: 1, explanation: 'Light travels at approximately 3 × 10⁸ meters per second in a vacuum.' },
  { id: 'p_e6', difficulty: 'easy', question: 'Sound cannot travel through which medium?', options: ['Water', 'Air', 'Steel', 'Vacuum'], correctIndex: 3, explanation: 'Sound requires a medium (solid, liquid, or gas) to propagate; it cannot travel through a vacuum.' },
  { id: 'p_e7', difficulty: 'easy', question: 'What is the formula for kinetic energy?', options: ['½mv²', 'mgh', 'Fd', 'mv'], correctIndex: 0, explanation: 'Kinetic energy equals one-half times mass times velocity squared (½mv²).' },
  { id: 'p_e8', difficulty: 'easy', question: 'What does a prism do to white light?', options: ['Absorbs it', 'Reflects it', 'Disperses it into colors', 'Amplifies it'], correctIndex: 2, explanation: 'A prism separates white light into its component colors through refraction at different angles.' },
  { id: 'p_e9', difficulty: 'easy', question: 'What is the unit of electrical resistance?', options: ['Volt', 'Ampere', 'Ohm', 'Watt'], correctIndex: 2, explanation: 'The Ohm (Ω) is the SI unit of electrical resistance.' },
  { id: 'p_e10', difficulty: 'easy', question: 'What is the SI unit of power?', options: ['Joule', 'Watt', 'Newton', 'Ampere'], correctIndex: 1, explanation: 'The Watt (W) equals one joule per second and measures the rate of energy transfer.' },
  { id: 'p_e11', difficulty: 'easy', question: 'What is the SI unit of energy?', options: ['Watt', 'Joule', 'Newton', 'Pascal'], correctIndex: 1, explanation: 'The Joule (J) is the SI unit of energy, equal to the work done by a force of one Newton over one meter.' },
  { id: 'p_e12', difficulty: 'easy', question: 'Which color of visible light has the longest wavelength?', options: ['Blue', 'Green', 'Red', 'Violet'], correctIndex: 2, explanation: 'Red light has a wavelength of about 620-750 nm, the longest in the visible spectrum.' },
  { id: 'p_e13', difficulty: 'easy', question: 'What is the acceleration due to gravity on Earth?', options: ['8.9 m/s²', '9.8 m/s²', '10.8 m/s²', '7.8 m/s²'], correctIndex: 1, explanation: 'Earth\'s gravitational acceleration is approximately 9.8 m/s² at sea level.' },
  { id: 'p_e14', difficulty: 'easy', question: 'Which lens converges light rays to a focal point?', options: ['Concave', 'Convex', 'Flat', 'Cylindrical'], correctIndex: 1, explanation: 'A convex (converging) lens bends parallel light rays inward to meet at a focal point.' },
  { id: 'p_e15', difficulty: 'easy', question: 'What is the boiling point of water in Kelvin?', options: ['273 K', '373 K', '473 K', '100 K'], correctIndex: 1, explanation: '100°C equals 373.15 K. Kelvin = Celsius + 273.15.' },
  { id: 'p_e16', difficulty: 'easy', question: 'What type of mirror is used in car headlights?', options: ['Plane', 'Convex', 'Concave', 'Cylindrical'], correctIndex: 2, explanation: 'Concave mirrors focus light into a parallel beam, making them ideal for headlights.' },
  { id: 'p_e17', difficulty: 'easy', question: 'What is the SI unit of pressure?', options: ['Newton', 'Pascal', 'Joule', 'Bar'], correctIndex: 1, explanation: 'The Pascal (Pa) equals one Newton per square meter.' },
  { id: 'p_e18', difficulty: 'easy', question: 'What is the frequency unit?', options: ['Hertz', 'Ohm', 'Watt', 'Tesla'], correctIndex: 0, explanation: 'Hertz (Hz) measures frequency — one Hz equals one cycle per second.' },
  { id: 'p_e19', difficulty: 'easy', question: 'Which force keeps planets in orbit around the Sun?', options: ['Magnetic', 'Nuclear', 'Gravitational', 'Electromagnetic'], correctIndex: 2, explanation: 'Gravitational force between the Sun and planets provides the centripetal force for orbital motion.' },
  { id: 'p_e20', difficulty: 'easy', question: 'What causes a rainbow?', options: ['Reflection only', 'Refraction and dispersion', 'Diffraction', 'Polarization'], correctIndex: 1, explanation: 'Rainbows form when sunlight is refracted and dispersed inside water droplets, separating into colors.' },
  { id: 'p_e21', difficulty: 'easy', question: 'What is the SI unit of temperature?', options: ['Celsius', 'Fahrenheit', 'Kelvin', 'Rankine'], correctIndex: 2, explanation: 'The Kelvin (K) is the SI base unit of temperature.' },
  { id: 'p_e22', difficulty: 'easy', question: 'What is the SI unit of electric charge?', options: ['Volt', 'Ampere', 'Coulomb', 'Ohm'], correctIndex: 2, explanation: 'The Coulomb (C) measures electric charge. One Coulomb equals about 6.24 × 10¹⁸ electrons.' },
  { id: 'p_e23', difficulty: 'easy', question: 'What form of energy is stored in a stretched rubber band?', options: ['Kinetic', 'Elastic potential', 'Thermal', 'Chemical'], correctIndex: 1, explanation: 'A stretched rubber band stores elastic potential energy due to its deformation.' },
  { id: 'p_e24', difficulty: 'easy', question: 'What is the SI unit of mass?', options: ['Pound', 'Gram', 'Kilogram', 'Ounce'], correctIndex: 2, explanation: 'The kilogram (kg) is the SI base unit of mass.' },
  { id: 'p_e25', difficulty: 'easy', question: 'Light travels fastest in which medium?', options: ['Water', 'Glass', 'Diamond', 'Vacuum'], correctIndex: 3, explanation: 'Light travels at its maximum speed in a vacuum because there are no particles to slow it down.' },
  { id: 'p_e26', difficulty: 'easy', question: 'What is the SI unit of length?', options: ['Foot', 'Meter', 'Yard', 'Mile'], correctIndex: 1, explanation: 'The meter (m) is the SI base unit of length.' },
  { id: 'p_e27', difficulty: 'easy', question: 'What type of wave is a sound wave?', options: ['Transverse', 'Longitudinal', 'Electromagnetic', 'Surface'], correctIndex: 1, explanation: 'Sound waves are longitudinal — particles vibrate parallel to the wave\'s direction of travel.' },
  { id: 'p_e28', difficulty: 'easy', question: 'What happens to a ball thrown straight up at its highest point?', options: ['Speed is maximum', 'Velocity is zero', 'Acceleration is zero', 'Force is zero'], correctIndex: 1, explanation: 'At the highest point, the ball momentarily stops (velocity = 0) before falling back down.' },
  { id: 'p_e29', difficulty: 'easy', question: 'What device converts electrical energy to mechanical energy?', options: ['Generator', 'Motor', 'Battery', 'Transformer'], correctIndex: 1, explanation: 'An electric motor converts electrical energy into rotational mechanical energy.' },
  { id: 'p_e30', difficulty: 'easy', question: 'Which state of matter has a fixed shape and volume?', options: ['Gas', 'Liquid', 'Solid', 'Plasma'], correctIndex: 2, explanation: 'Solids have fixed shape and volume because their particles are tightly packed in a regular arrangement.' },
  { id: 'p_e31', difficulty: 'easy', question: 'What is the formula for speed?', options: ['Distance × Time', 'Distance / Time', 'Mass × Acceleration', 'Force / Area'], correctIndex: 1, explanation: 'Speed equals the distance traveled divided by the time taken.' },
  { id: 'p_e32', difficulty: 'easy', question: 'What type of energy does food contain?', options: ['Kinetic', 'Nuclear', 'Chemical', 'Electrical'], correctIndex: 2, explanation: 'Food stores chemical energy in the bonds of molecules, released during digestion and metabolism.' },
  { id: 'p_e33', difficulty: 'easy', question: 'Which material is the best conductor of electricity?', options: ['Rubber', 'Wood', 'Copper', 'Plastic'], correctIndex: 2, explanation: 'Copper is an excellent electrical conductor due to its free-moving electrons.' },
  { id: 'p_e34', difficulty: 'easy', question: 'What is the center of an atom called?', options: ['Electron cloud', 'Shell', 'Nucleus', 'Orbital'], correctIndex: 2, explanation: 'The nucleus is the dense center of an atom containing protons and neutrons.' },
  { id: 'p_e35', difficulty: 'easy', question: 'What type of energy is stored in a battery?', options: ['Kinetic', 'Chemical', 'Nuclear', 'Mechanical'], correctIndex: 1, explanation: 'Batteries store chemical energy that is converted to electrical energy during discharge.' },
  { id: 'p_e36', difficulty: 'easy', question: 'What is friction?', options: ['A push force', 'A force that opposes motion', 'Gravity', 'Magnetism'], correctIndex: 1, explanation: 'Friction is a contact force that resists the relative motion of two surfaces.' },
  { id: 'p_e37', difficulty: 'easy', question: 'What is the unit of work?', options: ['Watt', 'Joule', 'Newton', 'Pascal'], correctIndex: 1, explanation: 'Work is measured in Joules. One Joule equals one Newton-meter of force applied over distance.' },
  { id: 'p_e38', difficulty: 'easy', question: 'An object at rest stays at rest unless acted upon by a force. Which law is this?', options: ['Newton\'s 1st', 'Newton\'s 2nd', 'Newton\'s 3rd', 'Hooke\'s Law'], correctIndex: 0, explanation: 'Newton\'s First Law (Law of Inertia) states that an object maintains its state of motion unless a net force acts on it.' },
  { id: 'p_e39', difficulty: 'easy', question: 'What is the opposite of transparent?', options: ['Translucent', 'Opaque', 'Reflective', 'Luminous'], correctIndex: 1, explanation: 'Opaque materials do not allow light to pass through them.' },
  { id: 'p_e40', difficulty: 'easy', question: 'What is the SI unit of time?', options: ['Minute', 'Hour', 'Second', 'Day'], correctIndex: 2, explanation: 'The second (s) is the SI base unit of time.' },
  { id: 'p_e41', difficulty: 'easy', question: 'What does a thermometer measure?', options: ['Pressure', 'Temperature', 'Humidity', 'Speed'], correctIndex: 1, explanation: 'A thermometer measures temperature, the average kinetic energy of particles in a substance.' },
  { id: 'p_e42', difficulty: 'easy', question: 'What is the pull of the Earth on an object called?', options: ['Mass', 'Weight', 'Density', 'Inertia'], correctIndex: 1, explanation: 'Weight is the gravitational force acting on an object\'s mass (W = mg).' },
  { id: 'p_e43', difficulty: 'easy', question: 'What is the main source of energy on Earth?', options: ['The Moon', 'The Sun', 'Earth\'s core', 'Wind'], correctIndex: 1, explanation: 'The Sun provides nearly all the energy that drives weather, climate, and life on Earth.' },
  { id: 'p_e44', difficulty: 'easy', question: 'Which simple machine is a ramp?', options: ['Lever', 'Pulley', 'Inclined plane', 'Wheel and axle'], correctIndex: 2, explanation: 'An inclined plane (ramp) reduces the force needed to raise an object by increasing the distance.' },
  { id: 'p_e45', difficulty: 'easy', question: 'What color does a red object reflect?', options: ['Blue', 'Green', 'Red', 'White'], correctIndex: 2, explanation: 'A red object absorbs all colors of light except red, which it reflects to our eyes.' },
  { id: 'p_e46', difficulty: 'easy', question: 'What does a magnet attract?', options: ['Wood', 'Iron', 'Plastic', 'Glass'], correctIndex: 1, explanation: 'Magnets attract ferromagnetic materials like iron, nickel, and cobalt.' },
  { id: 'p_e47', difficulty: 'easy', question: 'What is the fastest type of heat transfer?', options: ['Conduction', 'Convection', 'Radiation', 'Evaporation'], correctIndex: 2, explanation: 'Radiation transfers heat through electromagnetic waves at the speed of light, requiring no medium.' },
  { id: 'p_e48', difficulty: 'easy', question: 'What happens to water at 0°C?', options: ['Boils', 'Freezes', 'Evaporates', 'Sublimates'], correctIndex: 1, explanation: 'Water freezes (solidifies) at 0°C (273.15 K) at standard atmospheric pressure.' },
  { id: 'p_e49', difficulty: 'easy', question: 'What force acts on a parachute?', options: ['Thrust', 'Air resistance', 'Magnetism', 'Tension only'], correctIndex: 1, explanation: 'Air resistance (drag) acts upward on a parachute, opposing gravity to slow the fall.' },
  { id: 'p_e50', difficulty: 'easy', question: 'What is the symbol for velocity?', options: ['a', 'v', 'F', 's'], correctIndex: 1, explanation: 'Velocity is denoted by "v" and represents speed with a direction.' },

  // ── MEDIUM (50) ──
  { id: 'p_m1', difficulty: 'medium', question: "What is Newton's Third Law?", options: ['F = ma', 'Every action has an equal and opposite reaction', 'Objects at rest stay at rest', 'Energy is conserved'], correctIndex: 1, explanation: 'Newton\'s Third Law states that for every force exerted by one body on another, there is an equal and opposite force exerted back.' },
  { id: 'p_m2', difficulty: 'medium', question: "What is Ohm's Law?", options: ['V = IR', 'F = ma', 'E = mc²', 'P = IV'], correctIndex: 0, explanation: 'Ohm\'s Law relates voltage (V), current (I), and resistance (R): V = IR.' },
  { id: 'p_m3', difficulty: 'medium', question: 'What is the principle behind hydraulic lifts?', options: ['Archimedes\' Principle', "Pascal's Law", "Bernoulli's Principle", "Newton's 3rd Law"], correctIndex: 1, explanation: 'Pascal\'s Law states that pressure applied to a confined fluid is transmitted equally in all directions.' },
  { id: 'p_m4', difficulty: 'medium', question: 'What does F = ma represent?', options: ["Newton's 1st Law", "Newton's 2nd Law", "Newton's 3rd Law", "Hooke's Law"], correctIndex: 1, explanation: 'Newton\'s Second Law states that force equals mass times acceleration.' },
  { id: 'p_m5', difficulty: 'medium', question: 'What is terminal velocity?', options: ['Maximum speed in free fall', 'Speed of sound', 'Speed of light', 'Zero velocity'], correctIndex: 0, explanation: 'Terminal velocity occurs when air resistance equals gravitational force, resulting in zero net acceleration.' },
  { id: 'p_m6', difficulty: 'medium', question: 'The angle of incidence equals the angle of:', options: ['Diffraction', 'Reflection', 'Refraction', 'Dispersion'], correctIndex: 1, explanation: 'The law of reflection states that the angle of incidence equals the angle of reflection, measured from the normal.' },
  { id: 'p_m7', difficulty: 'medium', question: 'What is the unit of magnetic flux?', options: ['Tesla', 'Weber', 'Gauss', 'Henry'], correctIndex: 1, explanation: 'The Weber (Wb) is the SI unit of magnetic flux. 1 Wb = 1 T·m².' },
  { id: 'p_m8', difficulty: 'medium', question: 'Who discovered electromagnetic induction?', options: ['Faraday', 'Ampere', 'Ohm', 'Tesla'], correctIndex: 0, explanation: 'Michael Faraday discovered in 1831 that a changing magnetic field induces an electric current.' },
  { id: 'p_m9', difficulty: 'medium', question: 'Which electromagnetic wave has the shortest wavelength?', options: ['Radio waves', 'Microwaves', 'X-rays', 'Gamma rays'], correctIndex: 3, explanation: 'Gamma rays have the shortest wavelength (< 10 pm) and highest energy in the EM spectrum.' },
  { id: 'p_m10', difficulty: 'medium', question: 'What is the Doppler effect?', options: ['Change in observed frequency due to motion', 'Light bending around objects', 'Sound absorption by materials', 'Wave reflection at boundaries'], correctIndex: 0, explanation: 'The Doppler effect causes a shift in frequency when a source and observer move relative to each other.' },
  { id: 'p_m11', difficulty: 'medium', question: 'What is the relationship between wavelength and frequency?', options: ['Directly proportional', 'Inversely proportional', 'No relation', 'Exponential'], correctIndex: 1, explanation: 'For a given wave speed, wavelength and frequency are inversely proportional: v = fλ.' },
  { id: 'p_m12', difficulty: 'medium', question: 'What is electrical power calculated as?', options: ['P = V/I', 'P = VI', 'P = V+I', 'P = V-I'], correctIndex: 1, explanation: 'Electrical power P = VI (voltage × current), measured in watts.' },
  { id: 'p_m13', difficulty: 'medium', question: 'What is the principle of conservation of energy?', options: ['Energy can be created', 'Energy can be destroyed', 'Energy is always converted, never created or destroyed', 'Energy increases over time'], correctIndex: 2, explanation: 'The law of conservation of energy states that energy cannot be created or destroyed, only transformed.' },
  { id: 'p_m14', difficulty: 'medium', question: 'What is the resultant of two forces acting at right angles?', options: ['Sum of forces', 'Difference of forces', 'Square root of sum of squares', 'Product of forces'], correctIndex: 2, explanation: 'For perpendicular forces, the resultant is found using the Pythagorean theorem: R = √(F₁² + F₂²).' },
  { id: 'p_m15', difficulty: 'medium', question: 'What is specific heat capacity?', options: ['Energy to raise 1 kg by 1°C', 'Energy to melt 1 kg', 'Energy to boil 1 kg', 'Total heat in a body'], correctIndex: 0, explanation: 'Specific heat capacity is the energy required to raise the temperature of 1 kg of a substance by 1°C.' },
  { id: 'p_m16', difficulty: 'medium', question: 'In a series circuit, what remains constant?', options: ['Voltage', 'Current', 'Resistance', 'Power'], correctIndex: 1, explanation: 'In a series circuit, the same current flows through all components.' },
  { id: 'p_m17', difficulty: 'medium', question: 'What is the work-energy theorem?', options: ['Net work equals change in kinetic energy', 'Work equals force', 'Energy equals mass', 'Power equals work per area'], correctIndex: 0, explanation: 'The work-energy theorem states that the net work done on an object equals its change in kinetic energy.' },
  { id: 'p_m18', difficulty: 'medium', question: 'What is Snell\'s law used for?', options: ['Calculating refraction angles', 'Measuring gravity', 'Finding resistance', 'Computing velocity'], correctIndex: 0, explanation: 'Snell\'s law relates the angles of incidence and refraction to the refractive indices: n₁sinθ₁ = n₂sinθ₂.' },
  { id: 'p_m19', difficulty: 'medium', question: 'What is electromagnetic radiation?', options: ['Energy traveling as waves through space', 'Sound waves in metal', 'Heat through solids', 'Vibration in strings'], correctIndex: 0, explanation: 'EM radiation consists of oscillating electric and magnetic fields propagating through space at the speed of light.' },
  { id: 'p_m20', difficulty: 'medium', question: 'What happens to resistance when a wire is heated?', options: ['Decreases', 'Increases', 'Stays the same', 'Becomes zero'], correctIndex: 1, explanation: 'For most metals, resistance increases with temperature as atoms vibrate more, impeding electron flow.' },
  { id: 'p_m21', difficulty: 'medium', question: 'What is centripetal force?', options: ['Force directed toward the center of a circular path', 'Force pushing outward', 'Gravitational force only', 'Friction force only'], correctIndex: 0, explanation: 'Centripetal force is the net force directed toward the center that keeps an object moving in a circle.' },
  { id: 'p_m22', difficulty: 'medium', question: 'What is the principle of moments?', options: ['Sum of clockwise moments equals sum of counterclockwise moments at equilibrium', 'Force equals mass times acceleration', 'Energy is conserved', 'Momentum is always zero'], correctIndex: 0, explanation: 'For a body in rotational equilibrium, the sum of clockwise moments equals the sum of counterclockwise moments about any point.' },
  { id: 'p_m23', difficulty: 'medium', question: 'What is the SI unit of capacitance?', options: ['Henry', 'Farad', 'Ohm', 'Coulomb'], correctIndex: 1, explanation: 'The Farad (F) is the SI unit of capacitance. 1 F = 1 C/V.' },
  { id: 'p_m24', difficulty: 'medium', question: 'What is resonance?', options: ['Large amplitude oscillation at natural frequency', 'Decrease in amplitude', 'Random vibration', 'Constant velocity motion'], correctIndex: 0, explanation: 'Resonance occurs when a system is driven at its natural frequency, causing maximum energy transfer and amplitude.' },
  { id: 'p_m25', difficulty: 'medium', question: 'What is the difference between mass and weight?', options: ['Mass is amount of matter; weight is gravitational force', 'They are identical', 'Mass changes with location; weight does not', 'Weight is measured in kg'], correctIndex: 0, explanation: 'Mass is a measure of the amount of matter (kg) and is constant; weight is the gravitational force on that mass (N).' },
  { id: 'p_m26', difficulty: 'medium', question: 'What does a transformer do?', options: ['Changes AC voltage levels', 'Converts AC to DC', 'Stores energy', 'Generates electricity'], correctIndex: 0, explanation: 'A transformer changes the voltage of alternating current using electromagnetic induction between two coils.' },
  { id: 'p_m27', difficulty: 'medium', question: 'What is total internal reflection?', options: ['Light trapped inside a denser medium at angles beyond the critical angle', 'Light passing through glass', 'Light reflecting off a mirror', 'Light being absorbed'], correctIndex: 0, explanation: 'Total internal reflection occurs when light hits a boundary at an angle greater than the critical angle, reflecting entirely back.' },
  { id: 'p_m28', difficulty: 'medium', question: 'What is the equation for momentum?', options: ['p = mv', 'p = ma', 'p = Ft', 'p = ½mv²'], correctIndex: 0, explanation: 'Linear momentum p = mv, where m is mass and v is velocity. It is a vector quantity.' },
  { id: 'p_m29', difficulty: 'medium', question: 'What is the efficiency formula?', options: ['(Useful output / Total input) × 100%', 'Input / Output', 'Force × Distance', 'Power × Time'], correctIndex: 0, explanation: 'Efficiency measures how much input energy is usefully converted: η = (useful output ÷ total input) × 100%.' },
  { id: 'p_m30', difficulty: 'medium', question: 'What is an electric field?', options: ['Region where a charge experiences a force', 'A magnetic pole', 'A type of current', 'A resistance network'], correctIndex: 0, explanation: 'An electric field is the region around a charged particle where another charge would experience an electric force.' },
  { id: 'p_m31', difficulty: 'medium', question: 'What is the principle of superposition of waves?', options: ['Waves add algebraically when overlapping', 'Waves cancel always', 'Waves reflect always', 'Waves change frequency'], correctIndex: 0, explanation: 'When two waves overlap, their displacements add algebraically — this is the principle of superposition.' },
  { id: 'p_m32', difficulty: 'medium', question: 'What determines the pitch of a sound?', options: ['Amplitude', 'Frequency', 'Wavelength only', 'Medium'], correctIndex: 1, explanation: 'Pitch is determined by the frequency of a sound wave — higher frequency means higher pitch.' },
  { id: 'p_m33', difficulty: 'medium', question: 'What is Archimedes\' principle?', options: ['Buoyant force equals weight of displaced fluid', 'Pressure increases with depth', 'Fluids flow from high to low pressure', 'Volume is conserved'], correctIndex: 0, explanation: 'Archimedes\' principle: the upward buoyant force on a submerged object equals the weight of the fluid it displaces.' },
  { id: 'p_m34', difficulty: 'medium', question: 'What is the photoelectric effect threshold?', options: ['Minimum frequency to emit electrons', 'Maximum voltage', 'Speed of light', 'Resistance value'], correctIndex: 0, explanation: 'Below the threshold frequency, no electrons are emitted regardless of light intensity.' },
  { id: 'p_m35', difficulty: 'medium', question: 'What is the difference between AC and DC?', options: ['AC reverses direction periodically; DC flows one way', 'AC is always higher voltage', 'DC is wireless', 'They are the same'], correctIndex: 0, explanation: 'Alternating current (AC) periodically reverses direction; direct current (DC) flows in one constant direction.' },
  { id: 'p_m36', difficulty: 'medium', question: 'What is latent heat?', options: ['Energy for phase change without temperature change', 'Energy that changes temperature', 'Energy stored in a battery', 'Energy from the Sun'], correctIndex: 0, explanation: 'Latent heat is the energy absorbed or released during a phase change at constant temperature.' },
  { id: 'p_m37', difficulty: 'medium', question: 'What is the law of conservation of momentum?', options: ['Total momentum is constant in an isolated system', 'Momentum always increases', 'Force equals momentum', 'Momentum is scalar'], correctIndex: 0, explanation: 'In an isolated system with no external forces, total momentum before and after a collision is conserved.' },
  { id: 'p_m38', difficulty: 'medium', question: 'What is diffraction?', options: ['Bending of waves around obstacles', 'Reflection off smooth surfaces', 'Absorption of light', 'Emission of electrons'], correctIndex: 0, explanation: 'Diffraction is the bending and spreading of waves when they pass through gaps or around edges.' },
  { id: 'p_m39', difficulty: 'medium', question: 'In a parallel circuit, what remains constant across components?', options: ['Current', 'Voltage', 'Resistance', 'Power dissipation'], correctIndex: 1, explanation: 'In a parallel circuit, voltage is the same across all parallel branches.' },
  { id: 'p_m40', difficulty: 'medium', question: 'What is the critical angle?', options: ['Angle of incidence that produces 90° refraction', 'Any angle of reflection', 'The largest possible angle', 'An angle of zero degrees'], correctIndex: 0, explanation: 'The critical angle is the angle of incidence at which the refracted ray travels along the boundary (90° refraction angle).' },
  { id: 'p_m41', difficulty: 'medium', question: 'What is Young\'s modulus?', options: ['Ratio of stress to strain in elastic materials', 'Speed of sound in a solid', 'Density of a metal', 'Thermal expansion rate'], correctIndex: 0, explanation: 'Young\'s modulus (E) measures stiffness: E = stress / strain, for materials within their elastic limit.' },
  { id: 'p_m42', difficulty: 'medium', question: 'What is the period of a wave?', options: ['Time for one complete cycle', 'Distance of one cycle', 'Speed of the wave', 'Amplitude of the wave'], correctIndex: 0, explanation: 'The period (T) is the time taken for one complete oscillation. T = 1/f.' },
  { id: 'p_m43', difficulty: 'medium', question: 'What is electromotive force (EMF)?', options: ['Voltage provided by a source with no current flowing', 'Current through a resistor', 'Power dissipated', 'Charge stored'], correctIndex: 0, explanation: 'EMF is the potential difference of a source when no current flows — the maximum voltage it can provide.' },
  { id: 'p_m44', difficulty: 'medium', question: 'What is the gravitational potential energy formula?', options: ['E = mgh', 'E = ½mv²', 'E = mc²', 'E = Fd'], correctIndex: 0, explanation: 'Gravitational PE = mgh, where m is mass, g is gravitational acceleration, and h is height above the reference point.' },
  { id: 'p_m45', difficulty: 'medium', question: 'What is polarization of light?', options: ['Restricting light vibrations to one plane', 'Splitting light into colors', 'Bending light', 'Absorbing light'], correctIndex: 0, explanation: 'Polarization filters light so its electric field oscillates in only one direction or plane.' },
  { id: 'p_m46', difficulty: 'medium', question: 'What is Hooke\'s Law?', options: ['Force is proportional to extension in a spring', 'Force equals mass times acceleration', 'Energy is conserved', 'Pressure increases with depth'], correctIndex: 0, explanation: 'Hooke\'s Law states F = kx — the force needed to extend a spring is proportional to the extension, within the elastic limit.' },
  { id: 'p_m47', difficulty: 'medium', question: 'What is the difference between speed and velocity?', options: ['Velocity includes direction; speed does not', 'Speed is faster', 'Velocity is always positive', 'They are identical'], correctIndex: 0, explanation: 'Speed is a scalar (magnitude only); velocity is a vector (magnitude and direction).' },
  { id: 'p_m48', difficulty: 'medium', question: 'What is the law of refraction related to?', options: ['Change in wave speed between media', 'Reflection off mirrors', 'Absorption of energy', 'Production of sound'], correctIndex: 0, explanation: 'Refraction occurs because waves change speed when entering a different medium, causing them to bend.' },
  { id: 'p_m49', difficulty: 'medium', question: 'What is thermal equilibrium?', options: ['Two bodies at the same temperature with no net heat flow', 'Maximum temperature', 'Zero temperature', 'Constant pressure'], correctIndex: 0, explanation: 'Thermal equilibrium is reached when two objects in contact have the same temperature and no heat flows between them.' },
  { id: 'p_m50', difficulty: 'medium', question: 'What is the unit of inductance?', options: ['Farad', 'Henry', 'Ohm', 'Weber'], correctIndex: 1, explanation: 'The Henry (H) is the SI unit of inductance. 1 H = 1 V·s/A.' },

  // ── HARD (50) ──
  { id: 'p_h1', difficulty: 'hard', question: 'What does E = mc² describe?', options: ['Momentum', 'Force', 'Mass-energy equivalence', 'Power'], correctIndex: 2, explanation: 'Einstein\'s equation shows that mass and energy are interchangeable. A small mass yields enormous energy.' },
  { id: 'p_h2', difficulty: 'hard', question: 'What is impedance measured in?', options: ['Ohms', 'Farads', 'Henrys', 'Watts'], correctIndex: 0, explanation: 'Impedance (Z) is measured in Ohms and is the AC equivalent of resistance, combining resistance and reactance.' },
  { id: 'p_h3', difficulty: 'hard', question: 'Which law governs current distribution in parallel circuits?', options: ["Ohm's Law", "Kirchhoff's Current Law", "Faraday's Law", "Coulomb's Law"], correctIndex: 1, explanation: 'Kirchhoff\'s Current Law (KCL) states that the total current entering a junction equals the total current leaving it.' },
  { id: 'p_h4', difficulty: 'hard', question: 'What is the moment of inertia?', options: ['Rotational analog of mass', 'Linear momentum', 'Angular velocity', 'Torque'], correctIndex: 0, explanation: 'Moment of inertia is the rotational equivalent of mass — it determines how hard it is to change an object\'s rotational speed.' },
  { id: 'p_h5', difficulty: 'hard', question: 'What is Planck\'s constant used for?', options: ['Quantum energy calculations', 'Thermodynamic cycles', 'Fluid dynamics', 'Relativity corrections'], correctIndex: 0, explanation: 'Planck\'s constant (h ≈ 6.626 × 10⁻³⁴ J·s) relates a photon\'s energy to its frequency: E = hf.' },
  { id: 'p_h6', difficulty: 'hard', question: 'What is the Heisenberg Uncertainty Principle?', options: ['Cannot simultaneously know exact position and momentum', 'Energy is always conserved', 'Waves always interfere', 'Charges are quantized'], correctIndex: 0, explanation: 'The Uncertainty Principle states that the more precisely you know a particle\'s position, the less precisely you can know its momentum, and vice versa.' },
  { id: 'p_h7', difficulty: 'hard', question: 'What is a black body in physics?', options: ['A perfect absorber and emitter of radiation', 'A dark-colored metal', 'A black hole', 'An opaque material'], correctIndex: 0, explanation: 'A black body is an idealized object that absorbs all incident radiation and re-emits it based solely on its temperature.' },
  { id: 'p_h8', difficulty: 'hard', question: 'What is the photoelectric effect?', options: ['Electrons ejected from a surface by photons', 'Light bending in a prism', 'Heat radiation from hot objects', 'Fluorescence in gases'], correctIndex: 0, explanation: 'The photoelectric effect occurs when photons with sufficient energy strike a metal surface and eject electrons.' },
  { id: 'p_h9', difficulty: 'hard', question: 'What is superconductivity?', options: ['Zero electrical resistance below a critical temperature', 'Infinite resistance', 'Magnetic repulsion', 'Perfect insulation'], correctIndex: 0, explanation: 'Superconductors have exactly zero electrical resistance below a critical temperature, allowing lossless current flow.' },
  { id: 'p_h10', difficulty: 'hard', question: 'What is wave-particle duality?', options: ['Particles exhibit both wave and particle properties', 'Waves are always particles', 'Particles never behave as waves', 'Light is only a wave'], correctIndex: 0, explanation: 'Quantum mechanics shows that all matter and energy exhibit both wave-like and particle-like behavior.' },
  { id: 'p_h11', difficulty: 'hard', question: 'What is the de Broglie wavelength?', options: ['Wavelength associated with a moving particle', 'Wavelength of visible light', 'Radius of an atom', 'Length of a photon'], correctIndex: 0, explanation: 'De Broglie wavelength λ = h/p, where h is Planck\'s constant and p is momentum. All matter has an associated wavelength.' },
  { id: 'p_h12', difficulty: 'hard', question: 'What is the Compton effect?', options: ['Increase in photon wavelength after scattering off an electron', 'Photon absorption', 'Electron emission from nuclei', 'Nuclear fission'], correctIndex: 0, explanation: 'Compton scattering shows that photons lose energy (increase wavelength) when scattering off free electrons.' },
  { id: 'p_h13', difficulty: 'hard', question: 'What is the Pauli Exclusion Principle?', options: ['No two fermions can occupy the same quantum state', 'All particles are identical', 'Electrons can share states', 'Photons repel each other'], correctIndex: 0, explanation: 'The Pauli Exclusion Principle states that no two identical fermions can simultaneously occupy the same quantum state.' },
  { id: 'p_h14', difficulty: 'hard', question: 'What is the Boltzmann constant used for?', options: ['Relating temperature to energy at the molecular level', 'Measuring voltage', 'Calculating resistance', 'Defining wavelength'], correctIndex: 0, explanation: 'The Boltzmann constant (k_B ≈ 1.38 × 10⁻²³ J/K) connects the average kinetic energy of particles to temperature.' },
  { id: 'p_h15', difficulty: 'hard', question: 'What is the Stefan-Boltzmann law?', options: ['Radiated power is proportional to T⁴', 'Pressure is proportional to temperature', 'Force equals mass times acceleration', 'Current is proportional to voltage'], correctIndex: 0, explanation: 'The Stefan-Boltzmann law states that total radiated power per unit area is proportional to the fourth power of temperature: P = σT⁴.' },
  { id: 'p_h16', difficulty: 'hard', question: 'What is the Carnot efficiency?', options: ['Maximum theoretical efficiency of a heat engine', 'Actual engine efficiency', 'Refrigerator efficiency', 'Solar panel efficiency'], correctIndex: 0, explanation: 'Carnot efficiency η = 1 - T_cold/T_hot represents the maximum possible efficiency for a heat engine operating between two temperatures.' },
  { id: 'p_h17', difficulty: 'hard', question: 'What is quantum tunneling?', options: ['Particles passing through a potential barrier they classically cannot overcome', 'Electrons orbiting faster', 'Light passing through glass', 'Sound passing through walls'], correctIndex: 0, explanation: 'Quantum tunneling allows particles to pass through energy barriers due to their wave-like nature.' },
  { id: 'p_h18', difficulty: 'hard', question: 'What is the Meissner effect?', options: ['Expulsion of magnetic fields from a superconductor', 'Attraction of magnets', 'Heating of metals', 'Cooling of gases'], correctIndex: 0, explanation: 'The Meissner effect is the complete expulsion of magnetic flux from the interior of a superconductor below its critical temperature.' },
  { id: 'p_h19', difficulty: 'hard', question: 'What is the Hall effect?', options: ['Voltage produced across a conductor in a magnetic field', 'Current in a vacuum', 'Resistance in semiconductors', 'Capacitance change'], correctIndex: 0, explanation: 'The Hall effect produces a voltage (Hall voltage) across a conductor carrying current in a perpendicular magnetic field.' },
  { id: 'p_h20', difficulty: 'hard', question: 'What is the principle of least action?', options: ['Physical systems follow paths that minimize the action integral', 'Objects always take shortest distance', 'Energy is always minimized', 'Forces are always balanced'], correctIndex: 0, explanation: 'The principle of least action states that the path taken by a physical system is the one for which the action integral is stationary (usually a minimum).' },
  { id: 'p_h21', difficulty: 'hard', question: 'What is the Lorentz force?', options: ['Force on a charged particle in electric and magnetic fields', 'Gravitational force', 'Nuclear strong force', 'Frictional force'], correctIndex: 0, explanation: 'The Lorentz force F = q(E + v × B) describes the force on a charge q moving with velocity v in electric field E and magnetic field B.' },
  { id: 'p_h22', difficulty: 'hard', question: 'What is the Biot-Savart law used for?', options: ['Calculating magnetic field from a current element', 'Finding electric potential', 'Measuring temperature', 'Computing wave speed'], correctIndex: 0, explanation: 'The Biot-Savart law calculates the magnetic field generated by a steady current at any point in space.' },
  { id: 'p_h23', difficulty: 'hard', question: 'What is Lenz\'s law?', options: ['Induced current opposes the change causing it', 'Current always increases', 'Resistance decreases with temperature', 'Voltage is constant in circuits'], correctIndex: 0, explanation: 'Lenz\'s law states that the direction of an induced current is such that it opposes the change in magnetic flux that produced it.' },
  { id: 'p_h24', difficulty: 'hard', question: 'What is the Schrödinger equation used for?', options: ['Describing quantum state evolution', 'Calculating classical orbits', 'Finding chemical formulas', 'Measuring pressure'], correctIndex: 0, explanation: 'The Schrödinger equation describes how the quantum state (wave function) of a system changes over time.' },
  { id: 'p_h25', difficulty: 'hard', question: 'What is Cooper pairing?', options: ['Electron pairs in superconductors', 'Proton-neutron bonds', 'Molecular bonds', 'Photon coupling'], correctIndex: 0, explanation: 'In superconductors, electrons form Cooper pairs that move without resistance through the lattice, mediated by phonons.' },
  { id: 'p_h26', difficulty: 'hard', question: 'What is the Lamb shift?', options: ['Small energy level difference in hydrogen due to quantum electrodynamics', 'Orbital precession', 'Nuclear spin splitting', 'Doppler broadening'], correctIndex: 0, explanation: 'The Lamb shift is a tiny difference in hydrogen energy levels unexplained by the Dirac equation, requiring quantum electrodynamics (QED) for explanation.' },
  { id: 'p_h27', difficulty: 'hard', question: 'What is Cherenkov radiation?', options: ['Light emitted when particles exceed the speed of light in a medium', 'X-ray emission', 'Blackbody radiation', 'Bremsstrahlung'], correctIndex: 0, explanation: 'Cherenkov radiation is emitted when a charged particle travels faster than the phase velocity of light in a dielectric medium.' },
  { id: 'p_h28', difficulty: 'hard', question: 'What is the Josephson effect?', options: ['Supercurrent through a thin insulating barrier between superconductors', 'Normal current in wires', 'Voltage across a capacitor', 'Magnetic flux in a coil'], correctIndex: 0, explanation: 'The Josephson effect allows supercurrent to flow across a thin insulating gap between two superconductors via quantum tunneling of Cooper pairs.' },
  { id: 'p_h29', difficulty: 'hard', question: 'What is the Zeeman effect?', options: ['Splitting of spectral lines in a magnetic field', 'Merging of spectral lines', 'Color change of heated metals', 'Light polarization by crystals'], correctIndex: 0, explanation: 'The Zeeman effect is the splitting of atomic energy levels and spectral lines when an atom is placed in a magnetic field.' },
  { id: 'p_h30', difficulty: 'hard', question: 'What is the Stark effect?', options: ['Splitting of spectral lines in an electric field', 'Magnetic resonance', 'Nuclear decay', 'Thermal expansion'], correctIndex: 0, explanation: 'The Stark effect is the shifting and splitting of spectral lines due to an external electric field applied to an atom or molecule.' },
  { id: 'p_h31', difficulty: 'hard', question: 'What is the spin quantum number?', options: ['Intrinsic angular momentum of a particle', 'Orbital radius', 'Energy level number', 'Magnetic field strength'], correctIndex: 0, explanation: 'Spin is an intrinsic form of angular momentum. Electrons have spin quantum number ±½.' },
  { id: 'p_h32', difficulty: 'hard', question: 'What is the Aharonov-Bohm effect?', options: ['Charged particles affected by electromagnetic potentials even with zero fields', 'Gravitational lensing', 'Doppler shift', 'Thermal radiation'], correctIndex: 0, explanation: 'The Aharonov-Bohm effect shows that electromagnetic potentials (not just fields) have physical significance in quantum mechanics.' },
  { id: 'p_h33', difficulty: 'hard', question: 'What is Bremsstrahlung radiation?', options: ['Radiation emitted when a charged particle decelerates', 'Nuclear gamma emission', 'Thermal infrared', 'Reflected sunlight'], correctIndex: 0, explanation: 'Bremsstrahlung ("braking radiation") is emitted when charged particles (usually electrons) are decelerated by other charged particles.' },
  { id: 'p_h34', difficulty: 'hard', question: 'What is the fine structure constant?', options: ['Dimensionless constant characterizing electromagnetic interaction strength', 'Speed of light', 'Gravitational constant', 'Planck length'], correctIndex: 0, explanation: 'The fine structure constant α ≈ 1/137 characterizes the strength of the electromagnetic force between elementary charged particles.' },
  { id: 'p_h35', difficulty: 'hard', question: 'What is a Bose-Einstein condensate?', options: ['State of matter at near absolute zero where particles occupy the same quantum state', 'Hot plasma', 'Supercooled liquid', 'Dense crystal'], correctIndex: 0, explanation: 'A BEC forms when bosons are cooled to near absolute zero and a large fraction collapse into the lowest quantum state.' },
  { id: 'p_h36', difficulty: 'hard', question: 'What is the Casimir effect?', options: ['Attractive force between two uncharged parallel plates from quantum vacuum fluctuations', 'Magnetic repulsion', 'Gravitational attraction', 'Static electricity'], correctIndex: 0, explanation: 'The Casimir effect arises from quantum vacuum fluctuations creating a measurable force between two closely spaced uncharged conducting plates.' },
  { id: 'p_h37', difficulty: 'hard', question: 'What is the second law of thermodynamics?', options: ['Entropy of an isolated system never decreases', 'Energy is conserved', 'Pressure is constant', 'Temperature is absolute'], correctIndex: 0, explanation: 'The second law states that the total entropy of an isolated system can only increase or stay the same over time.' },
  { id: 'p_h38', difficulty: 'hard', question: 'What is the Chandrasekhar limit?', options: ['Maximum mass of a stable white dwarf star (~1.4 solar masses)', 'Speed of light limit', 'Maximum black hole size', 'Minimum star mass'], correctIndex: 0, explanation: 'The Chandrasekhar limit (~1.4 M☉) is the maximum mass a white dwarf can have before collapsing into a neutron star or black hole.' },
  { id: 'p_h39', difficulty: 'hard', question: 'What is renormalization in quantum field theory?', options: ['Technique to remove infinities from calculations', 'Normalizing wave functions', 'Balancing equations', 'Calibrating instruments'], correctIndex: 0, explanation: 'Renormalization is a mathematical procedure in QFT that absorbs infinite quantities into redefined physical parameters to yield finite predictions.' },
  { id: 'p_h40', difficulty: 'hard', question: 'What is spontaneous symmetry breaking?', options: ['A system\'s ground state has less symmetry than its equations', 'All symmetries are preserved', 'Crystals forming randomly', 'Nuclear decay'], correctIndex: 0, explanation: 'Spontaneous symmetry breaking occurs when a system\'s lowest energy state doesn\'t share the full symmetry of the underlying laws, key to the Higgs mechanism.' },
  { id: 'p_h41', difficulty: 'hard', question: 'What is the Dirac equation?', options: ['Relativistic wave equation for spin-½ particles', 'Classical wave equation', 'Thermodynamic equation', 'Fluid dynamics equation'], correctIndex: 0, explanation: 'The Dirac equation combines quantum mechanics and special relativity to describe particles like electrons, predicting antimatter.' },
  { id: 'p_h42', difficulty: 'hard', question: 'What is the Schwinger effect?', options: ['Pair creation from vacuum in a strong electric field', 'Magnetic monopole detection', 'Gravitational wave emission', 'Nuclear fission'], correctIndex: 0, explanation: 'The Schwinger effect predicts that sufficiently strong electric fields can create electron-positron pairs from the quantum vacuum.' },
  { id: 'p_h43', difficulty: 'hard', question: 'What is the Unruh effect?', options: ['An accelerating observer detects thermal radiation from vacuum', 'Sound amplification', 'Light absorption', 'Magnetic induction'], correctIndex: 0, explanation: 'The Unruh effect predicts that a uniformly accelerating observer perceives the vacuum as a warm bath of thermal particles.' },
  { id: 'p_h44', difficulty: 'hard', question: 'What is topological order in condensed matter?', options: ['Quantum order not described by symmetry breaking', 'Crystal lattice arrangement', 'Thermal conductivity order', 'Magnetic domain alignment'], correctIndex: 0, explanation: 'Topological order describes phases of matter characterized by topological properties rather than local order parameters or symmetry breaking.' },
  { id: 'p_h45', difficulty: 'hard', question: 'What is the Berry phase?', options: ['Geometric phase acquired during adiabatic cyclic evolution', 'Phase of moon', 'Chemical reaction phase', 'Electromagnetic phase shift'], correctIndex: 0, explanation: 'The Berry phase is a geometric phase acquired by a quantum system\'s wave function when parameters are slowly varied in a cycle.' },
  { id: 'p_h46', difficulty: 'hard', question: 'What is the Kondo effect?', options: ['Anomalous increase in resistivity at low temperatures from magnetic impurities', 'Superconductivity', 'Normal resistance', 'Thermal expansion'], correctIndex: 0, explanation: 'The Kondo effect causes a minimum in electrical resistivity at low temperatures due to scattering of conduction electrons off magnetic impurities.' },
  { id: 'p_h47', difficulty: 'hard', question: 'What is the quantum Hall effect?', options: ['Quantized Hall conductance in 2D electron systems under strong magnetic fields', 'Classical Hall voltage', 'Thermal Hall effect', 'Magnetic levitation'], correctIndex: 0, explanation: 'The quantum Hall effect shows that Hall conductance is quantized in integer multiples of e²/h in 2D electron systems at low temperatures and high magnetic fields.' },
  { id: 'p_h48', difficulty: 'hard', question: 'What is the Kerr effect?', options: ['Change in refractive index proportional to applied electric field squared', 'Magnetic rotation', 'Thermal lensing', 'Sound amplification'], correctIndex: 0, explanation: 'The Kerr effect (quadratic electro-optic effect) changes a material\'s refractive index proportionally to the square of the applied electric field.' },
  { id: 'p_h49', difficulty: 'hard', question: 'What is the Raman effect?', options: ['Inelastic scattering of light with change in photon energy', 'Elastic scattering only', 'Light absorption', 'Fluorescence'], correctIndex: 0, explanation: 'Raman scattering involves inelastic scattering where photons exchange energy with molecular vibrations, shifting their frequency.' },
  { id: 'p_h50', difficulty: 'hard', question: 'What are anyons?', options: ['Quasiparticles in 2D with fractional statistics', 'Types of ions', 'Nuclear particles', 'Photon variants'], correctIndex: 0, explanation: 'Anyons are quasiparticles existing in two-dimensional systems that obey fractional statistics, neither bosonic nor fermionic.' },
];

// ══════════════════════════════════════════════════════════════
// CHEMISTRY — 150 unique questions (50 easy, 50 medium, 50 hard)
// ══════════════════════════════════════════════════════════════
const chemistryPool: Question[] = [
  // ── EASY (50) ──
  { id: 'c_e1', difficulty: 'easy', question: 'What is the chemical symbol for water?', options: ['HO', 'H₂O', 'H₂O₂', 'OH'], correctIndex: 1, explanation: 'Water (H₂O) consists of two hydrogen atoms bonded to one oxygen atom.' },
  { id: 'c_e2', difficulty: 'easy', question: 'How many elements are in the periodic table (as of 2024)?', options: ['112', '118', '120', '108'], correctIndex: 1, explanation: 'The periodic table contains 118 confirmed elements as of 2024.' },
  { id: 'c_e3', difficulty: 'easy', question: 'What gas do plants absorb from the atmosphere?', options: ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Hydrogen'], correctIndex: 2, explanation: 'Plants absorb CO₂ during photosynthesis and convert it to glucose and oxygen.' },
  { id: 'c_e4', difficulty: 'easy', question: 'What is the pH of pure water?', options: ['5', '7', '9', '14'], correctIndex: 1, explanation: 'Pure water has a neutral pH of 7, meaning equal concentrations of H⁺ and OH⁻ ions.' },
  { id: 'c_e5', difficulty: 'easy', question: 'What is the lightest element?', options: ['Helium', 'Lithium', 'Hydrogen', 'Carbon'], correctIndex: 2, explanation: 'Hydrogen is the lightest element with atomic number 1 and atomic mass ~1.008 u.' },
  { id: 'c_e6', difficulty: 'easy', question: 'What bond involves sharing electrons?', options: ['Ionic', 'Covalent', 'Metallic', 'Hydrogen'], correctIndex: 1, explanation: 'Covalent bonds form when atoms share electron pairs to achieve stable electron configurations.' },
  { id: 'c_e7', difficulty: 'easy', question: 'What is the atomic number of carbon?', options: ['4', '6', '8', '12'], correctIndex: 1, explanation: 'Carbon has atomic number 6, meaning it has 6 protons in its nucleus.' },
  { id: 'c_e8', difficulty: 'easy', question: 'Which acid is found in vinegar?', options: ['Citric acid', 'Acetic acid', 'Sulfuric acid', 'Lactic acid'], correctIndex: 1, explanation: 'Vinegar contains about 5-8% acetic acid (CH₃COOH).' },
  { id: 'c_e9', difficulty: 'easy', question: 'Most abundant element in Earth\'s crust?', options: ['Iron', 'Silicon', 'Oxygen', 'Aluminum'], correctIndex: 2, explanation: 'Oxygen makes up about 46% of Earth\'s crust by mass, mostly in oxide and silicate minerals.' },
  { id: 'c_e10', difficulty: 'easy', question: 'Rust is iron reacting with:', options: ['Nitrogen', 'Carbon dioxide', 'Oxygen and water', 'Helium'], correctIndex: 2, explanation: 'Rust (iron oxide) forms when iron reacts with oxygen and moisture: 4Fe + 3O₂ + 6H₂O → 4Fe(OH)₃.' },
  { id: 'c_e11', difficulty: 'easy', question: 'Which noble gas is used in neon signs?', options: ['Helium', 'Argon', 'Neon', 'Krypton'], correctIndex: 2, explanation: 'Neon gas produces a characteristic red-orange glow when electrically excited in glass tubes.' },
  { id: 'c_e12', difficulty: 'easy', question: 'What process describes a solid turning directly to gas?', options: ['Evaporation', 'Sublimation', 'Condensation', 'Deposition'], correctIndex: 1, explanation: 'Sublimation is the transition from solid to gas without passing through the liquid phase (e.g., dry ice).' },
  { id: 'c_e13', difficulty: 'easy', question: 'Diamond and graphite are both made of:', options: ['Silicon', 'Carbon', 'Iron', 'Sulfur'], correctIndex: 1, explanation: 'Diamond and graphite are allotropes of carbon with different crystal structures and properties.' },
  { id: 'c_e14', difficulty: 'easy', question: 'Which metal is liquid at room temperature?', options: ['Lead', 'Tin', 'Mercury', 'Gallium'], correctIndex: 2, explanation: 'Mercury (Hg) has a melting point of -38.83°C, making it liquid at room temperature.' },
  { id: 'c_e15', difficulty: 'easy', question: 'What is the chemical formula for table salt?', options: ['NaOH', 'NaCl', 'KCl', 'CaCl₂'], correctIndex: 1, explanation: 'Table salt is sodium chloride (NaCl), an ionic compound of sodium and chlorine.' },
  { id: 'c_e16', difficulty: 'easy', question: 'What state of matter does ice represent?', options: ['Liquid', 'Gas', 'Solid', 'Plasma'], correctIndex: 2, explanation: 'Ice is the solid state of water, formed when water freezes at 0°C.' },
  { id: 'c_e17', difficulty: 'easy', question: 'What is the symbol for gold?', options: ['Go', 'Gd', 'Au', 'Ag'], correctIndex: 2, explanation: 'Gold\'s symbol Au comes from the Latin word "aurum."' },
  { id: 'c_e18', difficulty: 'easy', question: 'What gas makes soda fizzy?', options: ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Helium'], correctIndex: 2, explanation: 'Carbon dioxide (CO₂) dissolved under pressure creates the fizzy bubbles in carbonated drinks.' },
  { id: 'c_e19', difficulty: 'easy', question: 'What is the most abundant gas in Earth\'s atmosphere?', options: ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Argon'], correctIndex: 2, explanation: 'Nitrogen (N₂) makes up about 78% of Earth\'s atmosphere by volume.' },
  { id: 'c_e20', difficulty: 'easy', question: 'What color does litmus paper turn in acid?', options: ['Blue', 'Red', 'Green', 'Yellow'], correctIndex: 1, explanation: 'Blue litmus paper turns red in acidic solutions (pH < 7).' },
  { id: 'c_e21', difficulty: 'easy', question: 'What is the chemical formula for carbon dioxide?', options: ['CO', 'CO₂', 'C₂O', 'CO₃'], correctIndex: 1, explanation: 'Carbon dioxide (CO₂) has one carbon atom double-bonded to two oxygen atoms.' },
  { id: 'c_e22', difficulty: 'easy', question: 'What is an atom?', options: ['Smallest unit of an element', 'A molecule', 'A compound', 'An ion'], correctIndex: 0, explanation: 'An atom is the smallest unit of a chemical element that retains the element\'s properties.' },
  { id: 'c_e23', difficulty: 'easy', question: 'What is the symbol for sodium?', options: ['So', 'Sd', 'Na', 'S'], correctIndex: 2, explanation: 'Sodium\'s symbol Na comes from the Latin "natrium."' },
  { id: 'c_e24', difficulty: 'easy', question: 'How many protons does hydrogen have?', options: ['0', '1', '2', '3'], correctIndex: 1, explanation: 'Hydrogen has atomic number 1, meaning it has exactly one proton.' },
  { id: 'c_e25', difficulty: 'easy', question: 'What is the chemical formula for methane?', options: ['CH₃', 'CH₄', 'C₂H₆', 'C₂H₄'], correctIndex: 1, explanation: 'Methane (CH₄) is the simplest hydrocarbon with one carbon bonded to four hydrogen atoms.' },
  { id: 'c_e26', difficulty: 'easy', question: 'What particle is found in the nucleus with protons?', options: ['Electrons', 'Neutrons', 'Photons', 'Positrons'], correctIndex: 1, explanation: 'Neutrons are electrically neutral particles found alongside protons in the atomic nucleus.' },
  { id: 'c_e27', difficulty: 'easy', question: 'What is the chemical formula for oxygen gas?', options: ['O', 'O₂', 'O₃', 'O₄'], correctIndex: 1, explanation: 'Oxygen gas exists as a diatomic molecule (O₂) under standard conditions.' },
  { id: 'c_e28', difficulty: 'easy', question: 'Which group contains the halogens?', options: ['Group 1', 'Group 7/17', 'Group 18', 'Group 2'], correctIndex: 1, explanation: 'Halogens (F, Cl, Br, I, At) are in Group 17 (or Group VII) of the periodic table.' },
  { id: 'c_e29', difficulty: 'easy', question: 'What is the valency of hydrogen?', options: ['0', '1', '2', '3'], correctIndex: 1, explanation: 'Hydrogen has a valency of 1, meaning it can form one chemical bond.' },
  { id: 'c_e30', difficulty: 'easy', question: 'What is a mixture?', options: ['Two or more substances physically combined', 'A pure element', 'A single compound', 'A type of bond'], correctIndex: 0, explanation: 'A mixture contains two or more substances that are not chemically bonded and can be separated by physical means.' },
  { id: 'c_e31', difficulty: 'easy', question: 'What is the atomic number of oxygen?', options: ['6', '7', '8', '16'], correctIndex: 2, explanation: 'Oxygen has atomic number 8, meaning it has 8 protons.' },
  { id: 'c_e32', difficulty: 'easy', question: 'What is distillation used for?', options: ['Separating liquids by boiling points', 'Breaking bonds', 'Creating compounds', 'Measuring pH'], correctIndex: 0, explanation: 'Distillation separates liquid mixtures based on differences in boiling points through evaporation and condensation.' },
  { id: 'c_e33', difficulty: 'easy', question: 'What type of substance has a pH greater than 7?', options: ['Acid', 'Base/Alkali', 'Neutral', 'Salt'], correctIndex: 1, explanation: 'Bases (alkalis) have pH greater than 7. The higher the pH, the more basic the substance.' },
  { id: 'c_e34', difficulty: 'easy', question: 'What is the symbol for iron?', options: ['Ir', 'In', 'Fe', 'Fr'], correctIndex: 2, explanation: 'Iron\'s symbol Fe comes from the Latin "ferrum."' },
  { id: 'c_e35', difficulty: 'easy', question: 'What is evaporation?', options: ['Liquid to gas at the surface', 'Gas to liquid', 'Solid to liquid', 'Gas to solid'], correctIndex: 0, explanation: 'Evaporation is the process where liquid molecules at the surface gain enough energy to escape into the gas phase.' },
  { id: 'c_e36', difficulty: 'easy', question: 'What is the chemical formula for ammonia?', options: ['NH₂', 'NH₃', 'NH₄', 'N₂H₄'], correctIndex: 1, explanation: 'Ammonia (NH₃) consists of one nitrogen atom bonded to three hydrogen atoms.' },
  { id: 'c_e37', difficulty: 'easy', question: 'What are the alkali metals?', options: ['Group 1 elements', 'Group 18 elements', 'Transition metals', 'Halogens'], correctIndex: 0, explanation: 'Alkali metals (Li, Na, K, Rb, Cs, Fr) are in Group 1, known for being highly reactive.' },
  { id: 'c_e38', difficulty: 'easy', question: 'What happens in a chemical reaction?', options: ['New substances are formed', 'Color changes only', 'Nothing changes', 'Only temperature changes'], correctIndex: 0, explanation: 'In a chemical reaction, bonds break and new bonds form, creating different substances with new properties.' },
  { id: 'c_e39', difficulty: 'easy', question: 'What is the symbol for potassium?', options: ['Po', 'Pt', 'K', 'P'], correctIndex: 2, explanation: 'Potassium\'s symbol K comes from the Latin "kalium."' },
  { id: 'c_e40', difficulty: 'easy', question: 'Which element is essential for combustion?', options: ['Nitrogen', 'Hydrogen', 'Oxygen', 'Helium'], correctIndex: 2, explanation: 'Oxygen is required as an oxidizer for combustion reactions to occur.' },
  { id: 'c_e41', difficulty: 'easy', question: 'What is the main component of natural gas?', options: ['Ethane', 'Propane', 'Methane', 'Butane'], correctIndex: 2, explanation: 'Natural gas is primarily methane (CH₄), typically 70-90% by volume.' },
  { id: 'c_e42', difficulty: 'easy', question: 'What is the chemical formula for sulfuric acid?', options: ['HCl', 'H₂SO₄', 'HNO₃', 'H₃PO₄'], correctIndex: 1, explanation: 'Sulfuric acid (H₂SO₄) is a strong diprotic acid widely used in industry.' },
  { id: 'c_e43', difficulty: 'easy', question: 'What is a compound?', options: ['Two or more elements chemically combined', 'A single element', 'A physical mixture', 'An electron'], correctIndex: 0, explanation: 'A compound is a substance made of two or more different elements chemically bonded in a fixed ratio.' },
  { id: 'c_e44', difficulty: 'easy', question: 'What does "H" represent on the periodic table?', options: ['Helium', 'Hafnium', 'Hydrogen', 'Holmium'], correctIndex: 2, explanation: 'H is the symbol for hydrogen, the first element on the periodic table.' },
  { id: 'c_e45', difficulty: 'easy', question: 'What is condensation?', options: ['Gas to liquid', 'Liquid to gas', 'Solid to gas', 'Gas to solid'], correctIndex: 0, explanation: 'Condensation is when gas molecules lose energy and transition to the liquid state.' },
  { id: 'c_e46', difficulty: 'easy', question: 'What is the symbol for silver?', options: ['Si', 'Sv', 'Ag', 'Sr'], correctIndex: 2, explanation: 'Silver\'s symbol Ag comes from the Latin "argentum."' },
  { id: 'c_e47', difficulty: 'easy', question: 'What is the main gas in the Sun?', options: ['Oxygen', 'Hydrogen', 'Helium', 'Nitrogen'], correctIndex: 1, explanation: 'The Sun is approximately 75% hydrogen by mass, which fuels its nuclear fusion reactions.' },
  { id: 'c_e48', difficulty: 'easy', question: 'What is a proton\'s charge?', options: ['Negative', 'Positive', 'Neutral', 'Variable'], correctIndex: 1, explanation: 'Protons carry a positive electric charge of +1.6 × 10⁻¹⁹ coulombs.' },
  { id: 'c_e49', difficulty: 'easy', question: 'What is the freezing point of water in Celsius?', options: ['-10°C', '0°C', '10°C', '100°C'], correctIndex: 1, explanation: 'Water freezes at 0°C (32°F, 273.15 K) at standard atmospheric pressure.' },
  { id: 'c_e50', difficulty: 'easy', question: 'What type of reaction produces water and a salt?', options: ['Combustion', 'Decomposition', 'Neutralization', 'Synthesis'], correctIndex: 2, explanation: 'Neutralization reactions between acids and bases produce water and a salt: Acid + Base → Salt + Water.' },

  // ── MEDIUM (50) ──
  { id: 'c_m1', difficulty: 'medium', question: "What is Avogadro's number?", options: ['6.022 × 10²³', '3.14 × 10²³', '6.022 × 10²⁶', '9.81 × 10²³'], correctIndex: 0, explanation: 'Avogadro\'s number (6.022 × 10²³) is the number of particles in one mole of a substance.' },
  { id: 'c_m2', difficulty: 'medium', question: 'What is an isotope?', options: ['Same protons, different neutrons', 'Same neutrons, different protons', 'Same electrons', 'Different element'], correctIndex: 0, explanation: 'Isotopes are atoms of the same element with the same number of protons but different numbers of neutrons.' },
  { id: 'c_m3', difficulty: 'medium', question: 'What is the formula for glucose?', options: ['C₆H₁₂O₆', 'C₂H₆O', 'CH₄', 'C₆H₆'], correctIndex: 0, explanation: 'Glucose (C₆H₁₂O₆) is a simple sugar and primary energy source for cells.' },
  { id: 'c_m4', difficulty: 'medium', question: 'What is an exothermic reaction?', options: ['Releases heat', 'Absorbs heat', 'No energy change', 'Produces light only'], correctIndex: 0, explanation: 'Exothermic reactions release energy (usually as heat) to the surroundings, making the surroundings warmer.' },
  { id: 'c_m5', difficulty: 'medium', question: 'What does a catalyst do?', options: ['Speeds up reaction without being consumed', 'Slows reaction', 'Stops reaction', 'Is consumed in reaction'], correctIndex: 0, explanation: 'A catalyst lowers the activation energy of a reaction, increasing its rate without being permanently consumed.' },
  { id: 'c_m6', difficulty: 'medium', question: 'What is the valency of oxygen?', options: ['1', '2', '3', '4'], correctIndex: 1, explanation: 'Oxygen has a valency of 2, meaning it forms two bonds to complete its octet.' },
  { id: 'c_m7', difficulty: 'medium', question: 'What type of reaction is combustion?', options: ['Exothermic oxidation', 'Endothermic reduction', 'Neutralization', 'Decomposition'], correctIndex: 0, explanation: 'Combustion is a rapid exothermic oxidation reaction, typically involving a fuel and oxygen.' },
  { id: 'c_m8', difficulty: 'medium', question: 'What is an electrolyte?', options: ['Substance that conducts electricity in solution', 'Insulator', 'Pure metal', 'Noble gas'], correctIndex: 0, explanation: 'Electrolytes dissociate into ions when dissolved, allowing the solution to conduct electricity.' },
  { id: 'c_m9', difficulty: 'medium', question: 'What is the molar mass of CO₂?', options: ['28 g/mol', '32 g/mol', '44 g/mol', '18 g/mol'], correctIndex: 2, explanation: 'CO₂ molar mass = 12 (C) + 2 × 16 (O) = 44 g/mol.' },
  { id: 'c_m10', difficulty: 'medium', question: 'Which element has the symbol Fe?', options: ['Fluorine', 'Iron', 'Francium', 'Fermium'], correctIndex: 1, explanation: 'Fe is the symbol for iron, from the Latin "ferrum."' },
  { id: 'c_m11', difficulty: 'medium', question: 'What is a polymer?', options: ['Long chain of repeating monomer units', 'Single atom', 'An ion', 'An isotope'], correctIndex: 0, explanation: 'Polymers are large molecules made of many repeating smaller units (monomers) linked together.' },
  { id: 'c_m12', difficulty: 'medium', question: 'What is a redox reaction?', options: ['Involves transfer of electrons', 'Transfer of protons only', 'Transfer of neutrons', 'No particle transfer'], correctIndex: 0, explanation: 'Redox reactions involve simultaneous oxidation (electron loss) and reduction (electron gain).' },
  { id: 'c_m13', difficulty: 'medium', question: 'What is molarity?', options: ['Moles of solute per liter of solution', 'Grams per liter', 'Moles per kilogram', 'Mass percentage'], correctIndex: 0, explanation: 'Molarity (M) = moles of solute ÷ liters of solution. It\'s a common concentration unit.' },
  { id: 'c_m14', difficulty: 'medium', question: 'What is the octet rule?', options: ['Atoms tend to have 8 electrons in outer shell', '8 protons in nucleus', '8 neutrons required', '8 bonds maximum'], correctIndex: 0, explanation: 'The octet rule states that atoms tend to gain, lose, or share electrons to achieve 8 electrons in their valence shell.' },
  { id: 'c_m15', difficulty: 'medium', question: 'What is electronegativity?', options: ['Atom\'s ability to attract bonding electrons', 'Repulsion of protons', 'Atomic size', 'Ionization energy'], correctIndex: 0, explanation: 'Electronegativity measures how strongly an atom attracts the shared electrons in a chemical bond.' },
  { id: 'c_m16', difficulty: 'medium', question: 'What is the rate of a chemical reaction affected by?', options: ['Temperature, concentration, surface area, and catalyst', 'Color only', 'Mass only', 'Volume only'], correctIndex: 0, explanation: 'Reaction rate increases with higher temperature, concentration, surface area, and the presence of a catalyst.' },
  { id: 'c_m17', difficulty: 'medium', question: 'What is an endothermic reaction?', options: ['Absorbs heat from surroundings', 'Releases heat', 'No energy change', 'Produces only light'], correctIndex: 0, explanation: 'Endothermic reactions absorb energy from the surroundings, making the surroundings cooler.' },
  { id: 'c_m18', difficulty: 'medium', question: 'What is the law of conservation of mass?', options: ['Mass is neither created nor destroyed in a reaction', 'Mass always increases', 'Mass decreases', 'Mass converts to energy'], correctIndex: 0, explanation: 'In a chemical reaction, the total mass of reactants equals the total mass of products.' },
  { id: 'c_m19', difficulty: 'medium', question: 'What is a saturated solution?', options: ['Contains maximum dissolved solute at a given temperature', 'Has no solute', 'Is always hot', 'Is always cold'], correctIndex: 0, explanation: 'A saturated solution holds the maximum amount of solute that can dissolve at a specific temperature.' },
  { id: 'c_m20', difficulty: 'medium', question: 'What is an ionic bond?', options: ['Bond formed by transfer of electrons', 'Sharing of electrons', 'Metallic bonding', 'Van der Waals forces'], correctIndex: 0, explanation: 'Ionic bonds form when one atom transfers electrons to another, creating oppositely charged ions that attract.' },
  { id: 'c_m21', difficulty: 'medium', question: 'What is the pH scale range?', options: ['0 to 14', '1 to 10', '0 to 7', '-7 to 7'], correctIndex: 0, explanation: 'The pH scale typically ranges from 0 (most acidic) to 14 (most basic), with 7 being neutral.' },
  { id: 'c_m22', difficulty: 'medium', question: 'What is the electron configuration of sodium (Na)?', options: ['2, 8, 1', '2, 8, 2', '2, 7', '2, 8, 8'], correctIndex: 0, explanation: 'Sodium (atomic number 11) has electrons arranged as 2, 8, 1 across three shells.' },
  { id: 'c_m23', difficulty: 'medium', question: 'What is a precipitation reaction?', options: ['Formation of an insoluble solid from mixing solutions', 'Gas evolution', 'Color change only', 'Temperature change only'], correctIndex: 0, explanation: 'A precipitation reaction produces an insoluble solid (precipitate) when two aqueous solutions are mixed.' },
  { id: 'c_m24', difficulty: 'medium', question: 'What is activation energy?', options: ['Minimum energy needed to start a reaction', 'Total energy released', 'Energy of products', 'Energy stored in bonds'], correctIndex: 0, explanation: 'Activation energy is the minimum energy that reactant molecules must have for a reaction to occur.' },
  { id: 'c_m25', difficulty: 'medium', question: 'What is a cation?', options: ['Positively charged ion', 'Negatively charged ion', 'Neutral atom', 'A molecule'], correctIndex: 0, explanation: 'A cation is a positively charged ion formed when an atom loses one or more electrons.' },
  { id: 'c_m26', difficulty: 'medium', question: 'What does the term "mole" represent in chemistry?', options: ['6.022 × 10²³ particles', 'A unit of volume', 'A type of bond', 'A measurement of temperature'], correctIndex: 0, explanation: 'A mole is a quantity equal to 6.022 × 10²³ particles (atoms, molecules, ions, etc.).' },
  { id: 'c_m27', difficulty: 'medium', question: 'What is an alloy?', options: ['Mixture of metals', 'Pure element', 'A compound', 'A noble gas'], correctIndex: 0, explanation: 'An alloy is a mixture of two or more metals (or a metal with non-metals), like steel (iron + carbon).' },
  { id: 'c_m28', difficulty: 'medium', question: 'What is enthalpy?', options: ['Total heat content of a system at constant pressure', 'Volume of a gas', 'Mass of reactants', 'Speed of reaction'], correctIndex: 0, explanation: 'Enthalpy (H) is a thermodynamic quantity representing the total heat content of a system at constant pressure.' },
  { id: 'c_m29', difficulty: 'medium', question: 'What is the difference between organic and inorganic chemistry?', options: ['Organic studies carbon-based compounds; inorganic studies non-carbon compounds', 'They are the same', 'Organic is newer', 'Inorganic involves only metals'], correctIndex: 0, explanation: 'Organic chemistry focuses on carbon-containing compounds; inorganic chemistry deals with non-carbon compounds and some simple carbon compounds.' },
  { id: 'c_m30', difficulty: 'medium', question: 'What is a Lewis structure?', options: ['Diagram showing electron pairs around atoms', 'Atomic mass chart', 'Periodic table section', 'Reaction mechanism'], correctIndex: 0, explanation: 'Lewis structures are diagrams that show the bonding and lone pair electrons in molecules.' },
  { id: 'c_m31', difficulty: 'medium', question: 'What is the ideal gas law?', options: ['PV = nRT', 'PV = mgh', 'E = mc²', 'F = ma'], correctIndex: 0, explanation: 'The ideal gas law PV = nRT relates pressure, volume, amount (moles), and temperature of an ideal gas.' },
  { id: 'c_m32', difficulty: 'medium', question: 'What is a disproportionation reaction?', options: ['Same element is both oxidized and reduced', 'Two elements combine', 'Acid meets base', 'Gas is produced'], correctIndex: 0, explanation: 'In disproportionation, a single element in one oxidation state is simultaneously oxidized and reduced.' },
  { id: 'c_m33', difficulty: 'medium', question: 'What is the Haber process used for?', options: ['Industrial synthesis of ammonia', 'Making sulfuric acid', 'Refining oil', 'Producing electricity'], correctIndex: 0, explanation: 'The Haber process combines nitrogen and hydrogen at high temperature and pressure with a catalyst to produce ammonia: N₂ + 3H₂ ⇌ 2NH₃.' },
  { id: 'c_m34', difficulty: 'medium', question: 'What is an anion?', options: ['Negatively charged ion', 'Positively charged ion', 'Neutral atom', 'A proton'], correctIndex: 0, explanation: 'An anion is a negatively charged ion formed when an atom gains one or more electrons.' },
  { id: 'c_m35', difficulty: 'medium', question: 'What is the empirical formula?', options: ['Simplest whole number ratio of atoms in a compound', 'Exact number of atoms', 'Molecular weight', 'Structural formula'], correctIndex: 0, explanation: 'The empirical formula gives the simplest integer ratio of atoms of each element in a compound.' },
  { id: 'c_m36', difficulty: 'medium', question: 'What is Dalton\'s law of partial pressures?', options: ['Total pressure equals sum of partial pressures', 'Pressure is inversely proportional to volume', 'Gas expands when heated', 'Pressure equals force per area'], correctIndex: 0, explanation: 'Dalton\'s law states that the total pressure of a gas mixture equals the sum of the partial pressures of each gas.' },
  { id: 'c_m37', difficulty: 'medium', question: 'What is a functional group?', options: ['Specific atom group that determines chemical properties', 'A periodic table group', 'A type of bond', 'A classification of elements'], correctIndex: 0, explanation: 'Functional groups are specific arrangements of atoms within molecules that determine the molecules\' chemical properties.' },
  { id: 'c_m38', difficulty: 'medium', question: 'What is the difference between a strong and weak acid?', options: ['Strong acids fully dissociate; weak acids partially dissociate', 'Strong acids are more concentrated', 'Weak acids are dilute', 'No difference'], correctIndex: 0, explanation: 'Strong acids completely dissociate into ions in solution; weak acids only partially ionize, establishing equilibrium.' },
  { id: 'c_m39', difficulty: 'medium', question: 'What is Charles\'s Law?', options: ['Volume is proportional to temperature at constant pressure', 'Pressure is proportional to temperature', 'Volume is inversely proportional to pressure', 'PV = nRT'], correctIndex: 0, explanation: 'Charles\'s Law states that the volume of a gas is directly proportional to its absolute temperature at constant pressure: V/T = constant.' },
  { id: 'c_m40', difficulty: 'medium', question: 'What is Boyle\'s Law?', options: ['Pressure is inversely proportional to volume at constant temperature', 'Volume increases with temperature', 'Pressure equals force over area', 'Gas expands freely'], correctIndex: 0, explanation: 'Boyle\'s Law: at constant temperature, the pressure and volume of a gas are inversely proportional: PV = constant.' },
  { id: 'c_m41', difficulty: 'medium', question: 'What is the purpose of a titration?', options: ['Determine the concentration of an unknown solution', 'Measure temperature', 'Find density', 'Test conductivity'], correctIndex: 0, explanation: 'Titration is a technique where a solution of known concentration is used to determine the concentration of an unknown solution.' },
  { id: 'c_m42', difficulty: 'medium', question: 'What is a coordinate (dative) bond?', options: ['Both shared electrons come from the same atom', 'Electrons are transferred', 'No electrons are shared', 'Bonds break immediately'], correctIndex: 0, explanation: 'In a coordinate bond, both electrons in the shared pair are donated by the same atom.' },
  { id: 'c_m43', difficulty: 'medium', question: 'What is the Aufbau principle?', options: ['Electrons fill lowest energy orbitals first', 'Electrons fill highest first', 'All orbitals fill equally', 'Electrons skip orbitals'], correctIndex: 0, explanation: 'The Aufbau principle states that electrons occupy the lowest available energy orbitals before filling higher ones.' },
  { id: 'c_m44', difficulty: 'medium', question: 'What is electroplating?', options: ['Coating an object with metal using electrolysis', 'Melting metals', 'Mixing alloys', 'Heating metals'], correctIndex: 0, explanation: 'Electroplating uses electrolysis to deposit a thin layer of metal onto a conductive surface.' },
  { id: 'c_m45', difficulty: 'medium', question: 'What is Hund\'s rule?', options: ['Electrons occupy orbitals singly before pairing', 'Electrons always pair up', 'Electrons avoid orbitals', 'Electrons fill from top'], correctIndex: 0, explanation: 'Hund\'s rule states that electrons fill degenerate orbitals singly with parallel spins before pairing up.' },
  { id: 'c_m46', difficulty: 'medium', question: 'What is a displacement reaction?', options: ['More reactive element replaces less reactive one', 'Two compounds exchange ions', 'Decomposition occurs', 'Synthesis occurs'], correctIndex: 0, explanation: 'In displacement reactions, a more reactive element displaces a less reactive element from its compound.' },
  { id: 'c_m47', difficulty: 'medium', question: 'What is the relationship between pressure and temperature for a gas at constant volume?', options: ['Directly proportional (Gay-Lussac\'s Law)', 'Inversely proportional', 'No relationship', 'Exponential'], correctIndex: 0, explanation: 'Gay-Lussac\'s Law states that pressure is directly proportional to absolute temperature at constant volume: P/T = constant.' },
  { id: 'c_m48', difficulty: 'medium', question: 'What is a half-equation?', options: ['Shows either oxidation or reduction part of a redox reaction', 'Half a balanced equation', 'Incomplete reaction', 'Theoretical equation'], correctIndex: 0, explanation: 'Half-equations show the electron transfer in either the oxidation or reduction part of a redox reaction separately.' },
  { id: 'c_m49', difficulty: 'medium', question: 'What is collision theory?', options: ['Reactions occur when particles collide with sufficient energy and correct orientation', 'All collisions cause reactions', 'Particles never collide', 'Only gases collide'], correctIndex: 0, explanation: 'Collision theory states that reactions only occur when particles collide with enough energy (≥ activation energy) and proper orientation.' },
  { id: 'c_m50', difficulty: 'medium', question: 'What is a homologous series?', options: ['Family of compounds with same functional group and general formula', 'Random set of compounds', 'Isomers', 'Allotropes'], correctIndex: 0, explanation: 'A homologous series is a family of organic compounds with the same functional group and similar chemical properties, differing by CH₂.' },

  // ── HARD (50) ──
  { id: 'c_h1', difficulty: 'hard', question: 'What is a buffer solution?', options: ['Resists pH change on adding small amounts of acid/base', 'Always neutral pH', 'Highly acidic', 'Pure water'], correctIndex: 0, explanation: 'Buffer solutions maintain nearly constant pH by containing a weak acid/base and its conjugate, neutralizing added H⁺ or OH⁻.' },
  { id: 'c_h2', difficulty: 'hard', question: "What is Le Chatelier's principle?", options: ['System at equilibrium shifts to oppose applied stress', 'Reactions always go forward', 'Energy is always conserved', 'All reactions are reversible'], correctIndex: 0, explanation: 'Le Chatelier\'s principle states that a system at equilibrium will shift to counteract any change imposed upon it.' },
  { id: 'c_h3', difficulty: 'hard', question: 'What is hybridization in chemistry?', options: ['Mixing of atomic orbitals to form new hybrid orbitals', 'Mixing of elements', 'Nuclear fusion', 'Isomerism'], correctIndex: 0, explanation: 'Hybridization is the concept of mixing atomic orbitals to form new hybrid orbitals suitable for bonding (sp, sp², sp³).' },
  { id: 'c_h4', difficulty: 'hard', question: 'What are lanthanides?', options: ['Rare earth elements (atomic numbers 57-71)', 'Noble gases', 'Halogens', 'Alkali metals'], correctIndex: 0, explanation: 'Lanthanides are the 15 metallic elements from lanthanum (57) to lutetium (71), known as rare earth elements.' },
  { id: 'c_h5', difficulty: 'hard', question: 'What is a coordination compound?', options: ['Central metal ion bonded to ligands', 'Simple ionic compound', 'Covalent only', 'Polymer'], correctIndex: 0, explanation: 'Coordination compounds have a central metal atom/ion surrounded by molecules or ions (ligands) via coordinate bonds.' },
  { id: 'c_h6', difficulty: 'hard', question: 'What is chirality?', options: ['Non-superimposable mirror image property', 'Same structure', 'Isotope variation', 'Allotropy'], correctIndex: 0, explanation: 'A chiral molecule cannot be superimposed on its mirror image, like left and right hands.' },
  { id: 'c_h7', difficulty: 'hard', question: 'What is the Born-Haber cycle?', options: ['Thermodynamic cycle for calculating lattice energy', 'Electron orbital cycle', 'Nuclear reaction cycle', 'Catalytic cycle'], correctIndex: 0, explanation: 'The Born-Haber cycle uses Hess\'s law to calculate lattice energy of ionic compounds from measurable quantities.' },
  { id: 'c_h8', difficulty: 'hard', question: 'What is the Nernst equation used for?', options: ['Calculating electrode potential under non-standard conditions', 'Finding molarity', 'Measuring temperature', 'Determining atomic mass'], correctIndex: 0, explanation: 'The Nernst equation relates electrode potential to standard potential, temperature, and ion concentrations.' },
  { id: 'c_h9', difficulty: 'hard', question: 'What is the Gibbs free energy?', options: ['Energy available to do useful work at constant T and P', 'Total internal energy', 'Kinetic energy', 'Nuclear energy'], correctIndex: 0, explanation: 'Gibbs free energy (G = H - TS) determines reaction spontaneity: ΔG < 0 means spontaneous.' },
  { id: 'c_h10', difficulty: 'hard', question: 'What is the Henderson-Hasselbalch equation used for?', options: ['Calculating pH of buffer solutions', 'Finding boiling points', 'Measuring density', 'Determining molar mass'], correctIndex: 0, explanation: 'The Henderson-Hasselbalch equation: pH = pKa + log([A⁻]/[HA]), used to estimate the pH of buffer solutions.' },
  { id: 'c_h11', difficulty: 'hard', question: 'What is crystal field theory?', options: ['Explains electronic structure of transition metal complexes', 'Crystal growth rates', 'Ionic bond strength', 'Covalent bond angles'], correctIndex: 0, explanation: 'Crystal field theory explains how ligands affect d-orbital energies in transition metal complexes, determining color and magnetism.' },
  { id: 'c_h12', difficulty: 'hard', question: 'What is the Woodward-Hoffmann rules?', options: ['Predicting pericyclic reaction outcomes from orbital symmetry', 'Naming organic compounds', 'Balancing equations', 'Determining pH'], correctIndex: 0, explanation: 'The Woodward-Hoffmann rules use orbital symmetry conservation to predict whether pericyclic reactions occur thermally or photochemically.' },
  { id: 'c_h13', difficulty: 'hard', question: 'What is the Clausius-Clapeyron equation?', options: ['Relates vapor pressure to temperature', 'Calculates molecular weight', 'Determines density', 'Finds atomic radius'], correctIndex: 0, explanation: 'The Clausius-Clapeyron equation describes how vapor pressure of a liquid changes with temperature using the enthalpy of vaporization.' },
  { id: 'c_h14', difficulty: 'hard', question: 'What is a Grignard reagent?', options: ['Organomagnesium halide (RMgX)', 'A type of acid', 'A noble gas', 'An enzyme'], correctIndex: 0, explanation: 'Grignard reagents (RMgX) are organometallic compounds used extensively in organic synthesis for carbon-carbon bond formation.' },
  { id: 'c_h15', difficulty: 'hard', question: 'What is the Raoult\'s law?', options: ['Vapor pressure of a solution equals mole fraction times vapor pressure of pure solvent', 'Pressure equals force over area', 'PV = nRT', 'Boiling point elevation formula'], correctIndex: 0, explanation: 'Raoult\'s law: P = x·P°, where the partial vapor pressure of each component equals its mole fraction times its pure vapor pressure.' },
  { id: 'c_h16', difficulty: 'hard', question: 'What is the Boltzmann distribution?', options: ['Statistical distribution of particle energies at a given temperature', 'Even distribution', 'Linear distribution', 'No distribution'], correctIndex: 0, explanation: 'The Boltzmann distribution describes the probability of particles having various energy levels at thermal equilibrium.' },
  { id: 'c_h17', difficulty: 'hard', question: 'What is the Debye-Hückel theory?', options: ['Describes behavior of electrolyte solutions', 'Explains gas behavior', 'Nuclear theory', 'Bonding theory'], correctIndex: 0, explanation: 'Debye-Hückel theory models how ionic interactions affect the thermodynamic properties of electrolyte solutions.' },
  { id: 'c_h18', difficulty: 'hard', question: 'What is stereoisomerism?', options: ['Same molecular formula and connectivity but different spatial arrangement', 'Different formulas', 'Same arrangement', 'Different elements'], correctIndex: 0, explanation: 'Stereoisomers have identical molecular formulas and atom connectivity but differ in the three-dimensional arrangement of atoms.' },
  { id: 'c_h19', difficulty: 'hard', question: 'What is the transition state theory?', options: ['Reactants pass through a high-energy activated complex', 'Products form instantly', 'No energy barrier exists', 'Only catalysts work'], correctIndex: 0, explanation: 'Transition state theory proposes that reactants must form a high-energy activated complex (transition state) before converting to products.' },
  { id: 'c_h20', difficulty: 'hard', question: 'What is the Jahn-Teller effect?', options: ['Geometric distortion of non-linear molecules to remove degeneracy', 'Linear molecule bending', 'Bond lengthening', 'Orbital merging'], correctIndex: 0, explanation: 'The Jahn-Teller effect causes spontaneous geometric distortion in non-linear molecular systems with orbital degeneracy.' },
  { id: 'c_h21', difficulty: 'hard', question: 'What is the Arrhenius equation?', options: ['k = Ae^(-Ea/RT), relates rate constant to temperature', 'pH = -log[H⁺]', 'PV = nRT', 'E = hf'], correctIndex: 0, explanation: 'The Arrhenius equation shows how the rate constant k increases exponentially with temperature.' },
  { id: 'c_h22', difficulty: 'hard', question: 'What is molecular orbital theory?', options: ['Atomic orbitals combine to form molecular orbitals spanning entire molecule', 'Electrons stay on atoms', 'Only ionic bonds form', 'Orbitals don\'t overlap'], correctIndex: 0, explanation: 'MO theory combines atomic orbitals into bonding and antibonding molecular orbitals that belong to the molecule as a whole.' },
  { id: 'c_h23', difficulty: 'hard', question: 'What is the Friedel-Crafts reaction?', options: ['Electrophilic aromatic substitution using Lewis acid catalyst', 'Nucleophilic addition', 'Free radical reaction', 'Elimination reaction'], correctIndex: 0, explanation: 'Friedel-Crafts reactions are electrophilic aromatic substitutions (alkylation or acylation) catalyzed by Lewis acids like AlCl₃.' },
  { id: 'c_h24', difficulty: 'hard', question: 'What is the Diels-Alder reaction?', options: ['[4+2] cycloaddition between a diene and dienophile', 'Substitution reaction', 'Elimination reaction', 'Oxidation reaction'], correctIndex: 0, explanation: 'The Diels-Alder reaction is a [4+2] cycloaddition forming six-membered rings, widely used in organic synthesis.' },
  { id: 'c_h25', difficulty: 'hard', question: 'What is the Tollens\' test?', options: ['Distinguishes aldehydes from ketones using silver mirror', 'Tests for acids', 'Measures pH', 'Detects halogens'], correctIndex: 0, explanation: 'Tollens\' test uses ammoniacal silver nitrate: aldehydes reduce Ag⁺ to metallic silver (mirror), ketones do not.' },
  { id: 'c_h26', difficulty: 'hard', question: 'What is the Markovnikov rule?', options: ['In addition to alkenes, H adds to carbon with more H atoms', 'H adds to carbon with fewer H atoms', 'Random addition', 'Only applies to alkynes'], correctIndex: 0, explanation: 'Markovnikov\'s rule: in HX addition to alkenes, H adds to the carbon with more hydrogen atoms (forming the more stable carbocation).' },
  { id: 'c_h27', difficulty: 'hard', question: 'What is the Zaitsev rule?', options: ['Elimination favors the more substituted alkene', 'Less substituted alkene forms', 'Equal mixture always', 'Only applies to acids'], correctIndex: 0, explanation: 'Zaitsev\'s rule predicts that elimination reactions preferentially form the more substituted (more stable) alkene.' },
  { id: 'c_h28', difficulty: 'hard', question: 'What is VSEPR theory?', options: ['Predicts molecular geometry from electron pair repulsion', 'Calculates bond energy', 'Determines color', 'Measures mass'], correctIndex: 0, explanation: 'VSEPR (Valence Shell Electron Pair Repulsion) theory predicts molecular shapes by minimizing repulsion between electron pairs around a central atom.' },
  { id: 'c_h29', difficulty: 'hard', question: 'What is the Pauli exclusion principle in chemistry?', options: ['No two electrons in an atom can have the same four quantum numbers', 'Electrons share all quantum numbers', 'Only two quantum numbers matter', 'Electrons are identical'], correctIndex: 0, explanation: 'Each electron in an atom has a unique set of four quantum numbers (n, l, ml, ms), meaning at most 2 electrons per orbital.' },
  { id: 'c_h30', difficulty: 'hard', question: 'What is the chelate effect?', options: ['Polydentate ligands form more stable complexes than monodentate', 'All ligands are equal', 'Smaller ligands are stronger', 'Only water acts as ligand'], correctIndex: 0, explanation: 'The chelate effect explains why polydentate (chelating) ligands form more thermodynamically stable complexes due to the entropy advantage.' },
  { id: 'c_h31', difficulty: 'hard', question: 'What is the Hammond postulate?', options: ['Transition state resembles the species closest in energy', 'Products always resemble transition state', 'All transition states are identical', 'Energy is always conserved'], correctIndex: 0, explanation: 'Hammond\'s postulate states that the transition state of a reaction step resembles the species (reactant or product) it is closest to in energy.' },
  { id: 'c_h32', difficulty: 'hard', question: 'What is a carbocation?', options: ['Positively charged carbon species', 'Negatively charged carbon', 'Neutral carbon', 'Carbon with extra electrons'], correctIndex: 0, explanation: 'A carbocation is a carbon atom bearing a positive charge due to having only 6 valence electrons, key intermediate in many organic reactions.' },
  { id: 'c_h33', difficulty: 'hard', question: 'What is the SN1 mechanism?', options: ['Unimolecular nucleophilic substitution via carbocation intermediate', 'Bimolecular mechanism', 'Radical mechanism', 'Elimination mechanism'], correctIndex: 0, explanation: 'SN1 is a two-step substitution: first the leaving group departs forming a carbocation, then the nucleophile attacks.' },
  { id: 'c_h34', difficulty: 'hard', question: 'What is the SN2 mechanism?', options: ['Bimolecular one-step backside attack with inversion', 'Unimolecular mechanism', 'Radical mechanism', 'Rearrangement'], correctIndex: 0, explanation: 'SN2 is a one-step mechanism where the nucleophile attacks from the backside simultaneously as the leaving group departs, causing inversion.' },
  { id: 'c_h35', difficulty: 'hard', question: 'What is the Wittig reaction?', options: ['Converts aldehydes/ketones to alkenes using phosphorus ylides', 'Oxidation reaction', 'Reduction reaction', 'Polymerization'], correctIndex: 0, explanation: 'The Wittig reaction uses phosphonium ylides to convert carbonyl compounds to alkenes, forming triphenylphosphine oxide as byproduct.' },
  { id: 'c_h36', difficulty: 'hard', question: 'What is the Hess\'s law?', options: ['Total enthalpy change is independent of the pathway', 'Enthalpy depends on path', 'Only applies to gases', 'Only exothermic reactions'], correctIndex: 0, explanation: 'Hess\'s law states that the total enthalpy change for a reaction is the same regardless of the number of intermediate steps.' },
  { id: 'c_h37', difficulty: 'hard', question: 'What is the Cannizzaro reaction?', options: ['Non-enolizable aldehyde undergoes simultaneous oxidation and reduction in base', 'Acid-catalyzed reaction', 'Free radical reaction', 'Elimination'], correctIndex: 0, explanation: 'The Cannizzaro reaction occurs when a non-enolizable aldehyde is treated with strong base, producing an alcohol and carboxylate.' },
  { id: 'c_h38', difficulty: 'hard', question: 'What is the Beckmann rearrangement?', options: ['Oxime converts to amide under acid catalysis', 'Ester hydrolysis', 'Alcohol oxidation', 'Alkene addition'], correctIndex: 0, explanation: 'The Beckmann rearrangement converts oximes to amides (or lactams) through migration of a substituent from carbon to nitrogen.' },
  { id: 'c_h39', difficulty: 'hard', question: 'What is the Kolbe reaction?', options: ['Electrolysis of carboxylate salts to form hydrocarbons', 'Phenol carboxylation', 'Ester formation', 'Amide synthesis'], correctIndex: 0, explanation: 'The Kolbe reaction involves electrolysis of carboxylate salts, forming hydrocarbons through radical coupling after decarboxylation.' },
  { id: 'c_h40', difficulty: 'hard', question: 'What is the Michaelis-Menten equation?', options: ['Describes enzyme kinetics: v = Vmax[S]/(Km + [S])', 'Calculates pH', 'Determines molecular weight', 'Measures temperature'], correctIndex: 0, explanation: 'The Michaelis-Menten equation models enzyme kinetics, relating reaction rate to substrate concentration.' },
  { id: 'c_h41', difficulty: 'hard', question: 'What is the principle of microscopic reversibility?', options: ['Forward and reverse reactions follow the same pathway', 'Reactions only go forward', 'Reverse reactions use different paths', 'Only applies to gases'], correctIndex: 0, explanation: 'Microscopic reversibility states that at equilibrium, any elementary step proceeds at equal rates in both directions through the same transition state.' },
  { id: 'c_h42', difficulty: 'hard', question: 'What is the Curtin-Hammett principle?', options: ['Product ratio depends on transition state energies, not conformer populations', 'Products depend on reactant ratios', 'Temperature determines products', 'Catalyst determines products'], correctIndex: 0, explanation: 'The Curtin-Hammett principle states that for rapidly interconverting conformers, the product distribution depends on the relative transition state energies.' },
  { id: 'c_h43', difficulty: 'hard', question: 'What is the Marcus theory?', options: ['Relates electron transfer rates to thermodynamic driving force and reorganization energy', 'Describes acid-base reactions', 'Explains precipitation', 'Models gas behavior'], correctIndex: 0, explanation: 'Marcus theory predicts electron transfer rates from the reorganization energy and the free energy change of the reaction.' },
  { id: 'c_h44', difficulty: 'hard', question: 'What is the Ziegler-Natta catalyst?', options: ['Catalyst for stereospecific polymerization of alkenes', 'Acid catalyst', 'Enzyme', 'Photocatalyst'], correctIndex: 0, explanation: 'Ziegler-Natta catalysts (typically TiCl₄ with AlEt₃) enable stereospecific polymerization, producing isotactic or syndiotactic polymers.' },
  { id: 'c_h45', difficulty: 'hard', question: 'What is the Stille coupling?', options: ['Palladium-catalyzed cross-coupling using organotin compounds', 'Iron-catalyzed reaction', 'Acid-base reaction', 'Radical polymerization'], correctIndex: 0, explanation: 'The Stille coupling is a versatile palladium-catalyzed cross-coupling reaction between organostannanes and organic halides.' },
  { id: 'c_h46', difficulty: 'hard', question: 'What is the Suzuki reaction?', options: ['Palladium-catalyzed coupling of organoboron compounds with halides', 'Grignard reaction', 'Aldol condensation', 'Elimination reaction'], correctIndex: 0, explanation: 'The Suzuki reaction couples organoboron compounds with organic halides using palladium catalysis, widely used in pharmaceutical synthesis.' },
  { id: 'c_h47', difficulty: 'hard', question: 'What is the Heck reaction?', options: ['Palladium-catalyzed coupling of aryl halides with alkenes', 'Acid-catalyzed hydration', 'Free radical addition', 'Electrophilic substitution'], correctIndex: 0, explanation: 'The Heck reaction is a palladium-catalyzed C-C bond formation between aryl/vinyl halides and alkenes.' },
  { id: 'c_h48', difficulty: 'hard', question: 'What is the Birch reduction?', options: ['Partial reduction of aromatic rings using alkali metal in liquid ammonia', 'Complete hydrogenation', 'Oxidation', 'Substitution'], correctIndex: 0, explanation: 'The Birch reduction partially reduces aromatic rings to 1,4-cyclohexadienes using Na or Li in liquid ammonia with an alcohol.' },
  { id: 'c_h49', difficulty: 'hard', question: 'What is the Cope rearrangement?', options: ['[3,3]-Sigmatropic rearrangement of 1,5-dienes', '[2,3] rearrangement', 'Electrocyclic reaction', 'Cycloaddition'], correctIndex: 0, explanation: 'The Cope rearrangement is a thermal [3,3]-sigmatropic rearrangement of 1,5-dienes proceeding through a chair-like transition state.' },
  { id: 'c_h50', difficulty: 'hard', question: 'What is the Swern oxidation?', options: ['Mild oxidation of alcohols to aldehydes/ketones using DMSO/oxalyl chloride', 'Strong oxidation with KMnO₄', 'Reduction', 'Halogenation'], correctIndex: 0, explanation: 'The Swern oxidation converts primary/secondary alcohols to aldehydes/ketones under mild conditions using activated DMSO.' },
];

// ══════════════════════════════════════════════════════════════
// BIOLOGY — 150 unique questions
// ══════════════════════════════════════════════════════════════
const biologyPool: Question[] = [
  // ── EASY (50) ──
  { id: 'b_e1', difficulty: 'easy', question: 'What is the powerhouse of the cell?', options: ['Nucleus', 'Ribosome', 'Mitochondria', 'Golgi body'], correctIndex: 2, explanation: 'Mitochondria produce ATP through cellular respiration, providing energy for cell functions.' },
  { id: 'b_e2', difficulty: 'easy', question: 'What pigment makes plants green?', options: ['Melanin', 'Chlorophyll', 'Carotene', 'Hemoglobin'], correctIndex: 1, explanation: 'Chlorophyll absorbs red and blue light, reflecting green light, giving plants their color.' },
  { id: 'b_e3', difficulty: 'easy', question: 'DNA stands for:', options: ['Dioxyribose Nucleic Acid', 'Deoxyribonucleic Acid', 'Dynamic Natural Acid', 'Di-Nucleotide Acid'], correctIndex: 1, explanation: 'DNA (deoxyribonucleic acid) is the molecule that carries genetic instructions for all known organisms.' },
  { id: 'b_e4', difficulty: 'easy', question: 'How many chromosomes do humans have?', options: ['23', '44', '46', '48'], correctIndex: 2, explanation: 'Human cells contain 46 chromosomes (23 pairs): 22 pairs of autosomes and 1 pair of sex chromosomes.' },
  { id: 'b_e5', difficulty: 'easy', question: 'Which organ pumps blood throughout the body?', options: ['Liver', 'Brain', 'Lungs', 'Heart'], correctIndex: 3, explanation: 'The heart is a muscular organ that pumps blood through the circulatory system to deliver oxygen and nutrients.' },
  { id: 'b_e6', difficulty: 'easy', question: 'What is the largest organ of the human body?', options: ['Liver', 'Brain', 'Skin', 'Intestine'], correctIndex: 2, explanation: 'Skin is the largest organ, covering about 1.5-2 square meters in adults and weighing about 3.6 kg.' },
  { id: 'b_e7', difficulty: 'easy', question: 'What type of cell division produces gametes?', options: ['Mitosis', 'Meiosis', 'Binary fission', 'Budding'], correctIndex: 1, explanation: 'Meiosis is a specialized cell division that produces gametes (sex cells) with half the chromosome number.' },
  { id: 'b_e8', difficulty: 'easy', question: 'What is the universal blood donor type?', options: ['A+', 'B+', 'AB+', 'O-'], correctIndex: 3, explanation: 'Type O- blood has no A, B, or Rh antigens, so it can be donated to any blood type without causing an immune reaction.' },
  { id: 'b_e9', difficulty: 'easy', question: 'Photosynthesis occurs in which organelle?', options: ['Mitochondria', 'Nucleus', 'Chloroplast', 'Vacuole'], correctIndex: 2, explanation: 'Chloroplasts contain chlorophyll and are the site of photosynthesis: 6CO₂ + 6H₂O + light → C₆H₁₂O₆ + 6O₂.' },
  { id: 'b_e10', difficulty: 'easy', question: 'What carries genetic information to ribosomes?', options: ['tRNA', 'mRNA', 'rRNA', 'DNA polymerase'], correctIndex: 1, explanation: 'Messenger RNA (mRNA) carries genetic information from DNA in the nucleus to ribosomes for protein synthesis.' },
  { id: 'b_e11', difficulty: 'easy', question: 'What vitamin is produced when skin is exposed to sunlight?', options: ['Vitamin A', 'Vitamin B12', 'Vitamin C', 'Vitamin D'], correctIndex: 3, explanation: 'UV-B radiation triggers vitamin D synthesis in the skin, essential for calcium absorption and bone health.' },
  { id: 'b_e12', difficulty: 'easy', question: 'What enzyme in saliva breaks down starch?', options: ['Pepsin', 'Lipase', 'Amylase', 'Trypsin'], correctIndex: 2, explanation: 'Salivary amylase begins the digestion of starch into maltose in the mouth.' },
  { id: 'b_e13', difficulty: 'easy', question: 'Where are red blood cells produced?', options: ['Liver', 'Bone marrow', 'Spleen', 'Kidneys'], correctIndex: 1, explanation: 'Red bone marrow is the primary site of hematopoiesis (red blood cell production) in adults.' },
  { id: 'b_e14', difficulty: 'easy', question: 'What is the functional unit of the kidney?', options: ['Alveolus', 'Nephron', 'Neuron', 'Villus'], correctIndex: 1, explanation: 'Each kidney contains about 1 million nephrons that filter blood and produce urine.' },
  { id: 'b_e15', difficulty: 'easy', question: 'What is the smallest bone in the human body?', options: ['Femur', 'Stapes', 'Radius', 'Patella'], correctIndex: 1, explanation: 'The stapes (stirrup bone) in the middle ear is the smallest bone, measuring about 3 mm.' },
  { id: 'b_e16', difficulty: 'easy', question: 'What is the main function of white blood cells?', options: ['Carry oxygen', 'Fight infections', 'Clot blood', 'Transport nutrients'], correctIndex: 1, explanation: 'White blood cells (leukocytes) are the main components of the immune system, defending against pathogens.' },
  { id: 'b_e17', difficulty: 'easy', question: 'What gas do animals exhale?', options: ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Hydrogen'], correctIndex: 2, explanation: 'Animals exhale CO₂ as a waste product of cellular respiration.' },
  { id: 'b_e18', difficulty: 'easy', question: 'What is the basic unit of life?', options: ['Atom', 'Molecule', 'Cell', 'Organ'], correctIndex: 2, explanation: 'The cell is the fundamental structural and functional unit of all living organisms.' },
  { id: 'b_e19', difficulty: 'easy', question: 'What does the respiratory system do?', options: ['Digest food', 'Exchange gases', 'Pump blood', 'Filter waste'], correctIndex: 1, explanation: 'The respiratory system facilitates gas exchange: taking in oxygen and releasing carbon dioxide.' },
  { id: 'b_e20', difficulty: 'easy', question: 'What is the function of the stomach?', options: ['Absorb water', 'Mechanically and chemically digest food', 'Filter blood', 'Produce insulin'], correctIndex: 1, explanation: 'The stomach uses acid (HCl) and enzymes (pepsin) to break down food into chyme.' },
  { id: 'b_e21', difficulty: 'easy', question: 'What is the study of animals called?', options: ['Botany', 'Zoology', 'Ecology', 'Mycology'], correctIndex: 1, explanation: 'Zoology is the branch of biology that studies animals and animal life.' },
  { id: 'b_e22', difficulty: 'easy', question: 'What structure protects the brain?', options: ['Rib cage', 'Pelvis', 'Skull', 'Spine'], correctIndex: 2, explanation: 'The skull (cranium) is a bony structure that encases and protects the brain from injury.' },
  { id: 'b_e23', difficulty: 'easy', question: 'What is the largest bone in the human body?', options: ['Humerus', 'Femur', 'Tibia', 'Pelvis'], correctIndex: 1, explanation: 'The femur (thigh bone) is the longest and strongest bone in the human body.' },
  { id: 'b_e24', difficulty: 'easy', question: 'What are the building blocks of proteins?', options: ['Fatty acids', 'Amino acids', 'Nucleotides', 'Monosaccharides'], correctIndex: 1, explanation: 'Proteins are made of chains of amino acids. There are 20 standard amino acids used in protein synthesis.' },
  { id: 'b_e25', difficulty: 'easy', question: 'Which blood vessels carry blood away from the heart?', options: ['Veins', 'Arteries', 'Capillaries', 'Lymph vessels'], correctIndex: 1, explanation: 'Arteries carry blood away from the heart, typically oxygenated (except the pulmonary artery).' },
  { id: 'b_e26', difficulty: 'easy', question: 'What is the function of the large intestine?', options: ['Digest proteins', 'Absorb water and form feces', 'Produce bile', 'Secrete insulin'], correctIndex: 1, explanation: 'The large intestine absorbs water and electrolytes from remaining indigestible food matter and compacts waste into feces.' },
  { id: 'b_e27', difficulty: 'easy', question: 'What part of the plant absorbs water from the soil?', options: ['Leaves', 'Stem', 'Roots', 'Flowers'], correctIndex: 2, explanation: 'Roots absorb water and dissolved minerals from the soil through root hairs.' },
  { id: 'b_e28', difficulty: 'easy', question: 'What is the function of platelets?', options: ['Fight infection', 'Blood clotting', 'Carry oxygen', 'Produce hormones'], correctIndex: 1, explanation: 'Platelets (thrombocytes) are cell fragments that help form blood clots to stop bleeding.' },
  { id: 'b_e29', difficulty: 'easy', question: 'What is the scientific name for the windpipe?', options: ['Esophagus', 'Trachea', 'Bronchus', 'Larynx'], correctIndex: 1, explanation: 'The trachea (windpipe) is the tube connecting the larynx to the bronchi, carrying air to the lungs.' },
  { id: 'b_e30', difficulty: 'easy', question: 'How many senses do humans traditionally have?', options: ['3', '4', '5', '6'], correctIndex: 2, explanation: 'The five traditional senses are sight, hearing, smell, taste, and touch.' },
  { id: 'b_e31', difficulty: 'easy', question: 'What is the main organ of the nervous system?', options: ['Heart', 'Brain', 'Liver', 'Kidneys'], correctIndex: 1, explanation: 'The brain is the central organ of the nervous system, controlling thought, memory, and bodily functions.' },
  { id: 'b_e32', difficulty: 'easy', question: 'What do herbivores eat?', options: ['Meat', 'Plants', 'Both', 'Minerals'], correctIndex: 1, explanation: 'Herbivores are animals that primarily eat plant-based food.' },
  { id: 'b_e33', difficulty: 'easy', question: 'What is the process by which plants lose water through their leaves?', options: ['Osmosis', 'Diffusion', 'Transpiration', 'Evaporation'], correctIndex: 2, explanation: 'Transpiration is the loss of water vapor from plant leaves through stomata.' },
  { id: 'b_e34', difficulty: 'easy', question: 'What is the colored part of the eye called?', options: ['Pupil', 'Iris', 'Retina', 'Cornea'], correctIndex: 1, explanation: 'The iris is the colored part of the eye that controls the size of the pupil and the amount of light entering.' },
  { id: 'b_e35', difficulty: 'easy', question: 'What type of organism breaks down dead matter?', options: ['Producer', 'Consumer', 'Decomposer', 'Predator'], correctIndex: 2, explanation: 'Decomposers (like fungi and bacteria) break down dead organisms, recycling nutrients back into the ecosystem.' },
  { id: 'b_e36', difficulty: 'easy', question: 'What is a group of similar cells performing the same function called?', options: ['Organ', 'Tissue', 'System', 'Organism'], correctIndex: 1, explanation: 'A tissue is a group of similar cells working together to perform a specific function.' },
  { id: 'b_e37', difficulty: 'easy', question: 'What is the hard outer covering of insects called?', options: ['Shell', 'Exoskeleton', 'Endoskeleton', 'Cuticle'], correctIndex: 1, explanation: 'Insects have an exoskeleton — an external skeleton made of chitin that provides protection and support.' },
  { id: 'b_e38', difficulty: 'easy', question: 'What carries oxygen in red blood cells?', options: ['Plasma', 'Hemoglobin', 'White cells', 'Platelets'], correctIndex: 1, explanation: 'Hemoglobin is an iron-containing protein in red blood cells that binds and transports oxygen.' },
  { id: 'b_e39', difficulty: 'easy', question: 'What is the study of plants called?', options: ['Zoology', 'Botany', 'Ecology', 'Anatomy'], correctIndex: 1, explanation: 'Botany is the scientific study of plants, including their structure, genetics, and ecology.' },
  { id: 'b_e40', difficulty: 'easy', question: 'What is the function of the liver?', options: ['Pump blood', 'Detoxify blood and produce bile', 'Filter air', 'Produce insulin'], correctIndex: 1, explanation: 'The liver detoxifies chemicals, metabolizes drugs, produces bile for fat digestion, and stores nutrients.' },
  { id: 'b_e41', difficulty: 'easy', question: 'What are organisms that eat both plants and animals called?', options: ['Herbivores', 'Carnivores', 'Omnivores', 'Decomposers'], correctIndex: 2, explanation: 'Omnivores eat both plant and animal matter. Humans are a common example.' },
  { id: 'b_e42', difficulty: 'easy', question: 'What is the genetic material in most organisms?', options: ['RNA', 'DNA', 'Protein', 'Lipids'], correctIndex: 1, explanation: 'DNA (deoxyribonucleic acid) is the primary genetic material in most living organisms.' },
  { id: 'b_e43', difficulty: 'easy', question: 'What is the function of the lungs?', options: ['Pump blood', 'Exchange oxygen and carbon dioxide', 'Digest food', 'Filter waste'], correctIndex: 1, explanation: 'Lungs exchange gases: oxygen from inhaled air enters the blood, and CO₂ from the blood is exhaled.' },
  { id: 'b_e44', difficulty: 'easy', question: 'What is the process of cell division in body cells called?', options: ['Meiosis', 'Mitosis', 'Fertilization', 'Germination'], correctIndex: 1, explanation: 'Mitosis produces two genetically identical daughter cells, used for growth and repair.' },
  { id: 'b_e45', difficulty: 'easy', question: 'What connects muscles to bones?', options: ['Ligaments', 'Tendons', 'Cartilage', 'Nerves'], correctIndex: 1, explanation: 'Tendons are tough, fibrous connective tissues that attach muscles to bones.' },
  { id: 'b_e46', difficulty: 'easy', question: 'What is the largest cell in the human body?', options: ['Red blood cell', 'Ovum (egg cell)', 'Neuron', 'Muscle cell'], correctIndex: 1, explanation: 'The human ovum (egg cell) is about 0.1 mm in diameter, visible to the naked eye.' },
  { id: 'b_e47', difficulty: 'easy', question: 'What do plants need for photosynthesis?', options: ['Light, water, and CO₂', 'Darkness and oxygen', 'Only water', 'Only soil'], correctIndex: 0, explanation: 'Photosynthesis requires light energy, water (H₂O), and carbon dioxide (CO₂) to produce glucose and oxygen.' },
  { id: 'b_e48', difficulty: 'easy', question: 'What is the function of the small intestine?', options: ['Store food', 'Absorb nutrients', 'Produce bile', 'Filter blood'], correctIndex: 1, explanation: 'The small intestine is the primary site for digestion and absorption of nutrients into the bloodstream.' },
  { id: 'b_e49', difficulty: 'easy', question: 'What connects bones to other bones?', options: ['Tendons', 'Ligaments', 'Muscles', 'Cartilage'], correctIndex: 1, explanation: 'Ligaments are strong, elastic connective tissues that connect bones to other bones at joints.' },
  { id: 'b_e50', difficulty: 'easy', question: 'What is the liquid part of blood called?', options: ['Serum', 'Plasma', 'Hemoglobin', 'Lymph'], correctIndex: 1, explanation: 'Plasma makes up about 55% of blood volume and carries cells, nutrients, hormones, and waste products.' },

  // ── MEDIUM (50) ──
  { id: 'b_m1', difficulty: 'medium', question: 'What is homeostasis?', options: ['Body maintaining stable internal conditions', 'Cell division', 'DNA replication', 'Protein synthesis'], correctIndex: 0, explanation: 'Homeostasis is the process by which organisms regulate internal conditions (temperature, pH, glucose) to maintain stability.' },
  { id: 'b_m2', difficulty: 'medium', question: 'What are antibodies made of?', options: ['Lipids', 'Proteins', 'Carbohydrates', 'Nucleic acids'], correctIndex: 1, explanation: 'Antibodies (immunoglobulins) are Y-shaped proteins produced by B cells to identify and neutralize pathogens.' },
  { id: 'b_m3', difficulty: 'medium', question: 'What is the function of ribosomes?', options: ['Protein synthesis', 'Energy production', 'Cell division', 'Transport'], correctIndex: 0, explanation: 'Ribosomes translate mRNA into amino acid chains (proteins) through the process of translation.' },
  { id: 'b_m4', difficulty: 'medium', question: 'What is taxonomy?', options: ['Classification of organisms', 'Study of taxes', 'Cell structure', 'Genetics'], correctIndex: 0, explanation: 'Taxonomy is the science of classifying organisms into hierarchical groups: domain, kingdom, phylum, class, order, family, genus, species.' },
  { id: 'b_m5', difficulty: 'medium', question: 'What is the central dogma of molecular biology?', options: ['DNA → RNA → Protein', 'Protein → RNA → DNA', 'RNA → DNA → Protein', 'DNA → Protein → RNA'], correctIndex: 0, explanation: 'The central dogma describes information flow: DNA is transcribed to RNA, which is translated to protein.' },
  { id: 'b_m6', difficulty: 'medium', question: 'What is the study of fungi called?', options: ['Virology', 'Mycology', 'Botany', 'Zoology'], correctIndex: 1, explanation: 'Mycology is the branch of biology that studies fungi, including yeasts, molds, and mushrooms.' },
  { id: 'b_m7', difficulty: 'medium', question: 'What is the difference between mitosis and meiosis?', options: ['Mitosis produces identical cells; meiosis produces genetically diverse gametes', 'They are the same', 'Mitosis is only in plants', 'Meiosis produces body cells'], correctIndex: 0, explanation: 'Mitosis produces 2 identical diploid cells; meiosis produces 4 genetically unique haploid gametes through crossing over and independent assortment.' },
  { id: 'b_m8', difficulty: 'medium', question: 'What is natural selection?', options: ['Organisms with favorable traits survive and reproduce more', 'Random survival', 'Artificial breeding', 'Genetic engineering'], correctIndex: 0, explanation: 'Natural selection is the process where organisms with traits better suited to their environment survive and pass on those traits.' },
  { id: 'b_m9', difficulty: 'medium', question: 'What is a dominant allele?', options: ['Allele expressed when one or two copies are present', 'Always recessive', 'Causes mutations', 'Found only in males'], correctIndex: 0, explanation: 'A dominant allele is expressed in the phenotype when at least one copy is present (Aa or AA).' },
  { id: 'b_m10', difficulty: 'medium', question: 'What is the difference between prokaryotic and eukaryotic cells?', options: ['Prokaryotes lack a membrane-bound nucleus; eukaryotes have one', 'They are identical', 'Prokaryotes are larger', 'Eukaryotes lack DNA'], correctIndex: 0, explanation: 'Prokaryotic cells (bacteria) lack a membrane-bound nucleus; eukaryotic cells (animals, plants, fungi) have one.' },
  { id: 'b_m11', difficulty: 'medium', question: 'What is an ecosystem?', options: ['Community of organisms interacting with their environment', 'A single species', 'Just the climate', 'Only the soil'], correctIndex: 0, explanation: 'An ecosystem includes all living organisms (biotic) and non-living components (abiotic) interacting in a defined area.' },
  { id: 'b_m12', difficulty: 'medium', question: 'What is genetic drift?', options: ['Random changes in allele frequency in small populations', 'Directed evolution', 'Natural selection', 'Mutation only'], correctIndex: 0, explanation: 'Genetic drift is the random fluctuation of allele frequencies, most significant in small populations.' },
  { id: 'b_m13', difficulty: 'medium', question: 'What is the function of the Golgi apparatus?', options: ['Modifies, packages, and ships proteins', 'Produces energy', 'Stores DNA', 'Controls cell division'], correctIndex: 0, explanation: 'The Golgi apparatus processes, packages, and sorts proteins and lipids for secretion or delivery to other organelles.' },
  { id: 'b_m14', difficulty: 'medium', question: 'What is a food web?', options: ['Interconnected food chains in an ecosystem', 'A single predator-prey relationship', 'A type of plant', 'Nutrient cycle only'], correctIndex: 0, explanation: 'A food web shows the complex feeding relationships among multiple interconnected food chains in an ecosystem.' },
  { id: 'b_m15', difficulty: 'medium', question: 'What is the function of the endoplasmic reticulum?', options: ['Synthesis and transport of proteins and lipids', 'Cell division', 'DNA storage', 'Energy production'], correctIndex: 0, explanation: 'Rough ER synthesizes proteins; smooth ER synthesizes lipids and detoxifies chemicals. Both transport materials within the cell.' },
  { id: 'b_m16', difficulty: 'medium', question: 'What is a mutation?', options: ['Change in DNA sequence', 'Normal cell division', 'Protein folding', 'Cell death'], correctIndex: 0, explanation: 'A mutation is a permanent change in the nucleotide sequence of DNA, which may affect protein function.' },
  { id: 'b_m17', difficulty: 'medium', question: 'What is the greenhouse effect?', options: ['Atmospheric gases trap heat, warming Earth', 'Cooling of the atmosphere', 'Cloud formation', 'Wind patterns'], correctIndex: 0, explanation: 'Greenhouse gases (CO₂, CH₄, H₂O) trap infrared radiation from Earth\'s surface, warming the atmosphere.' },
  { id: 'b_m18', difficulty: 'medium', question: 'What is symbiosis?', options: ['Close, long-term interaction between different species', 'Competition', 'Predation', 'Parasitism only'], correctIndex: 0, explanation: 'Symbiosis is a close biological interaction between two species, including mutualism, commensalism, and parasitism.' },
  { id: 'b_m19', difficulty: 'medium', question: 'What is the lymphatic system\'s function?', options: ['Drains excess fluid and supports immune function', 'Pumps blood', 'Digests food', 'Produces hormones only'], correctIndex: 0, explanation: 'The lymphatic system returns excess interstitial fluid to blood, transports fats, and houses immune cells (lymphocytes).' },
  { id: 'b_m20', difficulty: 'medium', question: 'What is selective permeability?', options: ['Cell membrane allows some substances through but not others', 'Everything passes through', 'Nothing passes through', 'Only water passes'], correctIndex: 0, explanation: 'Selective permeability allows the cell membrane to regulate which molecules enter and exit the cell.' },
  { id: 'b_m21', difficulty: 'medium', question: 'What is a genotype?', options: ['Genetic makeup of an organism', 'Physical appearance', 'Behavior pattern', 'Habitat preference'], correctIndex: 0, explanation: 'Genotype refers to the specific alleles an organism carries (e.g., Aa, BB) as opposed to its visible traits (phenotype).' },
  { id: 'b_m22', difficulty: 'medium', question: 'What is osmosis?', options: ['Movement of water across a semipermeable membrane from low to high solute concentration', 'Movement of solutes', 'Active transport', 'Diffusion of gases'], correctIndex: 0, explanation: 'Osmosis is the passive movement of water molecules across a semipermeable membrane toward higher solute concentration.' },
  { id: 'b_m23', difficulty: 'medium', question: 'What is the difference between arteries and veins?', options: ['Arteries carry blood from heart; veins return blood to heart', 'They are identical', 'Veins carry oxygenated blood only', 'Arteries have valves; veins don\'t'], correctIndex: 0, explanation: 'Arteries carry blood away from the heart (usually oxygenated); veins return blood to the heart (usually deoxygenated).' },
  { id: 'b_m24', difficulty: 'medium', question: 'What is active transport?', options: ['Movement of substances against concentration gradient using energy', 'Passive diffusion', 'Osmosis', 'Filtration'], correctIndex: 0, explanation: 'Active transport uses cellular energy (ATP) to move substances from low to high concentration, against the gradient.' },
  { id: 'b_m25', difficulty: 'medium', question: 'What is biodiversity?', options: ['Variety of life in an ecosystem', 'Number of humans', 'Amount of water', 'Soil quality'], correctIndex: 0, explanation: 'Biodiversity encompasses the variety of species, genetic variation, and ecosystem diversity in a given area.' },
  { id: 'b_m26', difficulty: 'medium', question: 'What is the endocrine system?', options: ['Glands that produce hormones to regulate body functions', 'Digestive system', 'Skeletal system', 'Muscular system'], correctIndex: 0, explanation: 'The endocrine system consists of glands (thyroid, adrenal, pituitary, etc.) that secrete hormones into the bloodstream.' },
  { id: 'b_m27', difficulty: 'medium', question: 'What is a biome?', options: ['Large ecological area with distinct plant and animal communities', 'A single habitat', 'One organism', 'A cell type'], correctIndex: 0, explanation: 'A biome is a large-scale ecological region characterized by specific climate conditions and dominant vegetation (e.g., desert, tundra, rainforest).' },
  { id: 'b_m28', difficulty: 'medium', question: 'What is the function of insulin?', options: ['Lowers blood glucose by promoting cellular uptake', 'Raises blood sugar', 'Digests proteins', 'Contracts muscles'], correctIndex: 0, explanation: 'Insulin is a hormone produced by the pancreas that signals cells to absorb glucose from the blood, lowering blood sugar levels.' },
  { id: 'b_m29', difficulty: 'medium', question: 'What is the nitrogen cycle?', options: ['Process converting nitrogen between chemical forms through biological and physical processes', 'Oxygen cycle', 'Water cycle', 'Carbon cycle'], correctIndex: 0, explanation: 'The nitrogen cycle converts atmospheric N₂ to usable forms (NH₃, NO₃⁻) through fixation, nitrification, and denitrification.' },
  { id: 'b_m30', difficulty: 'medium', question: 'What is the function of the cell membrane?', options: ['Controls what enters and exits the cell', 'Stores DNA', 'Produces energy', 'Synthesizes proteins'], correctIndex: 0, explanation: 'The cell membrane (phospholipid bilayer) regulates the passage of substances in and out of the cell.' },
  { id: 'b_m31', difficulty: 'medium', question: 'What is the carbon cycle?', options: ['Movement of carbon through atmosphere, organisms, and Earth', 'Only CO₂ exchange', 'Fossil fuel formation only', 'Photosynthesis only'], correctIndex: 0, explanation: 'The carbon cycle describes how carbon moves through the atmosphere, biosphere, hydrosphere, and lithosphere via photosynthesis, respiration, decomposition, and combustion.' },
  { id: 'b_m32', difficulty: 'medium', question: 'What is a trophic level?', options: ['Position an organism occupies in a food chain', 'Geographic location', 'Body temperature', 'Reproductive rate'], correctIndex: 0, explanation: 'Trophic levels represent feeding positions: producers (level 1), primary consumers (level 2), secondary consumers (level 3), etc.' },
  { id: 'b_m33', difficulty: 'medium', question: 'What is the function of the vacuole in plant cells?', options: ['Stores water, nutrients, and waste; maintains turgor pressure', 'Produces energy', 'Synthesizes proteins', 'Contains DNA'], correctIndex: 0, explanation: 'The central vacuole in plant cells stores water and dissolved substances, helping maintain cell turgor pressure and rigidity.' },
  { id: 'b_m34', difficulty: 'medium', question: 'What is a phenotype?', options: ['Observable characteristics of an organism', 'DNA sequence', 'Number of chromosomes', 'Type of RNA'], correctIndex: 0, explanation: 'Phenotype is the observable physical and biochemical characteristics of an organism, determined by genotype and environment.' },
  { id: 'b_m35', difficulty: 'medium', question: 'What is aerobic respiration?', options: ['Energy release using oxygen: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP', 'Without oxygen', 'Photosynthesis', 'Fermentation'], correctIndex: 0, explanation: 'Aerobic respiration uses oxygen to completely break down glucose, yielding up to 38 ATP molecules per glucose.' },
  { id: 'b_m36', difficulty: 'medium', question: 'What is a vaccine?', options: ['Preparation that stimulates immune response without causing disease', 'Antibiotic', 'Painkiller', 'Vitamin supplement'], correctIndex: 0, explanation: 'Vaccines contain weakened/killed pathogens or their components that train the immune system to recognize and fight future infections.' },
  { id: 'b_m37', difficulty: 'medium', question: 'What is the difference between DNA and RNA?', options: ['DNA is double-stranded with deoxyribose; RNA is single-stranded with ribose', 'They are identical', 'RNA is double-stranded', 'DNA contains uracil'], correctIndex: 0, explanation: 'DNA is double-stranded with deoxyribose sugar and thymine; RNA is typically single-stranded with ribose sugar and uracil.' },
  { id: 'b_m38', difficulty: 'medium', question: 'What is succession in ecology?', options: ['Gradual change in species composition over time', 'Sudden extinction', 'Migration', 'Hibernation'], correctIndex: 0, explanation: 'Ecological succession is the process of gradual change in species composition of an ecological community over time.' },
  { id: 'b_m39', difficulty: 'medium', question: 'What is the function of the hypothalamus?', options: ['Links nervous and endocrine systems; regulates body temperature', 'Pumps blood', 'Digests food', 'Produces red blood cells'], correctIndex: 0, explanation: 'The hypothalamus controls body temperature, hunger, thirst, and links the nervous system to the endocrine system via the pituitary gland.' },
  { id: 'b_m40', difficulty: 'medium', question: 'What is anaerobic respiration?', options: ['Energy release without oxygen, producing less ATP', 'With oxygen', 'Photosynthesis', 'Transpiration'], correctIndex: 0, explanation: 'Anaerobic respiration occurs without oxygen, producing less ATP. In animals it produces lactic acid; in yeast, ethanol and CO₂.' },
  { id: 'b_m41', difficulty: 'medium', question: 'What is a Punnett square used for?', options: ['Predicting offspring genotype ratios', 'Measuring cell size', 'Drawing organisms', 'Calculating body mass'], correctIndex: 0, explanation: 'A Punnett square is a diagram used to predict the genotypes and phenotypes of offspring from a genetic cross.' },
  { id: 'b_m42', difficulty: 'medium', question: 'What is the function of myelin sheath?', options: ['Insulates nerve fibers to speed up signal transmission', 'Contracts muscles', 'Produces hormones', 'Stores calcium'], correctIndex: 0, explanation: 'The myelin sheath is a fatty layer around nerve axons that electrically insulates them, dramatically increasing signal transmission speed.' },
  { id: 'b_m43', difficulty: 'medium', question: 'What is eutrophication?', options: ['Excessive nutrient enrichment causing algal blooms and oxygen depletion', 'Water purification', 'Soil formation', 'Erosion'], correctIndex: 0, explanation: 'Eutrophication occurs when excess nutrients (nitrogen, phosphorus) cause algal blooms that deplete oxygen, killing aquatic life.' },
  { id: 'b_m44', difficulty: 'medium', question: 'What is the function of the cerebellum?', options: ['Coordinates movement, balance, and posture', 'Controls breathing', 'Processes vision', 'Regulates hormones'], correctIndex: 0, explanation: 'The cerebellum coordinates voluntary movements, balance, and motor learning.' },
  { id: 'b_m45', difficulty: 'medium', question: 'What is a keystone species?', options: ['Species whose impact on ecosystem is disproportionately large relative to its abundance', 'Most abundant species', 'Largest species', 'Fastest species'], correctIndex: 0, explanation: 'A keystone species has an outsized effect on its ecosystem. Removing it causes significant ecological change.' },
  { id: 'b_m46', difficulty: 'medium', question: 'What is the water cycle?', options: ['Continuous movement of water through evaporation, condensation, and precipitation', 'Only rainfall', 'Only evaporation', 'Only river flow'], correctIndex: 0, explanation: 'The water cycle describes the continuous movement of water through evaporation, transpiration, condensation, precipitation, and runoff.' },
  { id: 'b_m47', difficulty: 'medium', question: 'What is a reflex arc?', options: ['Neural pathway for automatic responses bypassing the brain', 'Voluntary movement', 'Hormone pathway', 'Blood vessel route'], correctIndex: 0, explanation: 'A reflex arc is the neural pathway for involuntary responses: receptor → sensory neuron → relay neuron → motor neuron → effector.' },
  { id: 'b_m48', difficulty: 'medium', question: 'What is the function of stomata?', options: ['Allow gas exchange and transpiration in leaves', 'Absorb water', 'Produce seeds', 'Transport sugars'], correctIndex: 0, explanation: 'Stomata are pores on leaf surfaces that open and close to regulate CO₂ intake, O₂ release, and water loss.' },
  { id: 'b_m49', difficulty: 'medium', question: 'What is the Hardy-Weinberg equilibrium?', options: ['Allele frequencies remain constant in a non-evolving population', 'Species go extinct', 'Mutations increase', 'Natural selection dominates'], correctIndex: 0, explanation: 'Hardy-Weinberg equilibrium shows that allele frequencies stay constant without evolution, requiring no mutation, migration, selection, or drift.' },
  { id: 'b_m50', difficulty: 'medium', question: 'What is the function of the pancreas?', options: ['Produces insulin and digestive enzymes', 'Filters blood', 'Pumps blood', 'Stores bile'], correctIndex: 0, explanation: 'The pancreas has endocrine (insulin, glucagon) and exocrine (digestive enzyme) functions.' },

  // ── HARD (50) ──
  { id: 'b_h1', difficulty: 'hard', question: 'What is apoptosis?', options: ['Programmed cell death', 'Cell growth', 'Cell division', 'Random mutation'], correctIndex: 0, explanation: 'Apoptosis is a controlled process of programmed cell death essential for development, homeostasis, and eliminating damaged cells.' },
  { id: 'b_h2', difficulty: 'hard', question: 'What is CRISPR-Cas9 used for?', options: ['Precise gene editing', 'Microscopy', 'Drug delivery', 'Protein folding'], correctIndex: 0, explanation: 'CRISPR-Cas9 is a revolutionary gene-editing tool that uses a guide RNA to direct the Cas9 enzyme to cut DNA at specific locations.' },
  { id: 'b_h3', difficulty: 'hard', question: 'What is the endosymbiotic theory?', options: ['Mitochondria and chloroplasts evolved from engulfed bacteria', 'Cells evolved from rocks', 'DNA came from space', 'Viruses created cells'], correctIndex: 0, explanation: 'The endosymbiotic theory proposes that mitochondria and chloroplasts were once free-living bacteria that were engulfed by ancestral eukaryotic cells.' },
  { id: 'b_h4', difficulty: 'hard', question: 'What is epigenetics?', options: ['Heritable gene expression changes without DNA sequence alteration', 'DNA mutation', 'Gene deletion', 'Chromosome duplication'], correctIndex: 0, explanation: 'Epigenetics studies modifications (methylation, histone changes) that alter gene expression without changing the DNA sequence itself.' },
  { id: 'b_h5', difficulty: 'hard', question: 'What is a prion?', options: ['Infectious misfolded protein', 'A type of virus', 'A bacterium', 'A fungal spore'], correctIndex: 0, explanation: 'Prions are misfolded proteins that can cause normal proteins to misfold, leading to diseases like CJD and mad cow disease.' },
  { id: 'b_h6', difficulty: 'hard', question: 'What is convergent evolution?', options: ['Unrelated species independently evolving similar traits', 'Same species diverging', 'Genetic drift', 'Gene flow'], correctIndex: 0, explanation: 'Convergent evolution occurs when unrelated species develop similar features due to similar environmental pressures (e.g., wings in bats and birds).' },
  { id: 'b_h7', difficulty: 'hard', question: 'What is the microbiome?', options: ['Community of microorganisms living in and on an organism', 'A single bacterium', 'A virus collection', 'A fungal network'], correctIndex: 0, explanation: 'The human microbiome includes trillions of bacteria, viruses, and fungi that play crucial roles in digestion, immunity, and health.' },
  { id: 'b_h8', difficulty: 'hard', question: 'What is RNA interference (RNAi)?', options: ['Gene silencing by small RNA molecules', 'RNA amplification', 'DNA repair', 'Protein synthesis acceleration'], correctIndex: 0, explanation: 'RNAi is a biological process where small RNA molecules (siRNA, miRNA) silence gene expression by targeting mRNA for degradation.' },
  { id: 'b_h9', difficulty: 'hard', question: 'What is the Krebs cycle?', options: ['Series of reactions in mitochondria that generate electron carriers for ATP production', 'DNA replication', 'Photosynthesis', 'Cell division'], correctIndex: 0, explanation: 'The Krebs cycle (citric acid cycle) oxidizes acetyl-CoA in mitochondria, producing NADH, FADH₂, and GTP for oxidative phosphorylation.' },
  { id: 'b_h10', difficulty: 'hard', question: 'What is horizontal gene transfer?', options: ['Transfer of genetic material between organisms not through reproduction', 'Parent-to-offspring inheritance', 'Mutation', 'Genetic drift'], correctIndex: 0, explanation: 'Horizontal gene transfer moves genes between organisms (especially bacteria) through transformation, transduction, or conjugation.' },
  { id: 'b_h11', difficulty: 'hard', question: 'What is a telomere?', options: ['Protective cap at chromosome ends that shortens with each division', 'Center of chromosome', 'Gene promoter', 'RNA strand'], correctIndex: 0, explanation: 'Telomeres are repetitive DNA sequences at chromosome ends that protect against degradation and shorten with each cell division, linked to aging.' },
  { id: 'b_h12', difficulty: 'hard', question: 'What is oxidative phosphorylation?', options: ['ATP synthesis using electron transport chain and chemiosmosis', 'Substrate-level phosphorylation', 'Photophosphorylation', 'Fermentation'], correctIndex: 0, explanation: 'Oxidative phosphorylation uses the electron transport chain to create a proton gradient that drives ATP synthase, producing most cellular ATP.' },
  { id: 'b_h13', difficulty: 'hard', question: 'What is a histone?', options: ['Protein that DNA wraps around for chromatin structure', 'Type of enzyme', 'Sugar molecule', 'Lipid molecule'], correctIndex: 0, explanation: 'Histones are proteins that package and order DNA into nucleosomes, the basic structural unit of chromatin.' },
  { id: 'b_h14', difficulty: 'hard', question: 'What is metagenomics?', options: ['Study of genetic material from environmental samples', 'Single organism genome', 'Protein analysis', 'Cell culture technique'], correctIndex: 0, explanation: 'Metagenomics analyzes the collective genomic material from environmental samples, revealing the diversity of uncultured microorganisms.' },
  { id: 'b_h15', difficulty: 'hard', question: 'What is the Calvin cycle?', options: ['Light-independent reactions fixing CO₂ into sugar in chloroplasts', 'Light-dependent reactions', 'Krebs cycle', 'Electron transport'], correctIndex: 0, explanation: 'The Calvin cycle (dark reactions) uses ATP and NADPH from light reactions to fix CO₂ into glyceraldehyde-3-phosphate (G3P).' },
  { id: 'b_h16', difficulty: 'hard', question: 'What is a retrovirus?', options: ['RNA virus that uses reverse transcriptase to integrate into host DNA', 'DNA virus', 'Bacteriophage', 'Prion'], correctIndex: 0, explanation: 'Retroviruses (like HIV) carry RNA that is reverse-transcribed into DNA and integrated into the host genome.' },
  { id: 'b_h17', difficulty: 'hard', question: 'What is signal transduction?', options: ['Process by which cells respond to external signals through cascades', 'Direct gene activation', 'Osmosis', 'Diffusion'], correctIndex: 0, explanation: 'Signal transduction is the cascade of molecular events where a cell converts an extracellular signal into a specific cellular response.' },
  { id: 'b_h18', difficulty: 'hard', question: 'What is a stem cell?', options: ['Undifferentiated cell that can become specialized cell types', 'Mature blood cell', 'Dead cell', 'Cancer cell'], correctIndex: 0, explanation: 'Stem cells are unspecialized cells with the ability to self-renew and differentiate into various specialized cell types.' },
  { id: 'b_h19', difficulty: 'hard', question: 'What is the lac operon?', options: ['Gene regulatory system in E. coli for lactose metabolism', 'Human gene', 'Plant hormone', 'Virus component'], correctIndex: 0, explanation: 'The lac operon is a cluster of genes in E. coli that are regulated together, activated when lactose is present and glucose is absent.' },
  { id: 'b_h20', difficulty: 'hard', question: 'What is the electron transport chain?', options: ['Series of protein complexes transferring electrons to generate proton gradient', 'DNA replication machinery', 'Protein synthesis pathway', 'Cell division apparatus'], correctIndex: 0, explanation: 'The ETC in the inner mitochondrial membrane transfers electrons through complexes I-IV, pumping protons to create the gradient driving ATP synthase.' },
  { id: 'b_h21', difficulty: 'hard', question: 'What is phylogenetics?', options: ['Study of evolutionary relationships among organisms', 'Cell structure study', 'Protein folding', 'Hormone regulation'], correctIndex: 0, explanation: 'Phylogenetics reconstructs evolutionary trees showing relationships between species based on shared characteristics and molecular data.' },
  { id: 'b_h22', difficulty: 'hard', question: 'What is an operon?', options: ['Cluster of genes under control of a single promoter', 'Single gene', 'Protein', 'Organelle'], correctIndex: 0, explanation: 'An operon is a functional unit of genomic DNA containing a cluster of genes under the control of a single promoter, common in prokaryotes.' },
  { id: 'b_h23', difficulty: 'hard', question: 'What is the bottleneck effect?', options: ['Dramatic reduction in population size reducing genetic diversity', 'Population growth', 'Natural selection', 'Gene flow increase'], correctIndex: 0, explanation: 'The bottleneck effect occurs when a population is drastically reduced, causing loss of genetic variation and potentially new allele frequencies.' },
  { id: 'b_h24', difficulty: 'hard', question: 'What is proteomics?', options: ['Large-scale study of all proteins in an organism', 'DNA sequencing', 'RNA analysis', 'Cell counting'], correctIndex: 0, explanation: 'Proteomics is the comprehensive study of the entire set of proteins (proteome) produced by an organism, including structure and function.' },
  { id: 'b_h25', difficulty: 'hard', question: 'What is a transcription factor?', options: ['Protein that controls gene expression by binding to DNA', 'RNA polymerase', 'Ribosome component', 'Lipid molecule'], correctIndex: 0, explanation: 'Transcription factors are proteins that bind to specific DNA sequences to regulate the rate of gene transcription.' },
  { id: 'b_h26', difficulty: 'hard', question: 'What is the Hayflick limit?', options: ['Maximum number of times a cell can divide (~50-70 for human cells)', 'Unlimited division', 'Cell size limit', 'Organ size limit'], correctIndex: 0, explanation: 'The Hayflick limit is the number of times a normal cell can divide before stopping (~50-70 times), related to telomere shortening.' },
  { id: 'b_h27', difficulty: 'hard', question: 'What is quorum sensing?', options: ['Bacterial communication based on population density', 'Plant signaling', 'Nerve impulse', 'Hormone release'], correctIndex: 0, explanation: 'Quorum sensing allows bacteria to coordinate gene expression collectively based on their population density using signaling molecules.' },
  { id: 'b_h28', difficulty: 'hard', question: 'What is autophagy?', options: ['Cell\'s self-digestion of damaged organelles for recycling', 'Cell growth', 'Cell migration', 'Cell fusion'], correctIndex: 0, explanation: 'Autophagy is a cellular housekeeping process where cells degrade and recycle damaged organelles and proteins within lysosomes.' },
  { id: 'b_h29', difficulty: 'hard', question: 'What is the founder effect?', options: ['Loss of genetic variation when small group colonizes new area', 'Population explosion', 'Increased diversity', 'Natural selection'], correctIndex: 0, explanation: 'The founder effect occurs when a small group of individuals establishes a new population with less genetic diversity than the original.' },
  { id: 'b_h30', difficulty: 'hard', question: 'What is alternative splicing?', options: ['Single gene producing multiple mRNA variants and proteins', 'DNA mutation', 'Gene deletion', 'Chromosome crossing over'], correctIndex: 0, explanation: 'Alternative splicing allows a single gene to code for multiple proteins by including/excluding different exons during mRNA processing.' },
  { id: 'b_h31', difficulty: 'hard', question: 'What is a restriction enzyme?', options: ['Enzyme that cuts DNA at specific recognition sequences', 'Enzyme that joins DNA', 'RNA polymerase', 'Protease'], correctIndex: 0, explanation: 'Restriction enzymes (endonucleases) cut DNA at specific palindromic sequences, essential tools in molecular biology and genetic engineering.' },
  { id: 'b_h32', difficulty: 'hard', question: 'What is the endoplasmic reticulum stress response?', options: ['Cellular response to accumulation of misfolded proteins in the ER', 'Normal protein folding', 'DNA repair', 'Cell division'], correctIndex: 0, explanation: 'ER stress response (unfolded protein response) is activated when misfolded proteins accumulate, attempting to restore normal ER function or trigger apoptosis.' },
  { id: 'b_h33', difficulty: 'hard', question: 'What is synteny?', options: ['Conservation of gene order between species on chromosomes', 'Gene mutation', 'Protein structure', 'Cell polarity'], correctIndex: 0, explanation: 'Synteny refers to the preserved order of genes on chromosomes across different species, evidence of common ancestry.' },
  { id: 'b_h34', difficulty: 'hard', question: 'What is a tumor suppressor gene?', options: ['Gene that regulates cell growth and prevents cancer when functioning normally', 'Gene causing cancer', 'Gene for tumor growth', 'Oncogene'], correctIndex: 0, explanation: 'Tumor suppressor genes (like p53, Rb) normally prevent excessive cell division. Their loss of function can lead to cancer.' },
  { id: 'b_h35', difficulty: 'hard', question: 'What is the difference between innate and adaptive immunity?', options: ['Innate is non-specific and immediate; adaptive is specific and develops memory', 'They are the same', 'Innate is slower', 'Adaptive has no memory'], correctIndex: 0, explanation: 'Innate immunity provides immediate, non-specific defense; adaptive immunity develops specific responses and immunological memory.' },
  { id: 'b_h36', difficulty: 'hard', question: 'What is a plasmid?', options: ['Small circular DNA molecule in bacteria, separate from chromosomal DNA', 'Part of the chromosome', 'RNA molecule', 'Protein'], correctIndex: 0, explanation: 'Plasmids are small, self-replicating circular DNA molecules in bacteria, often carrying antibiotic resistance genes.' },
  { id: 'b_h37', difficulty: 'hard', question: 'What is the chemiosmotic theory?', options: ['ATP synthesis driven by proton gradient across a membrane', 'Direct chemical coupling', 'Substrate phosphorylation', 'Fermentation theory'], correctIndex: 0, explanation: 'Peter Mitchell\'s chemiosmotic theory explains ATP synthesis: the electron transport chain creates a proton gradient that drives ATP synthase.' },
  { id: 'b_h38', difficulty: 'hard', question: 'What is a monoclonal antibody?', options: ['Identical antibodies produced by a single clone of B cells', 'Mixed antibodies', 'Antigen', 'T cell receptor'], correctIndex: 0, explanation: 'Monoclonal antibodies are identical immunoglobulins made by clones of a single B cell, used in diagnostics and therapeutics.' },
  { id: 'b_h39', difficulty: 'hard', question: 'What is the central role of p53?', options: ['Tumor suppressor that triggers cell cycle arrest, DNA repair, or apoptosis', 'Cell growth promoter', 'Hormone receptor', 'Metabolic enzyme'], correctIndex: 0, explanation: 'p53 is the "guardian of the genome" — it responds to DNA damage by halting the cell cycle, promoting repair, or initiating apoptosis.' },
  { id: 'b_h40', difficulty: 'hard', question: 'What is the microRNA (miRNA)?', options: ['Small non-coding RNA that regulates gene expression post-transcriptionally', 'Messenger RNA', 'Transfer RNA', 'Ribosomal RNA'], correctIndex: 0, explanation: 'miRNAs are ~22 nucleotide non-coding RNAs that silence genes by binding to complementary mRNA, preventing translation.' },
  { id: 'b_h41', difficulty: 'hard', question: 'What is the Warburg effect?', options: ['Cancer cells preferentially use glycolysis even with oxygen available', 'Normal respiration', 'Photosynthesis in animals', 'Fermentation in plants'], correctIndex: 0, explanation: 'The Warburg effect describes cancer cells\' tendency to rely on glycolysis rather than oxidative phosphorylation, even in the presence of oxygen.' },
  { id: 'b_h42', difficulty: 'hard', question: 'What is chromatin remodeling?', options: ['Dynamic modification of chromatin structure to regulate gene access', 'DNA deletion', 'Chromosome duplication', 'Cell division'], correctIndex: 0, explanation: 'Chromatin remodeling changes the structure of chromatin (DNA-histone complex) to expose or hide genes for transcription.' },
  { id: 'b_h43', difficulty: 'hard', question: 'What is synthetic biology?', options: ['Designing and constructing new biological parts and systems', 'Studying natural biology', 'Ecology', 'Taxonomy'], correctIndex: 0, explanation: 'Synthetic biology combines engineering principles with biology to design and build new biological components, devices, and systems.' },
  { id: 'b_h44', difficulty: 'hard', question: 'What is the two-hit hypothesis?', options: ['Both alleles of a tumor suppressor must be inactivated for cancer', 'One mutation causes cancer', 'Mutations are always inherited', 'Cancer is not genetic'], correctIndex: 0, explanation: 'Knudson\'s two-hit hypothesis states that both copies of a tumor suppressor gene must be mutated for loss of function leading to cancer.' },
  { id: 'b_h45', difficulty: 'hard', question: 'What is the difference between totipotent and pluripotent stem cells?', options: ['Totipotent can become any cell type including placenta; pluripotent can become any body cell but not placenta', 'They are identical', 'Pluripotent is more versatile', 'Totipotent cannot self-renew'], correctIndex: 0, explanation: 'Totipotent cells (zygote) can form all cell types including extraembryonic tissue; pluripotent cells can form all body cell types but not placental tissue.' },
  { id: 'b_h46', difficulty: 'hard', question: 'What is the complement system?', options: ['Cascade of proteins enhancing antibody and phagocytic cell pathogen clearance', 'Type of white blood cell', 'Antibody production', 'T cell activation'], correctIndex: 0, explanation: 'The complement system is a cascade of ~30 blood proteins that enhance (complement) the ability of antibodies and phagocytes to clear pathogens.' },
  { id: 'b_h47', difficulty: 'hard', question: 'What is gene drive technology?', options: ['System that biases inheritance to spread a gene through a population', 'Normal Mendelian inheritance', 'Genetic drift', 'Natural selection'], correctIndex: 0, explanation: 'Gene drives use CRISPR to ensure a genetic modification is inherited by nearly all offspring, potentially spreading through wild populations.' },
  { id: 'b_h48', difficulty: 'hard', question: 'What is the Central Limit Theorem\'s importance in biology?', options: ['Sampling distributions approach normal distribution regardless of population distribution', 'All biological data is normal', 'Sample size doesn\'t matter', 'Statistics don\'t apply to biology'], correctIndex: 0, explanation: 'The CLT allows biologists to use parametric statistics on sample means even when individual measurements aren\'t normally distributed.' },
  { id: 'b_h49', difficulty: 'hard', question: 'What is the Red Queen hypothesis?', options: ['Species must constantly evolve to survive alongside evolving competitors/parasites', 'Evolution stops', 'Only prey evolve', 'Only predators evolve'], correctIndex: 0, explanation: 'The Red Queen hypothesis suggests organisms must continuously adapt and evolve to maintain their relative fitness against co-evolving organisms.' },
  { id: 'b_h50', difficulty: 'hard', question: 'What is a phase-separated condensate in cells?', options: ['Membraneless organelle formed by liquid-liquid phase separation of proteins/RNA', 'Membrane-bound organelle', 'Crystal structure', 'Gas bubble'], correctIndex: 0, explanation: 'Biomolecular condensates are membraneless compartments formed by liquid-liquid phase separation, organizing biochemistry within cells.' },
];

// ══════════════════════════════════════════════════════════════
// EARTH & SPACE — 150 unique questions
// ══════════════════════════════════════════════════════════════
const earthSpacePool: Question[] = [
  // ── EASY (50) ──
  { id: 'e_e1', difficulty: 'easy', question: 'What is the closest star to Earth?', options: ['Proxima Centauri', 'Sirius', 'The Sun', 'Alpha Centauri A'], correctIndex: 2, explanation: 'The Sun is a star located about 150 million km from Earth — our nearest star.' },
  { id: 'e_e2', difficulty: 'easy', question: 'How many planets are in our solar system?', options: ['7', '8', '9', '10'], correctIndex: 1, explanation: 'There are 8 planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune.' },
  { id: 'e_e3', difficulty: 'easy', question: 'What is the hardest mineral on the Mohs scale?', options: ['Quartz', 'Topaz', 'Corundum', 'Diamond'], correctIndex: 3, explanation: 'Diamond scores 10 on the Mohs hardness scale, the maximum, due to its strong carbon-carbon bonds.' },
  { id: 'e_e4', difficulty: 'easy', question: 'What primarily causes ocean tides?', options: ['Wind', "Moon's gravitational pull", "Earth's rotation alone", 'Solar flares'], correctIndex: 1, explanation: 'Tides are primarily caused by the Moon\'s gravitational pull on Earth\'s oceans, with the Sun also contributing.' },
  { id: 'e_e5', difficulty: 'easy', question: 'Which atmosphere layer do we live in?', options: ['Stratosphere', 'Mesosphere', 'Troposphere', 'Thermosphere'], correctIndex: 2, explanation: 'The troposphere extends from the surface to about 12 km altitude, containing most of our weather.' },
  { id: 'e_e6', difficulty: 'easy', question: 'What is the largest planet in our solar system?', options: ['Saturn', 'Neptune', 'Jupiter', 'Uranus'], correctIndex: 2, explanation: 'Jupiter is the largest planet with a diameter of about 139,820 km — more than 11 times Earth\'s.' },
  { id: 'e_e7', difficulty: 'easy', question: 'What type of rock forms from cooled lava or magma?', options: ['Sedimentary', 'Metamorphic', 'Igneous', 'Limestone'], correctIndex: 2, explanation: 'Igneous rocks form when molten rock (magma or lava) cools and solidifies.' },
  { id: 'e_e8', difficulty: 'easy', question: 'The ozone layer protects us from:', options: ['Infrared radiation', 'UV radiation', 'Cosmic rays', 'Radio waves'], correctIndex: 1, explanation: 'The ozone layer in the stratosphere absorbs most of the Sun\'s harmful ultraviolet (UV) radiation.' },
  { id: 'e_e9', difficulty: 'easy', question: 'A light-year measures:', options: ['Time', 'Speed', 'Distance', 'Brightness'], correctIndex: 2, explanation: 'A light-year is the distance light travels in one year: about 9.46 trillion kilometers.' },
  { id: 'e_e10', difficulty: 'easy', question: 'Which planet is known as the Red Planet?', options: ['Venus', 'Mars', 'Jupiter', 'Mercury'], correctIndex: 1, explanation: 'Mars appears red due to iron oxide (rust) on its surface.' },
  { id: 'e_e11', difficulty: 'easy', question: 'What is the name of our galaxy?', options: ['Andromeda', 'Milky Way', 'Triangulum', 'Sombrero'], correctIndex: 1, explanation: 'Our solar system is located in the Milky Way, a barred spiral galaxy containing 100-400 billion stars.' },
  { id: 'e_e12', difficulty: 'easy', question: 'What scale measures earthquake magnitude?', options: ['Beaufort', 'Richter', 'Kelvin', 'Decibel'], correctIndex: 1, explanation: 'The Richter scale (and moment magnitude scale) measures the energy released by earthquakes.' },
  { id: 'e_e13', difficulty: 'easy', question: 'Approximately how long does sunlight take to reach Earth?', options: ['1 minute', '8 minutes', '1 hour', '24 hours'], correctIndex: 1, explanation: 'Light from the Sun takes about 8 minutes and 20 seconds to travel the 150 million km to Earth.' },
  { id: 'e_e14', difficulty: 'easy', question: 'What is Saturn known for?', options: ['Red spot', 'Prominent ring system', 'Being closest to Sun', 'Having no moons'], correctIndex: 1, explanation: 'Saturn is famous for its extensive ring system made of ice and rock particles.' },
  { id: 'e_e15', difficulty: 'easy', question: 'What are the three types of rocks?', options: ['Igneous, sedimentary, metamorphic', 'Hard, soft, medium', 'Light, dark, colorful', 'Granite, marble, slate'], correctIndex: 0, explanation: 'Rocks are classified into igneous (from cooling magma), sedimentary (from compressed sediments), and metamorphic (changed by heat/pressure).' },
  { id: 'e_e16', difficulty: 'easy', question: 'What is the hottest planet in our solar system?', options: ['Mercury', 'Venus', 'Mars', 'Jupiter'], correctIndex: 1, explanation: 'Venus is the hottest planet (~465°C) due to its dense CO₂ atmosphere creating a runaway greenhouse effect.' },
  { id: 'e_e17', difficulty: 'easy', question: 'What causes wind?', options: ['Earth\'s rotation only', 'Differences in air pressure', 'Ocean currents', 'Magnetic fields'], correctIndex: 1, explanation: 'Wind is caused by differences in atmospheric pressure. Air flows from high-pressure to low-pressure areas.' },
  { id: 'e_e18', difficulty: 'easy', question: 'What is the Earth\'s main source of heat?', options: ['The Moon', 'The Sun', 'Earth\'s core only', 'Stars'], correctIndex: 1, explanation: 'The Sun provides virtually all the heat that warms Earth\'s surface and drives weather patterns.' },
  { id: 'e_e19', difficulty: 'easy', question: 'What is a volcano?', options: ['Opening where magma erupts to surface', 'Deep ocean trench', 'Mountain formed by folding', 'A type of earthquake'], correctIndex: 0, explanation: 'A volcano is an opening in Earth\'s crust where molten rock, gases, and ash can escape from below.' },
  { id: 'e_e20', difficulty: 'easy', question: 'How long does Earth take to orbit the Sun?', options: ['24 hours', '30 days', '365.25 days', '28 days'], correctIndex: 2, explanation: 'Earth takes approximately 365.25 days to complete one orbit around the Sun (one year).' },
  { id: 'e_e21', difficulty: 'easy', question: 'What is the smallest planet in our solar system?', options: ['Mars', 'Mercury', 'Pluto', 'Venus'], correctIndex: 1, explanation: 'Mercury is the smallest planet with a diameter of about 4,879 km (Pluto is classified as a dwarf planet).' },
  { id: 'e_e22', difficulty: 'easy', question: 'What causes day and night?', options: ['Earth orbiting the Sun', 'Earth rotating on its axis', 'Moon blocking sunlight', 'Sun moving around Earth'], correctIndex: 1, explanation: 'Day and night are caused by Earth\'s rotation on its axis every 24 hours.' },
  { id: 'e_e23', difficulty: 'easy', question: 'What is a fossil?', options: ['Preserved remains of ancient organisms', 'A type of rock', 'A living organism', 'A mineral'], correctIndex: 0, explanation: 'Fossils are the preserved remains, impressions, or traces of organisms from past geological ages.' },
  { id: 'e_e24', difficulty: 'easy', question: 'What is the water cycle?', options: ['Continuous movement of water between Earth and atmosphere', 'Only rainfall', 'Only evaporation', 'River flow only'], correctIndex: 0, explanation: 'The water cycle includes evaporation, condensation, precipitation, and collection in a continuous loop.' },
  { id: 'e_e25', difficulty: 'easy', question: 'What is erosion?', options: ['Wearing away of land by wind, water, or ice', 'Rock formation', 'Volcanic eruption', 'Earthquake'], correctIndex: 0, explanation: 'Erosion is the gradual wearing away and transport of rock and soil by wind, water, ice, or gravity.' },
  { id: 'e_e26', difficulty: 'easy', question: 'What is Earth\'s natural satellite?', options: ['Sun', 'Mars', 'Moon', 'Venus'], correctIndex: 2, explanation: 'The Moon is Earth\'s only natural satellite, orbiting at an average distance of about 384,400 km.' },
  { id: 'e_e27', difficulty: 'easy', question: 'What is the outer layer of the Earth called?', options: ['Mantle', 'Core', 'Crust', 'Magma'], correctIndex: 2, explanation: 'Earth\'s crust is the thin, solid outermost layer, ranging from 5-70 km thick.' },
  { id: 'e_e28', difficulty: 'easy', question: 'What is a meteorite?', options: ['Space rock that reaches Earth\'s surface', 'Shooting star', 'Comet', 'Asteroid in orbit'], correctIndex: 0, explanation: 'A meteorite is a fragment of space rock or metal that survives passage through Earth\'s atmosphere and lands on the surface.' },
  { id: 'e_e29', difficulty: 'easy', question: 'What is the main gas in the Sun?', options: ['Oxygen', 'Hydrogen', 'Helium', 'Nitrogen'], correctIndex: 1, explanation: 'The Sun is about 75% hydrogen by mass, which fuses into helium in its core.' },
  { id: 'e_e30', difficulty: 'easy', question: 'What is a constellation?', options: ['Pattern of stars as seen from Earth', 'Group of planets', 'Galaxy cluster', 'Solar system'], correctIndex: 0, explanation: 'A constellation is a recognizable pattern of stars as viewed from Earth. There are 88 officially recognized constellations.' },
  { id: 'e_e31', difficulty: 'easy', question: 'What forms clouds?', options: ['Dust particles only', 'Water vapor condensing on particles', 'Smoke', 'Chemical reactions'], correctIndex: 1, explanation: 'Clouds form when water vapor in the atmosphere condenses on tiny particles (condensation nuclei) like dust or pollen.' },
  { id: 'e_e32', difficulty: 'easy', question: 'What is the equator?', options: ['Imaginary line dividing Earth into northern and southern hemispheres', 'North pole', 'A continent', 'A time zone'], correctIndex: 0, explanation: 'The equator is the imaginary circle at 0° latitude, dividing Earth into the Northern and Southern hemispheres.' },
  { id: 'e_e33', difficulty: 'easy', question: 'What is a comet?', options: ['Icy body that develops a tail near the Sun', 'A type of star', 'A planet', 'A satellite'], correctIndex: 0, explanation: 'Comets are icy bodies that develop a visible atmosphere (coma) and sometimes a tail when near the Sun due to solar heating.' },
  { id: 'e_e34', difficulty: 'easy', question: 'What is soil made of?', options: ['Only rocks', 'Minerals, organic matter, water, and air', 'Only sand', 'Only clay'], correctIndex: 1, explanation: 'Soil is a mixture of mineral particles, organic matter (humus), water, air, and living organisms.' },
  { id: 'e_e35', difficulty: 'easy', question: 'What is an orbit?', options: ['Path one object takes around another', 'The center of a planet', 'A type of rock', 'An earthquake measurement'], correctIndex: 0, explanation: 'An orbit is the curved path an object takes around a larger body due to gravity.' },
  { id: 'e_e36', difficulty: 'easy', question: 'What is a glacier?', options: ['Large mass of slowly moving ice', 'A frozen lake', 'An iceberg', 'A snowstorm'], correctIndex: 0, explanation: 'Glaciers are large, persistent bodies of ice that form from compacted snow and slowly flow under their own weight.' },
  { id: 'e_e37', difficulty: 'easy', question: 'What planet has the Great Red Spot?', options: ['Mars', 'Saturn', 'Jupiter', 'Neptune'], correctIndex: 2, explanation: 'Jupiter\'s Great Red Spot is a massive storm (anticyclone) that has been raging for at least 400 years.' },
  { id: 'e_e38', difficulty: 'easy', question: 'What is weathering?', options: ['Breaking down of rocks by weather, chemicals, or living things', 'Weather forecasting', 'Wind speed measurement', 'Cloud formation'], correctIndex: 0, explanation: 'Weathering is the breakdown of rocks and minerals through physical, chemical, or biological processes without transport.' },
  { id: 'e_e39', difficulty: 'easy', question: 'What is the International Space Station (ISS)?', options: ['Habitable satellite orbiting Earth', 'A telescope', 'A planet', 'A space shuttle'], correctIndex: 0, explanation: 'The ISS is a modular space station in low Earth orbit serving as a laboratory for scientific research in microgravity.' },
  { id: 'e_e40', difficulty: 'easy', question: 'What is the Milky Way\'s shape?', options: ['Elliptical', 'Barred spiral', 'Irregular', 'Spherical'], correctIndex: 1, explanation: 'The Milky Way is a barred spiral galaxy with a central bar-shaped structure of stars.' },
  { id: 'e_e41', difficulty: 'easy', question: 'What is an asteroid?', options: ['Small rocky body orbiting the Sun', 'A type of star', 'A moon', 'A comet'], correctIndex: 0, explanation: 'Asteroids are small, rocky objects that orbit the Sun, mostly found in the asteroid belt between Mars and Jupiter.' },
  { id: 'e_e42', difficulty: 'easy', question: 'What is the atmosphere?', options: ['Layer of gases surrounding Earth', 'The ocean', 'Earth\'s core', 'The Moon\'s surface'], correctIndex: 0, explanation: 'Earth\'s atmosphere is the layer of gases (mainly nitrogen and oxygen) held by gravity, protecting life and moderating temperature.' },
  { id: 'e_e43', difficulty: 'easy', question: 'What is a stalactite?', options: ['Mineral formation hanging from a cave ceiling', 'Growing from cave floor', 'A type of fossil', 'A type of mineral'], correctIndex: 0, explanation: 'Stalactites hang from cave ceilings, formed by mineral-rich water dripping and depositing calcium carbonate over time.' },
  { id: 'e_e44', difficulty: 'easy', question: 'What is the ring of fire?', options: ['Area around Pacific Ocean with many volcanoes and earthquakes', 'Saturn\'s rings', 'The Sun\'s corona', 'A type of eclipse'], correctIndex: 0, explanation: 'The Ring of Fire is a horseshoe-shaped zone around the Pacific Ocean where about 75% of the world\'s volcanoes are found.' },
  { id: 'e_e45', difficulty: 'easy', question: 'What are the four seasons?', options: ['Spring, Summer, Autumn, Winter', 'Hot, Cold, Warm, Cool', 'Wet, Dry, Windy, Calm', 'Morning, Afternoon, Evening, Night'], correctIndex: 0, explanation: 'The four seasons — spring, summer, autumn (fall), and winter — are caused by Earth\'s axial tilt as it orbits the Sun.' },
  { id: 'e_e46', difficulty: 'easy', question: 'What is the deepest point in the ocean?', options: ['Mid-Atlantic Ridge', 'Mariana Trench', 'Great Barrier Reef', 'Hawaiian trench'], correctIndex: 1, explanation: 'The Mariana Trench in the Pacific Ocean is the deepest point, reaching about 10,994 meters (Challenger Deep).' },
  { id: 'e_e47', difficulty: 'easy', question: 'What causes a solar eclipse?', options: ['Moon blocks sunlight from reaching Earth', 'Earth blocks sunlight from Moon', 'Sun moves behind Moon', 'Stars align'], correctIndex: 0, explanation: 'A solar eclipse occurs when the Moon passes between the Sun and Earth, casting a shadow on Earth.' },
  { id: 'e_e48', difficulty: 'easy', question: 'What is a hurricane?', options: ['Large rotating storm with high winds forming over warm ocean', 'A tornado', 'An earthquake', 'A flood'], correctIndex: 0, explanation: 'Hurricanes are large, organized storms with sustained winds ≥119 km/h, forming over warm tropical waters.' },
  { id: 'e_e49', difficulty: 'easy', question: 'What is magma?', options: ['Molten rock beneath Earth\'s surface', 'A type of mineral', 'Ocean water', 'Atmospheric gas'], correctIndex: 0, explanation: 'Magma is molten rock found beneath Earth\'s surface. When it reaches the surface through eruption, it\'s called lava.' },
  { id: 'e_e50', difficulty: 'easy', question: 'What are the inner planets of our solar system?', options: ['Mercury, Venus, Earth, Mars', 'Jupiter, Saturn, Uranus, Neptune', 'Earth, Mars, Jupiter, Saturn', 'Mercury, Mars, Jupiter, Saturn'], correctIndex: 0, explanation: 'The inner (terrestrial) planets — Mercury, Venus, Earth, Mars — are rocky planets closest to the Sun.' },

  // ── MEDIUM (50) ──
  { id: 'e_m1', difficulty: 'medium', question: 'What is a supernova?', options: ['Explosion marking death of a massive star', 'Birth of a new star', 'A black hole', 'A comet impact'], correctIndex: 0, explanation: 'A supernova is a powerful stellar explosion that occurs when a massive star exhausts its nuclear fuel and collapses.' },
  { id: 'e_m2', difficulty: 'medium', question: 'What causes seasons on Earth?', options: ['Distance from Sun', 'Axial tilt of 23.5°', 'Moon phases', 'Solar flares'], correctIndex: 1, explanation: 'Earth\'s 23.5° axial tilt causes different hemispheres to receive varying amounts of sunlight throughout the year.' },
  { id: 'e_m3', difficulty: 'medium', question: 'What is the Kuiper Belt?', options: ['Region of icy bodies beyond Neptune', "Jupiter's rings", 'The asteroid belt', 'Solar corona'], correctIndex: 0, explanation: 'The Kuiper Belt is a disc-shaped region beyond Neptune containing dwarf planets (like Pluto) and icy bodies.' },
  { id: 'e_m4', difficulty: 'medium', question: 'What is plate tectonics?', options: ['Theory that Earth\'s crust is divided into moving plates', 'Ocean current theory', 'Wind pattern theory', 'Magnetic field theory'], correctIndex: 0, explanation: 'Plate tectonics explains how Earth\'s lithosphere is divided into plates that float on the asthenosphere and interact at boundaries.' },
  { id: 'e_m5', difficulty: 'medium', question: 'What is a nebula?', options: ['Cloud of gas and dust in space', 'A type of star', 'A galaxy cluster', 'Dark matter'], correctIndex: 0, explanation: 'Nebulae are vast clouds of gas (mostly hydrogen) and dust where new stars are born.' },
  { id: 'e_m6', difficulty: 'medium', question: 'What is the Coriolis effect?', options: ['Deflection of moving objects due to Earth\'s rotation', 'Tidal forces', 'Magnetic pole shifting', 'Gravity variation'], correctIndex: 0, explanation: 'The Coriolis effect deflects moving objects (like winds) to the right in the Northern Hemisphere and left in the Southern.' },
  { id: 'e_m7', difficulty: 'medium', question: 'What is Earth\'s core mainly composed of?', options: ['Silicon', 'Magnesium', 'Iron and nickel', 'Carbon'], correctIndex: 2, explanation: 'Earth\'s core is primarily iron (~85%) and nickel (~10%), with the inner core being solid and outer core liquid.' },
  { id: 'e_m8', difficulty: 'medium', question: 'What is the main fuel of the Sun?', options: ['Helium', 'Hydrogen', 'Carbon', 'Oxygen'], correctIndex: 1, explanation: 'The Sun fuses hydrogen into helium in its core, converting about 600 million tons of hydrogen every second.' },
  { id: 'e_m9', difficulty: 'medium', question: 'What is Saturn\'s largest moon?', options: ['Europa', 'Ganymede', 'Titan', 'Io'], correctIndex: 2, explanation: 'Titan is Saturn\'s largest moon and the second largest in the solar system, with a dense nitrogen atmosphere.' },
  { id: 'e_m10', difficulty: 'medium', question: 'What causes auroras?', options: ['Solar wind interacting with Earth\'s magnetosphere', 'Moon reflection', 'Volcanic gases', 'Cloud refraction'], correctIndex: 0, explanation: 'Auroras occur when charged particles from the solar wind interact with gases in Earth\'s upper atmosphere along magnetic field lines.' },
  { id: 'e_m11', difficulty: 'medium', question: 'What is a geode?', options: ['Rock with crystals inside a hollow cavity', 'Type of fossil', 'Volcanic glass', 'Sedimentary layer'], correctIndex: 0, explanation: 'Geodes are rounded rocks with hollow interiors lined with crystals, formed by mineral-rich water seeping into rock cavities.' },
  { id: 'e_m12', difficulty: 'medium', question: 'What is the difference between weather and climate?', options: ['Weather is short-term atmospheric conditions; climate is long-term average', 'They are the same', 'Climate is daily', 'Weather is over decades'], correctIndex: 0, explanation: 'Weather describes atmospheric conditions over short periods (hours-days); climate is the average weather pattern over decades.' },
  { id: 'e_m13', difficulty: 'medium', question: 'What is a fault line?', options: ['Fracture in Earth\'s crust where blocks of rock move', 'An ocean trench', 'A river bed', 'A mountain peak'], correctIndex: 0, explanation: 'A fault is a fracture in Earth\'s crust along which blocks of rock have moved relative to each other.' },
  { id: 'e_m14', difficulty: 'medium', question: 'What is the asthenosphere?', options: ['Partially molten layer below the lithosphere', 'Solid inner core', 'Outer atmosphere', 'Ocean floor'], correctIndex: 0, explanation: 'The asthenosphere is the semi-fluid layer of the upper mantle below the lithosphere, allowing tectonic plates to move.' },
  { id: 'e_m15', difficulty: 'medium', question: 'What is a tsunami?', options: ['Large ocean wave caused by underwater earthquakes', 'A hurricane', 'A tidal wave from the Moon', 'An ocean current'], correctIndex: 0, explanation: 'Tsunamis are massive waves generated by underwater earthquakes, volcanic eruptions, or landslides displacing water.' },
  { id: 'e_m16', difficulty: 'medium', question: 'What is the rock cycle?', options: ['Process by which rocks are transformed between igneous, sedimentary, and metamorphic', 'Rocks orbiting Earth', 'Only erosion', 'Only volcanic activity'], correctIndex: 0, explanation: 'The rock cycle describes the continuous transformation of rocks through processes like melting, weathering, compaction, and metamorphism.' },
  { id: 'e_m17', difficulty: 'medium', question: 'What is a black hole?', options: ['Region where gravity is so strong nothing can escape, not even light', 'Dark nebula', 'Empty space', 'Dead star visible as dark spot'], correctIndex: 0, explanation: 'A black hole forms when a massive star collapses, creating a region with such intense gravity that even light cannot escape.' },
  { id: 'e_m18', difficulty: 'medium', question: 'What is continental drift?', options: ['Gradual movement of continents across Earth\'s surface', 'Earthquakes', 'Ocean currents moving land', 'Wind erosion of continents'], correctIndex: 0, explanation: 'Continental drift, proposed by Wegener, describes how continents slowly move over geological time, now explained by plate tectonics.' },
  { id: 'e_m19', difficulty: 'medium', question: 'What is the greenhouse effect?', options: ['Atmospheric gases trapping heat from the Sun', 'Growing plants in greenhouses', 'Ozone depletion', 'UV radiation'], correctIndex: 0, explanation: 'Greenhouse gases (CO₂, methane, water vapor) trap infrared radiation, warming Earth\'s surface above what it would be otherwise.' },
  { id: 'e_m20', difficulty: 'medium', question: 'What is the magnetosphere?', options: ['Region around Earth dominated by its magnetic field', 'The atmosphere', 'Earth\'s core', 'The Moon\'s orbit'], correctIndex: 0, explanation: 'Earth\'s magnetosphere is the region of space dominated by Earth\'s magnetic field, deflecting most solar wind particles.' },
  { id: 'e_m21', difficulty: 'medium', question: 'What are seismic waves?', options: ['Energy waves traveling through Earth from earthquakes', 'Ocean waves', 'Sound waves in air', 'Light waves'], correctIndex: 0, explanation: 'Seismic waves are vibrations that travel through Earth\'s interior and surface, generated by earthquakes, volcanism, or explosions.' },
  { id: 'e_m22', difficulty: 'medium', question: 'What is a main sequence star?', options: ['Star fusing hydrogen in its core, on the main band of the H-R diagram', 'Dying star', 'Brown dwarf', 'Neutron star'], correctIndex: 0, explanation: 'Main sequence stars fuse hydrogen into helium in their cores. Our Sun is a main sequence star, spending ~90% of its life in this phase.' },
  { id: 'e_m23', difficulty: 'medium', question: 'What is the difference between a meteor and a meteorite?', options: ['Meteor burns in atmosphere; meteorite reaches the ground', 'They are the same', 'Meteorite is in space', 'Meteor is on the ground'], correctIndex: 0, explanation: 'A meteor is the streak of light (shooting star) as a space rock burns in the atmosphere; a meteorite is the fragment that survives to reach the ground.' },
  { id: 'e_m24', difficulty: 'medium', question: 'What is an exoplanet?', options: ['Planet orbiting a star other than our Sun', 'A moon of Jupiter', 'Dwarf planet in our solar system', 'Asteroid'], correctIndex: 0, explanation: 'Exoplanets orbit stars beyond our solar system. Over 5,000 have been confirmed as of 2024.' },
  { id: 'e_m25', difficulty: 'medium', question: 'What is subduction?', options: ['One tectonic plate sliding under another', 'Two plates moving apart', 'Plates sliding past each other', 'Volcanic eruption'], correctIndex: 0, explanation: 'Subduction occurs at convergent boundaries where a denser plate slides under a less dense plate, often creating deep ocean trenches.' },
  { id: 'e_m26', difficulty: 'medium', question: 'What is the habitable zone?', options: ['Region around a star where liquid water could exist on a planet', 'Any orbit', 'The entire galaxy', 'Earth\'s atmosphere'], correctIndex: 0, explanation: 'The habitable zone (Goldilocks zone) is the orbital region where temperatures allow liquid water on a planet\'s surface.' },
  { id: 'e_m27', difficulty: 'medium', question: 'What type of galaxy is the Milky Way?', options: ['Elliptical', 'Barred spiral', 'Irregular', 'Lenticular'], correctIndex: 1, explanation: 'The Milky Way is a barred spiral galaxy, about 100,000 light-years in diameter with a central bar structure.' },
  { id: 'e_m28', difficulty: 'medium', question: 'What is the Mohorovičić discontinuity?', options: ['Boundary between Earth\'s crust and mantle', 'Core-mantle boundary', 'Atmosphere-space boundary', 'Ocean-land boundary'], correctIndex: 0, explanation: 'The "Moho" is the boundary between the crust and mantle, detected by changes in seismic wave velocity.' },
  { id: 'e_m29', difficulty: 'medium', question: 'What is a red giant?', options: ['Evolved star that has expanded and cooled', 'Young star', 'Neutron star', 'White dwarf'], correctIndex: 0, explanation: 'A red giant is a late-stage star that has exhausted hydrogen in its core, causing it to expand and cool, turning red.' },
  { id: 'e_m30', difficulty: 'medium', question: 'What is the Pangaea?', options: ['Ancient supercontinent that existed about 300 million years ago', 'A current continent', 'An ocean', 'A galaxy'], correctIndex: 0, explanation: 'Pangaea was a supercontinent that included all present-day landmasses, which began to break apart about 200 million years ago.' },
  { id: 'e_m31', difficulty: 'medium', question: 'What is the difference between P-waves and S-waves?', options: ['P-waves are faster compression waves; S-waves are slower shear waves', 'They are identical', 'S-waves are faster', 'P-waves only travel through liquids'], correctIndex: 0, explanation: 'P-waves (primary) are compressional and travel through solids and liquids; S-waves (secondary) are transverse and only travel through solids.' },
  { id: 'e_m32', difficulty: 'medium', question: 'What is the solar wind?', options: ['Stream of charged particles from the Sun', 'Wind on the Sun\'s surface', 'Light from the Sun', 'Gravitational force'], correctIndex: 0, explanation: 'Solar wind is a continuous stream of protons and electrons flowing from the Sun\'s corona at ~400-800 km/s.' },
  { id: 'e_m33', difficulty: 'medium', question: 'What is the mid-ocean ridge?', options: ['Underwater mountain range where new ocean floor is created', 'Deepest ocean trench', 'Continental shelf edge', 'Coral reef system'], correctIndex: 0, explanation: 'Mid-ocean ridges are divergent plate boundaries where magma rises to create new oceanic crust (seafloor spreading).' },
  { id: 'e_m34', difficulty: 'medium', question: 'What is the albedo of a surface?', options: ['Fraction of sunlight it reflects', 'Its temperature', 'Its color', 'Its height'], correctIndex: 0, explanation: 'Albedo is the proportion of incident light reflected by a surface. Ice has high albedo (~0.9); dark ocean has low albedo (~0.06).' },
  { id: 'e_m35', difficulty: 'medium', question: 'What is a white dwarf?', options: ['Dense stellar remnant after a sun-like star dies', 'Young star', 'Massive star', 'Gas giant'], correctIndex: 0, explanation: 'A white dwarf is the dense, hot remnant of a low-to-medium mass star after it has shed its outer layers.' },
  { id: 'e_m36', difficulty: 'medium', question: 'What is radioactive dating used for?', options: ['Determining the age of rocks and fossils', 'Finding radiation levels', 'Measuring temperature', 'Predicting earthquakes'], correctIndex: 0, explanation: 'Radiometric dating uses the known decay rates of radioactive isotopes to determine the age of geological materials.' },
  { id: 'e_m37', difficulty: 'medium', question: 'What is the jet stream?', options: ['Narrow band of fast-moving air in the upper atmosphere', 'Ocean current', 'Volcanic gas stream', 'Solar wind'], correctIndex: 0, explanation: 'Jet streams are narrow bands of strong winds at high altitudes (typically 9-12 km) that influence weather patterns.' },
  { id: 'e_m38', difficulty: 'medium', question: 'What is a pulsar?', options: ['Rapidly rotating neutron star emitting beams of radiation', 'A planet', 'A galaxy', 'A comet'], correctIndex: 0, explanation: 'Pulsars are neutron stars that rotate rapidly and emit beams of electromagnetic radiation from their magnetic poles.' },
  { id: 'e_m39', difficulty: 'medium', question: 'What is isostasy?', options: ['Gravitational equilibrium of Earth\'s crust floating on the mantle', 'Atmospheric pressure', 'Ocean salinity balance', 'Magnetic field strength'], correctIndex: 0, explanation: 'Isostasy describes how Earth\'s crust "floats" on the denser mantle, rising or sinking to achieve gravitational equilibrium.' },
  { id: 'e_m40', difficulty: 'medium', question: 'What is the Oort Cloud?', options: ['Theoretical spherical cloud of icy bodies at the edge of the solar system', 'A nebula', 'Jupiter\'s atmosphere', 'Saturn\'s rings'], correctIndex: 0, explanation: 'The Oort Cloud is a hypothesized spherical shell of icy objects surrounding the solar system at vast distances (up to 100,000 AU).' },
  { id: 'e_m41', difficulty: 'medium', question: 'What is the mantle?', options: ['Thick layer between Earth\'s crust and core', 'The atmosphere', 'The ocean floor', 'Earth\'s surface'], correctIndex: 0, explanation: 'Earth\'s mantle is approximately 2,900 km thick, composed of silicate rocks rich in iron and magnesium.' },
  { id: 'e_m42', difficulty: 'medium', question: 'What is a stratovolcano?', options: ['Steep conical volcano built of alternating lava and ash layers', 'Flat shield volcano', 'Underwater volcano only', 'Extinct volcano'], correctIndex: 0, explanation: 'Stratovolcanoes (composite volcanoes) are tall, steep volcanoes built from layers of lava, ash, and rock. Examples: Mt. Fuji, Mt. Vesuvius.' },
  { id: 'e_m43', difficulty: 'medium', question: 'What is the Big Bang theory?', options: ['Universe expanded from an extremely hot, dense state ~13.8 billion years ago', 'Universe was always the same', 'Universe is shrinking', 'Stars created the universe'], correctIndex: 0, explanation: 'The Big Bang theory states that the universe began as an extremely hot, dense point ~13.8 billion years ago and has been expanding since.' },
  { id: 'e_m44', difficulty: 'medium', question: 'What is a transform fault boundary?', options: ['Where two tectonic plates slide past each other horizontally', 'Where plates collide', 'Where plates separate', 'Where plates subduct'], correctIndex: 0, explanation: 'Transform boundaries occur where plates slide horizontally past each other. The San Andreas Fault is a famous example.' },
  { id: 'e_m45', difficulty: 'medium', question: 'What is a neutron star?', options: ['Ultra-dense remnant of a massive star after supernova', 'A star made of neutrons only', 'A young star', 'A gas giant'], correctIndex: 0, explanation: 'Neutron stars are incredibly dense stellar remnants (~2 solar masses in ~20 km diameter) formed when massive stars collapse in supernovae.' },
  { id: 'e_m46', difficulty: 'medium', question: 'What is the thermosphere?', options: ['Atmosphere layer (80-700 km) where temperature increases with altitude', 'Lowest atmosphere layer', 'Layer with the ozone', 'The ground layer'], correctIndex: 0, explanation: 'The thermosphere (80-700 km) has temperatures reaching 2,500°C due to absorption of solar UV and X-ray radiation.' },
  { id: 'e_m47', difficulty: 'medium', question: 'What is El Niño?', options: ['Warming of equatorial Pacific Ocean waters affecting global weather', 'A hurricane', 'A volcano', 'An earthquake type'], correctIndex: 0, explanation: 'El Niño is a climate pattern where equatorial Pacific waters warm unusually, disrupting weather patterns worldwide.' },
  { id: 'e_m48', difficulty: 'medium', question: 'What is the Hertzsprung-Russell diagram?', options: ['Chart plotting star luminosity versus temperature', 'Planet orbit diagram', 'Galaxy classification', 'Comet trajectory'], correctIndex: 0, explanation: 'The H-R diagram plots stars by luminosity (brightness) versus surface temperature, revealing distinct groups (main sequence, giants, dwarfs).' },
  { id: 'e_m49', difficulty: 'medium', question: 'What is the lithosphere?', options: ['Rigid outer layer of Earth including crust and upper mantle', 'Only the crust', 'Only the mantle', 'Earth\'s core'], correctIndex: 0, explanation: 'The lithosphere is the rigid outer shell (~100 km thick) comprising the crust and uppermost solid mantle, divided into tectonic plates.' },
  { id: 'e_m50', difficulty: 'medium', question: 'What is a geothermal energy source?', options: ['Heat from Earth\'s interior used for energy', 'Solar energy', 'Wind energy', 'Tidal energy'], correctIndex: 0, explanation: 'Geothermal energy harnesses heat from Earth\'s interior (radioactive decay and residual formation heat) for electricity and heating.' },

  // ── HARD (50) ──
  { id: 'e_h1', difficulty: 'hard', question: 'What is the cosmic microwave background?', options: ['Radiation remnant from the Big Bang', 'Solar radiation', 'X-rays from stars', 'Radio from pulsars'], correctIndex: 0, explanation: 'The CMB is thermal radiation from ~380,000 years after the Big Bang, providing a snapshot of the early universe at ~2.7 K.' },
  { id: 'e_h2', difficulty: 'hard', question: 'What is the Chandrasekhar limit?', options: ['Maximum mass for a stable white dwarf (~1.4 solar masses)', 'Speed of light', 'Maximum black hole size', 'Age of the universe'], correctIndex: 0, explanation: 'The Chandrasekhar limit (~1.4 M☉) is the maximum mass a white dwarf can support; beyond this, it collapses into a neutron star or black hole.' },
  { id: 'e_h3', difficulty: 'hard', question: 'What is dark energy?', options: ['Unknown force accelerating universal expansion', 'Black hole energy', 'Stellar fusion energy', 'Gravitational wave energy'], correctIndex: 0, explanation: 'Dark energy (~68% of the universe) is a mysterious force driving the accelerating expansion of the universe.' },
  { id: 'e_h4', difficulty: 'hard', question: 'What is a quasar?', options: ['Extremely luminous active galactic nucleus powered by a supermassive black hole', 'A small star', 'A type of moon', 'An asteroid'], correctIndex: 0, explanation: 'Quasars are the most luminous objects in the universe, powered by accretion of matter onto supermassive black holes at galaxy centers.' },
  { id: 'e_h5', difficulty: 'hard', question: 'What is dark matter?', options: ['Invisible matter detectable only through gravitational effects', 'Black holes', 'Interstellar gas', 'Cosmic dust'], correctIndex: 0, explanation: 'Dark matter (~27% of the universe) doesn\'t emit or interact with electromagnetic radiation but exerts gravitational influence on visible matter.' },
  { id: 'e_h6', difficulty: 'hard', question: 'What is gravitational lensing?', options: ['Bending of light by massive objects warping spacetime', 'Light reflecting off planets', 'Sound refraction', 'Magnetic deflection'], correctIndex: 0, explanation: 'Gravitational lensing occurs when massive objects bend the path of light from distant sources, as predicted by Einstein\'s general relativity.' },
  { id: 'e_h7', difficulty: 'hard', question: 'What are gravitational waves?', options: ['Ripples in spacetime caused by accelerating massive objects', 'Sound waves in space', 'Ocean waves from gravity', 'Electromagnetic waves'], correctIndex: 0, explanation: 'Gravitational waves are distortions in spacetime produced by accelerating masses, first detected by LIGO in 2015.' },
  { id: 'e_h8', difficulty: 'hard', question: 'What is the Schwarzschild radius?', options: ['Radius of the event horizon of a non-rotating black hole', 'Radius of the Sun', 'Size of a neutron star', 'Orbital radius of Earth'], correctIndex: 0, explanation: 'The Schwarzschild radius defines the size of the event horizon: rs = 2GM/c². For Earth\'s mass, it would be about 9 mm.' },
  { id: 'e_h9', difficulty: 'hard', question: 'What is Hubble\'s Law?', options: ['Galaxies recede at speeds proportional to their distance', 'Galaxies attract each other', 'Stars orbit galaxies at constant speed', 'Light speed is constant'], correctIndex: 0, explanation: 'Hubble\'s Law (v = H₀d) states that the recession velocity of galaxies is proportional to their distance, demonstrating universal expansion.' },
  { id: 'e_h10', difficulty: 'hard', question: 'What is the Roche limit?', options: ['Distance within which tidal forces disrupt a satellite', 'Maximum orbital distance', 'Minimum star size', 'Maximum planet mass'], correctIndex: 0, explanation: 'The Roche limit is the closest distance a satellite can orbit without being torn apart by tidal forces from the primary body.' },
  { id: 'e_h11', difficulty: 'hard', question: 'What is the Tolman-Oppenheimer-Volkoff limit?', options: ['Maximum mass of a neutron star before collapsing to a black hole', 'Minimum star mass', 'Maximum planet size', 'White dwarf limit'], correctIndex: 0, explanation: 'The TOV limit (~2-3 M☉) is the maximum mass a neutron star can sustain before gravitational collapse into a black hole.' },
  { id: 'e_h12', difficulty: 'hard', question: 'What is the Olbers\' paradox?', options: ['Why the night sky is dark if the universe has infinite stars', 'Why the sky is blue', 'Why stars twinkle', 'Why the Moon shines'], correctIndex: 0, explanation: 'Olbers\' paradox asks why the night sky is dark despite potentially infinite stars. It\'s resolved by the finite age of the universe and its expansion.' },
  { id: 'e_h13', difficulty: 'hard', question: 'What is the Drake equation?', options: ['Estimates the number of communicable civilizations in the Milky Way', 'Calculates star luminosity', 'Determines planet orbits', 'Measures galaxy size'], correctIndex: 0, explanation: 'The Drake equation estimates the number of active, communicative extraterrestrial civilizations by multiplying several probabilistic factors.' },
  { id: 'e_h14', difficulty: 'hard', question: 'What is the Fermi paradox?', options: ['Contradiction between lack of alien evidence and high probability estimates', 'Fermion behavior in stars', 'Nuclear reaction paradox', 'Quantum gravity problem'], correctIndex: 0, explanation: 'The Fermi paradox highlights the contradiction between the high probability of extraterrestrial civilizations and the lack of evidence or contact.' },
  { id: 'e_h15', difficulty: 'hard', question: 'What is the Jeans mass?', options: ['Minimum mass for a gas cloud to collapse under its own gravity', 'Mass of Jupiter', 'Solar mass', 'Earth\'s mass'], correctIndex: 0, explanation: 'The Jeans mass is the critical mass above which a gas cloud\'s gravity overcomes thermal pressure, initiating collapse and star formation.' },
  { id: 'e_h16', difficulty: 'hard', question: 'What is the Eddington luminosity?', options: ['Maximum luminosity a star can achieve in hydrostatic equilibrium', 'Minimum star brightness', 'Average galaxy brightness', 'Solar luminosity'], correctIndex: 0, explanation: 'The Eddington luminosity is the maximum luminosity where radiation pressure balances gravitational infall, limiting stellar brightness.' },
  { id: 'e_h17', difficulty: 'hard', question: 'What is the virial theorem?', options: ['Relates average kinetic energy to average potential energy in a gravitationally bound system', 'Conservation of energy', 'Ideal gas law', 'Newton\'s law'], correctIndex: 0, explanation: 'The virial theorem states that for a gravitationally bound system in equilibrium, the time-averaged kinetic energy is -½ the potential energy.' },
  { id: 'e_h18', difficulty: 'hard', question: 'What is the Tully-Fisher relation?', options: ['Correlation between galaxy luminosity and rotational velocity', 'Star color and temperature', 'Planet size and orbit', 'Moon phase and tide'], correctIndex: 0, explanation: 'The Tully-Fisher relation links spiral galaxy luminosity to rotational velocity, used as a distance indicator in astronomy.' },
  { id: 'e_h19', difficulty: 'hard', question: 'What is cosmic inflation?', options: ['Rapid exponential expansion of the early universe in first ~10⁻³² seconds', 'Current expansion rate', 'Galaxy rotation', 'Star formation'], correctIndex: 0, explanation: 'Cosmic inflation theory proposes that the universe underwent extremely rapid exponential expansion just after the Big Bang.' },
  { id: 'e_h20', difficulty: 'hard', question: 'What is the Sunyaev-Zel\'dovich effect?', options: ['CMB photon energy boost from hot galaxy cluster gas', 'Star formation in clusters', 'Black hole radiation', 'Solar wind interaction'], correctIndex: 0, explanation: 'The SZ effect occurs when CMB photons gain energy from inverse Compton scattering off hot electrons in galaxy cluster gas.' },
  { id: 'e_h21', difficulty: 'hard', question: 'What is the epoch of reionization?', options: ['Period when first stars and galaxies ionized neutral hydrogen', 'Formation of first atoms', 'Big Bang itself', 'Current era'], correctIndex: 0, explanation: 'The epoch of reionization (~150 million - 1 billion years after Big Bang) is when UV radiation from early stars re-ionized the neutral hydrogen.' },
  { id: 'e_h22', difficulty: 'hard', question: 'What is the Sagnac effect?', options: ['Difference in light travel time in a rotating reference frame', 'Gravitational time dilation', 'Doppler shift', 'Parallax'], correctIndex: 0, explanation: 'The Sagnac effect shows that light traveling in opposite directions around a rotating loop arrives at different times, used in ring laser gyroscopes.' },
  { id: 'e_h23', difficulty: 'hard', question: 'What is the Bondi accretion model?', options: ['Spherically symmetric accretion of gas onto a compact object', 'Disk accretion only', 'Stellar wind model', 'Jet formation theory'], correctIndex: 0, explanation: 'Bondi accretion describes the spherically symmetric flow of gas onto a gravitating body, giving the Bondi accretion rate.' },
  { id: 'e_h24', difficulty: 'hard', question: 'What is the Penrose process?', options: ['Extracting energy from a rotating black hole\'s ergosphere', 'Black hole evaporation', 'Star formation', 'Galaxy collision'], correctIndex: 0, explanation: 'The Penrose process allows energy extraction from a rotating (Kerr) black hole by sending particles into the ergosphere.' },
  { id: 'e_h25', difficulty: 'hard', question: 'What is the Friedmann equation?', options: ['Governs the expansion rate of the universe from general relativity', 'Newton\'s gravity law', 'Kepler\'s third law', 'Ideal gas law'], correctIndex: 0, explanation: 'The Friedmann equations, derived from Einstein\'s field equations, describe how the scale factor of the universe evolves over time.' },
  { id: 'e_h26', difficulty: 'hard', question: 'What is baryonic acoustic oscillations?', options: ['Density fluctuations in early universe matter visible in galaxy distribution', 'Sound in stars', 'Planetary resonances', 'Solar oscillations'], correctIndex: 0, explanation: 'BAO are regular density fluctuations from sound waves in the early universe plasma, now visible as a preferred galaxy separation scale (~490 million light-years).' },
  { id: 'e_h27', difficulty: 'hard', question: 'What is the Lane-Emden equation?', options: ['Describes structure of self-gravitating polytropic spheres', 'Orbital mechanics', 'Wave equation', 'Heat equation'], correctIndex: 0, explanation: 'The Lane-Emden equation models the internal structure of stars by relating density to radius in self-gravitating fluid spheres.' },
  { id: 'e_h28', difficulty: 'hard', question: 'What is the Shakura-Sunyaev disk model?', options: ['Standard thin accretion disk model around compact objects', 'Planetary ring model', 'Galaxy disk model', 'Solar system formation model'], correctIndex: 0, explanation: 'The Shakura-Sunyaev model describes geometrically thin, optically thick accretion disks using α-viscosity parameterization.' },
  { id: 'e_h29', difficulty: 'hard', question: 'What is the Hawking radiation?', options: ['Theoretical radiation emitted by black holes due to quantum effects', 'Solar radiation', 'Cosmic rays', 'Neutron star emission'], correctIndex: 0, explanation: 'Hawking radiation is the theoretical thermal radiation predicted to be emitted by black holes due to quantum effects near the event horizon.' },
  { id: 'e_h30', difficulty: 'hard', question: 'What is the cosmological constant?', options: ['Energy density of empty space (vacuum energy)', 'Speed of light', 'Gravitational constant', 'Hubble constant'], correctIndex: 0, explanation: 'The cosmological constant (Λ) represents the energy density of empty space, associated with dark energy and the accelerating expansion.' },
  { id: 'e_h31', difficulty: 'hard', question: 'What is the Tidal Disruption Event?', options: ['Star being torn apart by a black hole\'s gravity', 'Moon causing tides', 'Earthquake', 'Tsunami'], correctIndex: 0, explanation: 'A TDE occurs when a star ventures too close to a supermassive black hole and is ripped apart by tidal forces.' },
  { id: 'e_h32', difficulty: 'hard', question: 'What is the Kelvin-Helmholtz mechanism?', options: ['Gravitational contraction heating a star', 'Nuclear fusion', 'Chemical combustion', 'Magnetic heating'], correctIndex: 0, explanation: 'The Kelvin-Helmholtz mechanism describes heating through gravitational contraction, significant in early stellar evolution before nuclear fusion begins.' },
  { id: 'e_h33', difficulty: 'hard', question: 'What is the Chandrasekhar mass for neutron stars?', options: ['Maximum mass supported by neutron degeneracy pressure (~2-3 M☉)', 'Any mass', 'Only 1 solar mass', 'Infinite mass'], correctIndex: 0, explanation: 'The Tolman-Oppenheimer-Volkoff limit (analogous to Chandrasekhar for white dwarfs) sets the maximum neutron star mass at ~2-3 M☉.' },
  { id: 'e_h34', difficulty: 'hard', question: 'What is the Malmquist bias?', options: ['Observational bias toward detecting intrinsically brighter objects at greater distances', 'Instrument error', 'Atmospheric distortion', 'Time zone effects'], correctIndex: 0, explanation: 'Malmquist bias occurs in flux-limited surveys where only the brightest objects are detected at greater distances, skewing samples.' },
  { id: 'e_h35', difficulty: 'hard', question: 'What is the Silk damping scale?', options: ['Scale below which density perturbations in early universe are erased by photon diffusion', 'Sound wavelength', 'Galaxy size', 'Star radius'], correctIndex: 0, explanation: 'Silk damping erases small-scale density fluctuations in the early universe through photon diffusion, setting a minimum structure scale.' },
  { id: 'e_h36', difficulty: 'hard', question: 'What is the Sachs-Wolfe effect?', options: ['CMB temperature anisotropies from gravitational potentials at last scattering', 'Doppler shift of stars', 'Solar wind effect', 'Tidal heating'], correctIndex: 0, explanation: 'The Sachs-Wolfe effect describes temperature fluctuations in the CMB caused by photons climbing out of gravitational potential wells.' },
  { id: 'e_h37', difficulty: 'hard', question: 'What is frame dragging?', options: ['Rotating masses drag spacetime around them', 'Orbital precession from Newtonian gravity', 'Light dragging by gravity', 'Atmospheric drag on satellites'], correctIndex: 0, explanation: 'Frame dragging (Lense-Thirring effect) is a general relativistic effect where rotating masses twist the surrounding spacetime.' },
  { id: 'e_h38', difficulty: 'hard', question: 'What is the Shapiro delay?', options: ['Time delay of light passing near a massive object', 'Light speeding up near stars', 'Gravitational blueshift', 'Parallax measurement'], correctIndex: 0, explanation: 'The Shapiro delay is the relativistic time delay experienced by signals passing near a massive body, confirmed as a test of general relativity.' },
  { id: 'e_h39', difficulty: 'hard', question: 'What is the Rayleigh-Jeans law?', options: ['Classical approximation for blackbody radiation at long wavelengths', 'Quantum radiation law', 'Star classification', 'Planetary motion'], correctIndex: 0, explanation: 'The Rayleigh-Jeans law approximates blackbody radiation at long wavelengths but fails at short wavelengths (ultraviolet catastrophe).' },
  { id: 'e_h40', difficulty: 'hard', question: 'What is the Birkhoff theorem?', options: ['Any spherically symmetric vacuum solution to Einstein\'s equations is the Schwarzschild metric', 'All solutions are flat', 'Only rotating solutions exist', 'No solutions exist'], correctIndex: 0, explanation: 'Birkhoff\'s theorem states that any spherically symmetric vacuum solution to Einstein\'s field equations must be static and is the Schwarzschild solution.' },
  { id: 'e_h41', difficulty: 'hard', question: 'What is the Kerr metric?', options: ['Spacetime geometry around a rotating black hole', 'Non-rotating black hole', 'Flat spacetime', 'Expanding universe'], correctIndex: 0, explanation: 'The Kerr metric describes the spacetime geometry around a rotating (uncharged) black hole, generalizing the Schwarzschild solution.' },
  { id: 'e_h42', difficulty: 'hard', question: 'What is the Bondi-Hoyle-Lyttleton accretion?', options: ['Accretion of gas by a body moving through a medium', 'Static accretion only', 'Disk accretion', 'Magnetic accretion'], correctIndex: 0, explanation: 'BHL accretion describes how a gravitating body moving through a gas medium captures material, important for binary star systems.' },
  { id: 'e_h43', difficulty: 'hard', question: 'What is the Baade-Wesselink method?', options: ['Technique to determine distances to pulsating stars', 'Spectroscopic classification', 'Galaxy redshift measurement', 'Parallax measurement'], correctIndex: 0, explanation: 'The Baade-Wesselink method combines radial velocity measurements with angular size changes to determine distances to pulsating variable stars.' },
  { id: 'e_h44', difficulty: 'hard', question: 'What is the Nordtvedt effect?', options: ['Possible violation of the strong equivalence principle by gravitational self-energy', 'Normal gravity', 'Electromagnetic effect', 'Thermodynamic effect'], correctIndex: 0, explanation: 'The Nordtvedt effect predicts that bodies with significant gravitational self-energy might fall differently, testing the strong equivalence principle.' },
  { id: 'e_h45', difficulty: 'hard', question: 'What is the Sunyaev-Zel\'dovich decrement?', options: ['Reduction in CMB intensity toward galaxy clusters due to inverse Compton scattering', 'Increased CMB brightness', 'No change in CMB', 'CMB polarization'], correctIndex: 0, explanation: 'The thermal SZ effect causes a decrement in CMB intensity at frequencies below ~217 GHz due to inverse Compton scattering in hot cluster gas.' },
  { id: 'e_h46', difficulty: 'hard', question: 'What is the epoch of matter-radiation equality?', options: ['When matter and radiation energy densities were equal (~47,000 years after Big Bang)', 'Big Bang itself', 'Present day', 'Heat death'], correctIndex: 0, explanation: 'Matter-radiation equality occurred ~47,000 years after the Big Bang, marking the transition from radiation-dominated to matter-dominated expansion.' },
  { id: 'e_h47', difficulty: 'hard', question: 'What is the peculiar velocity of a galaxy?', options: ['Deviation from pure Hubble flow due to local gravitational influences', 'Orbital speed', 'Rotational speed', 'Speed of light'], correctIndex: 0, explanation: 'A galaxy\'s peculiar velocity is its motion relative to the Hubble flow, caused by gravitational interactions with nearby structures.' },
  { id: 'e_h48', difficulty: 'hard', question: 'What is the Gunn-Peterson trough?', options: ['Near-complete absorption of light below Lyman-alpha by neutral hydrogen at high redshift', 'Emission line', 'Absorption by dust', 'Scattering by electrons'], correctIndex: 0, explanation: 'The Gunn-Peterson trough is the absorption of high-redshift quasar light by neutral hydrogen before the epoch of reionization.' },
  { id: 'e_h49', difficulty: 'hard', question: 'What is the Bekenstein-Hawking entropy?', options: ['Black hole entropy proportional to event horizon area', 'Zero entropy for black holes', 'Infinite entropy', 'Entropy of the universe'], correctIndex: 0, explanation: 'Bekenstein-Hawking entropy: S = kA/4ℓ_P², showing black hole entropy is proportional to the event horizon area, not volume.' },
  { id: 'e_h50', difficulty: 'hard', question: 'What is the information paradox?', options: ['Conflict between black hole evaporation and quantum unitarity', 'Loss of classical information', 'Data storage problem', 'Communication delay'], correctIndex: 0, explanation: 'The black hole information paradox asks whether information entering a black hole is truly lost when it evaporates, violating quantum mechanics\' unitarity.' },
];

