const generalPool: Question[] = [
  // ── EASY (50) ──
  { id: 'g_e1', difficulty: 'easy', question: 'Who developed the theory of relativity?', options: ['Newton', 'Einstein', 'Bohr', 'Galileo'], correctIndex: 1, explanation: 'Albert Einstein published the special theory of relativity in 1905 and the general theory in 1915.' },
  { id: 'g_e2', difficulty: 'easy', question: 'What is the shape of DNA?', options: ['Single helix', 'Double helix', 'Triple helix', 'Flat ribbon'], correctIndex: 1, explanation: 'DNA has a double helix structure, discovered by Watson and Crick in 1953.' },
  { id: 'g_e3', difficulty: 'easy', question: 'At what temperature does water boil (at sea level)?', options: ['90°C', '95°C', '100°C', '110°C'], correctIndex: 2, explanation: 'Water boils at 100°C (212°F) at standard atmospheric pressure (sea level).' },
  { id: 'g_e4', difficulty: 'easy', question: 'Who discovered penicillin?', options: ['Pasteur', 'Fleming', 'Curie', 'Koch'], correctIndex: 1, explanation: 'Alexander Fleming discovered penicillin in 1928 when he noticed mold killing bacteria in a petri dish.' },
  { id: 'g_e5', difficulty: 'easy', question: 'How many bones are in an adult human body?', options: ['196', '206', '216', '186'], correctIndex: 1, explanation: 'An adult human skeleton has 206 bones. Babies are born with about 270, which fuse over time.' },
  { id: 'g_e6', difficulty: 'easy', question: 'What is the most abundant gas in Earth\'s atmosphere?', options: ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Argon'], correctIndex: 2, explanation: 'Nitrogen (N₂) makes up about 78% of Earth\'s atmosphere by volume.' },
  { id: 'g_e7', difficulty: 'easy', question: 'Who proposed the heliocentric model of the solar system?', options: ['Ptolemy', 'Copernicus', 'Kepler', 'Galileo'], correctIndex: 1, explanation: 'Nicolaus Copernicus proposed in 1543 that the Sun, not Earth, is at the center of the solar system.' },
  { id: 'g_e8', difficulty: 'easy', question: 'What is the chemical formula for table salt?', options: ['NaOH', 'NaCl', 'KCl', 'CaCl₂'], correctIndex: 1, explanation: 'Table salt is sodium chloride (NaCl), an ionic compound.' },
  { id: 'g_e9', difficulty: 'easy', question: 'What is photosynthesis?', options: ['Converting light energy to chemical energy', 'Breathing in animals', 'Digesting food', 'Reproducing cells'], correctIndex: 0, explanation: 'Photosynthesis converts light energy, water, and CO₂ into glucose and oxygen in plants.' },
  { id: 'g_e10', difficulty: 'easy', question: 'What is the scientific method?', options: ['Systematic observation and testing', 'Random guessing', 'Mathematical proof only', 'Statistical analysis only'], correctIndex: 0, explanation: 'The scientific method involves observation, hypothesis, experimentation, analysis, and conclusion.' },
  { id: 'g_e11', difficulty: 'easy', question: 'Who discovered gravity?', options: ['Einstein', 'Newton', 'Galileo', 'Kepler'], correctIndex: 1, explanation: 'Isaac Newton formulated the law of universal gravitation in 1687, inspired by observing falling objects.' },
  { id: 'g_e12', difficulty: 'easy', question: 'What is a hypothesis?', options: ['A testable prediction', 'A proven fact', 'A random guess', 'A final conclusion'], correctIndex: 0, explanation: 'A hypothesis is a testable explanation for an observation, which can be supported or refuted through experimentation.' },
  { id: 'g_e13', difficulty: 'easy', question: 'What is the speed of sound in air?', options: ['343 m/s', '300 m/s', '400 m/s', '500 m/s'], correctIndex: 0, explanation: 'Sound travels at approximately 343 m/s in air at 20°C (about 1,235 km/h).' },
  { id: 'g_e14', difficulty: 'easy', question: 'What organ filters blood in the human body?', options: ['Liver', 'Heart', 'Kidneys', 'Lungs'], correctIndex: 2, explanation: 'The kidneys filter blood, removing waste products and excess water to produce urine.' },
  { id: 'g_e15', difficulty: 'easy', question: 'What is the study of weather called?', options: ['Geology', 'Astronomy', 'Meteorology', 'Oceanography'], correctIndex: 2, explanation: 'Meteorology is the scientific study of the atmosphere and weather phenomena.' },
  { id: 'g_e16', difficulty: 'easy', question: 'What is the boiling point of water in Fahrenheit?', options: ['100°F', '180°F', '212°F', '232°F'], correctIndex: 2, explanation: 'Water boils at 212°F (100°C) at standard atmospheric pressure.' },
  { id: 'g_e17', difficulty: 'easy', question: 'What is an ecosystem?', options: ['Community of living things and their environment', 'A single animal', 'Just the weather', 'Only plants'], correctIndex: 0, explanation: 'An ecosystem includes all living organisms and their physical environment interacting as a system.' },
  { id: 'g_e18', difficulty: 'easy', question: 'What is the smallest unit of matter?', options: ['Molecule', 'Atom', 'Cell', 'Electron'], correctIndex: 1, explanation: 'An atom is the smallest unit of a chemical element that retains the element\'s chemical properties.' },
  { id: 'g_e19', difficulty: 'easy', question: 'What is gravity?', options: ['Force that attracts objects with mass toward each other', 'Magnetic force', 'Electrical force', 'Wind force'], correctIndex: 0, explanation: 'Gravity is the fundamental force of attraction between all objects with mass.' },
  { id: 'g_e20', difficulty: 'easy', question: 'What does a barometer measure?', options: ['Temperature', 'Wind speed', 'Atmospheric pressure', 'Humidity'], correctIndex: 2, explanation: 'A barometer measures atmospheric (air) pressure, useful for weather prediction.' },
  { id: 'g_e21', difficulty: 'easy', question: 'What is the largest mammal on Earth?', options: ['Elephant', 'Blue whale', 'Giraffe', 'Hippopotamus'], correctIndex: 1, explanation: 'The blue whale is the largest animal ever known, reaching up to 30 meters and 200 tonnes.' },
  { id: 'g_e22', difficulty: 'easy', question: 'Who is known as the father of modern chemistry?', options: ['Dalton', 'Lavoisier', 'Mendeleev', 'Boyle'], correctIndex: 1, explanation: 'Antoine Lavoisier is called the father of modern chemistry for his work on combustion, chemical nomenclature, and conservation of mass.' },
  { id: 'g_e23', difficulty: 'easy', question: 'What is the hardest natural substance?', options: ['Steel', 'Quartz', 'Diamond', 'Titanium'], correctIndex: 2, explanation: 'Diamond is the hardest known natural material, scoring 10 on the Mohs hardness scale.' },
  { id: 'g_e24', difficulty: 'easy', question: 'What does a compass point toward?', options: ['South Pole', 'Magnetic North Pole', 'The Sun', 'The Moon'], correctIndex: 1, explanation: 'A compass needle aligns with Earth\'s magnetic field, pointing toward the magnetic North Pole.' },
  { id: 'g_e25', difficulty: 'easy', question: 'What is evaporation?', options: ['Solid to gas', 'Liquid to gas at the surface', 'Gas to liquid', 'Liquid to solid'], correctIndex: 1, explanation: 'Evaporation is when liquid molecules at the surface gain enough energy to become gas.' },
  { id: 'g_e26', difficulty: 'easy', question: 'What is the periodic table?', options: ['Chart organizing elements by atomic number', 'A calendar', 'A math table', 'A physics formula sheet'], correctIndex: 0, explanation: 'The periodic table organizes chemical elements by atomic number, revealing periodic trends in properties.' },
  { id: 'g_e27', difficulty: 'easy', question: 'What is a vaccine?', options: ['A substance that stimulates immunity', 'An antibiotic', 'A painkiller', 'A vitamin'], correctIndex: 0, explanation: 'Vaccines contain weakened or killed pathogens that train the immune system to fight specific diseases.' },
  { id: 'g_e28', difficulty: 'easy', question: 'What is the function of the ozone layer?', options: ['Absorbs harmful UV radiation', 'Produces oxygen', 'Creates rain', 'Generates wind'], correctIndex: 0, explanation: 'The ozone layer in the stratosphere absorbs most of the Sun\'s harmful ultraviolet (UV-B and UV-C) radiation.' },
  { id: 'g_e29', difficulty: 'easy', question: 'What planet is closest to the Sun?', options: ['Venus', 'Earth', 'Mercury', 'Mars'], correctIndex: 2, explanation: 'Mercury orbits closest to the Sun at an average distance of about 58 million km.' },
  { id: 'g_e30', difficulty: 'easy', question: 'What is the freezing point of water?', options: ['-10°C', '0°C', '10°C', '32°C'], correctIndex: 1, explanation: 'Water freezes at 0°C (32°F) at standard atmospheric pressure.' },
  { id: 'g_e31', difficulty: 'easy', question: 'Who invented the telephone?', options: ['Edison', 'Bell', 'Tesla', 'Marconi'], correctIndex: 1, explanation: 'Alexander Graham Bell is credited with inventing the first practical telephone in 1876.' },
  { id: 'g_e32', difficulty: 'easy', question: 'What is the main function of red blood cells?', options: ['Fight infection', 'Carry oxygen', 'Clot blood', 'Digest food'], correctIndex: 1, explanation: 'Red blood cells contain hemoglobin, which carries oxygen from the lungs to body tissues.' },
  { id: 'g_e33', difficulty: 'easy', question: 'What is density?', options: ['Mass per unit volume', 'Weight per area', 'Speed per time', 'Force per mass'], correctIndex: 0, explanation: 'Density = mass ÷ volume. It measures how much matter is packed into a given space.' },
  { id: 'g_e34', difficulty: 'easy', question: 'What are the three states of matter?', options: ['Solid, liquid, gas', 'Hot, cold, warm', 'Heavy, light, medium', 'Hard, soft, flexible'], correctIndex: 0, explanation: 'The three common states of matter are solid (fixed shape and volume), liquid (fixed volume), and gas (neither).' },
  { id: 'g_e35', difficulty: 'easy', question: 'What does a telescope do?', options: ['Makes distant objects appear closer', 'Measures temperature', 'Records sound', 'Analyzes chemicals'], correctIndex: 0, explanation: 'Telescopes collect and focus light (or other radiation) to magnify distant objects.' },
  { id: 'g_e36', difficulty: 'easy', question: 'What is the symbol for water?', options: ['Wa', 'W', 'H₂O', 'HO₂'], correctIndex: 2, explanation: 'Water\'s chemical formula H₂O represents two hydrogen atoms bonded to one oxygen atom.' },
  { id: 'g_e37', difficulty: 'easy', question: 'What is the largest ocean on Earth?', options: ['Atlantic', 'Indian', 'Pacific', 'Arctic'], correctIndex: 2, explanation: 'The Pacific Ocean is the largest, covering about 165.25 million km² — more than all land area combined.' },
  { id: 'g_e38', difficulty: 'easy', question: 'What is renewable energy?', options: ['Energy from sources that replenish naturally', 'Fossil fuels', 'Nuclear energy only', 'Energy that runs out'], correctIndex: 0, explanation: 'Renewable energy comes from naturally replenishing sources like solar, wind, hydro, and geothermal.' },
  { id: 'g_e39', difficulty: 'easy', question: 'What is the center of our solar system?', options: ['Earth', 'Moon', 'Sun', 'Jupiter'], correctIndex: 2, explanation: 'The Sun is at the center of our solar system, with all planets orbiting around it.' },
  { id: 'g_e40', difficulty: 'easy', question: 'What is an insulator?', options: ['Material that doesn\'t conduct electricity well', 'Good conductor', 'A semiconductor', 'A superconductor'], correctIndex: 0, explanation: 'Insulators (rubber, glass, plastic) have high resistance and don\'t allow electric current to flow easily.' },
  { id: 'g_e41', difficulty: 'easy', question: 'What is carbon dioxide\'s role in the atmosphere?', options: ['Greenhouse gas that traps heat', 'Cools the atmosphere', 'Creates ozone', 'Produces oxygen'], correctIndex: 0, explanation: 'CO₂ is a greenhouse gas that absorbs and re-emits infrared radiation, contributing to Earth\'s warming.' },
  { id: 'g_e42', difficulty: 'easy', question: 'Who invented the light bulb?', options: ['Bell', 'Edison', 'Tesla', 'Franklin'], correctIndex: 1, explanation: 'Thomas Edison developed the first commercially practical incandescent light bulb in 1879.' },
  { id: 'g_e43', difficulty: 'easy', question: 'What is the study of life called?', options: ['Chemistry', 'Physics', 'Biology', 'Geology'], correctIndex: 2, explanation: 'Biology is the natural science that studies life and living organisms.' },
  { id: 'g_e44', difficulty: 'easy', question: 'What is a food chain?', options: ['Sequence of organisms where each is food for the next', 'A recipe', 'A type of restaurant', 'A nutrition label'], correctIndex: 0, explanation: 'A food chain shows the linear pathway of energy flow from producers to consumers in an ecosystem.' },
  { id: 'g_e45', difficulty: 'easy', question: 'What is the chemical formula for oxygen gas?', options: ['O', 'O₂', 'O₃', 'O₄'], correctIndex: 1, explanation: 'Oxygen gas exists as a diatomic molecule (O₂) under standard conditions.' },
  { id: 'g_e46', difficulty: 'easy', question: 'What is pollution?', options: ['Introduction of harmful substances into the environment', 'Clean air', 'Recycling', 'Conservation'], correctIndex: 0, explanation: 'Pollution is the introduction of contaminants into the environment that cause adverse changes.' },
  { id: 'g_e47', difficulty: 'easy', question: 'What is the function of the skeletal system?', options: ['Support, protection, and movement', 'Digestion', 'Breathing', 'Blood circulation'], correctIndex: 0, explanation: 'The skeletal system provides structural support, protects organs, enables movement, and produces blood cells.' },
  { id: 'g_e48', difficulty: 'easy', question: 'Who was Marie Curie famous for studying?', options: ['Electricity', 'Gravity', 'Radioactivity', 'Magnetism'], correctIndex: 2, explanation: 'Marie Curie pioneered research on radioactivity, discovered polonium and radium, and won two Nobel Prizes.' },
  { id: 'g_e49', difficulty: 'easy', question: 'What is the boiling point of water in Kelvin?', options: ['273 K', '373 K', '473 K', '100 K'], correctIndex: 1, explanation: '100°C = 373.15 K. Kelvin = Celsius + 273.15.' },
  { id: 'g_e50', difficulty: 'easy', question: 'What is a microscope used for?', options: ['Viewing very small objects', 'Viewing distant objects', 'Measuring temperature', 'Recording sound'], correctIndex: 0, explanation: 'Microscopes magnify tiny objects, allowing us to see cells, bacteria, and other microscopic structures.' },

  // ── MEDIUM (50) ──
  { id: 'g_m1', difficulty: 'medium', question: 'What particle mediates the electromagnetic force?', options: ['Gluon', 'Photon', 'W boson', 'Graviton'], correctIndex: 1, explanation: 'The photon is the gauge boson that mediates the electromagnetic force between charged particles.' },
  { id: 'g_m2', difficulty: 'medium', question: 'What is the half-life of Carbon-14?', options: ['2,730 years', '5,730 years', '11,460 years', '1,000 years'], correctIndex: 1, explanation: 'Carbon-14 has a half-life of 5,730 years, making it useful for dating organic materials up to ~50,000 years old.' },
  { id: 'g_m3', difficulty: 'medium', question: 'What is absolute zero in Celsius?', options: ['-273.15°C', '-100°C', '-459.67°C', '0°C'], correctIndex: 0, explanation: 'Absolute zero (0 K) equals -273.15°C — the lowest possible temperature where all molecular motion ceases.' },
  { id: 'g_m4', difficulty: 'medium', question: 'Which planet currently has the most known moons?', options: ['Jupiter', 'Saturn', 'Neptune', 'Uranus'], correctIndex: 1, explanation: 'Saturn has the most known moons (over 140 as of 2024), surpassing Jupiter.' },
  { id: 'g_m5', difficulty: 'medium', question: 'What is a genome?', options: ['Complete set of an organism\'s DNA', 'A single gene', 'A protein', 'A chromosome'], correctIndex: 0, explanation: 'A genome is the complete set of genetic instructions (DNA) of an organism, including all its genes and non-coding sequences.' },
  { id: 'g_m6', difficulty: 'medium', question: 'What is entropy?', options: ['Measure of disorder in a system', 'A type of energy', 'A force', 'A mass unit'], correctIndex: 0, explanation: 'Entropy is a thermodynamic quantity measuring the degree of randomness or disorder in a system.' },
  { id: 'g_m7', difficulty: 'medium', question: 'What is a control group in an experiment?', options: ['Group that doesn\'t receive the treatment', 'Group with the treatment', 'The largest group', 'A random selection'], correctIndex: 0, explanation: 'The control group receives no treatment, serving as a baseline for comparison with experimental groups.' },
  { id: 'g_m8', difficulty: 'medium', question: 'What is peer review?', options: ['Expert evaluation of scientific work before publication', 'Student grading', 'Public voting', 'AI review'], correctIndex: 0, explanation: 'Peer review involves independent experts evaluating research for validity and significance before publication.' },
  { id: 'g_m9', difficulty: 'medium', question: 'Who invented the telescope?', options: ['Galileo', 'Hans Lippershey', 'Newton', 'Hubble'], correctIndex: 1, explanation: 'Hans Lippershey is generally credited with inventing the telescope in 1608. Galileo later improved it for astronomical use.' },
  { id: 'g_m10', difficulty: 'medium', question: 'What is the law of conservation of energy?', options: ['Energy cannot be created or destroyed, only transformed', 'Energy increases over time', 'Energy can be created', 'Energy disappears'], correctIndex: 0, explanation: 'The first law of thermodynamics states that energy is always conserved — it changes form but the total amount remains constant.' },
  { id: 'g_m11', difficulty: 'medium', question: 'What is a catalyst?', options: ['Substance that speeds up a reaction without being consumed', 'A reactant', 'A product', 'An inhibitor'], correctIndex: 0, explanation: 'Catalysts lower the activation energy of reactions, increasing the rate without being permanently consumed.' },
  { id: 'g_m12', difficulty: 'medium', question: 'What is the electromagnetic spectrum?', options: ['Range of all electromagnetic radiation frequencies', 'Only visible light', 'Only radio waves', 'Sound waves'], correctIndex: 0, explanation: 'The EM spectrum encompasses all types of electromagnetic radiation: radio, microwave, infrared, visible, UV, X-ray, and gamma.' },
  { id: 'g_m13', difficulty: 'medium', question: 'What is natural selection?', options: ['Process where organisms with favorable traits survive and reproduce more', 'Artificial breeding', 'Random evolution', 'Genetic engineering'], correctIndex: 0, explanation: 'Natural selection is the mechanism of evolution where organisms better adapted to their environment tend to survive and reproduce.' },
  { id: 'g_m14', difficulty: 'medium', question: 'What is plate tectonics?', options: ['Theory that Earth\'s crust is divided into moving plates', 'Study of plates and dishes', 'Ocean current theory', 'Atmospheric science'], correctIndex: 0, explanation: 'Plate tectonics explains how Earth\'s lithosphere is divided into large plates that move, causing earthquakes and volcanism.' },
  { id: 'g_m15', difficulty: 'medium', question: 'What is the Doppler effect?', options: ['Change in wave frequency due to relative motion', 'Wave amplitude change', 'Wave reflection', 'Wave absorption'], correctIndex: 0, explanation: 'The Doppler effect causes apparent frequency changes when a source and observer are moving relative to each other.' },
  { id: 'g_m16', difficulty: 'medium', question: 'What is biodegradable material?', options: ['Material that can be broken down by living organisms', 'Synthetic plastic', 'Metal alloy', 'Glass'], correctIndex: 0, explanation: 'Biodegradable materials (paper, food waste, natural fibers) can be decomposed by bacteria and other organisms.' },
  { id: 'g_m17', difficulty: 'medium', question: 'What is the difference between accuracy and precision?', options: ['Accuracy is closeness to true value; precision is consistency of measurements', 'They are the same', 'Precision is closer to true value', 'Accuracy means consistent'], correctIndex: 0, explanation: 'Accuracy measures how close a result is to the true value; precision measures how reproducible results are.' },
  { id: 'g_m18', difficulty: 'medium', question: 'What is a black hole?', options: ['Region where gravity prevents anything from escaping', 'A dark star', 'Empty space', 'A type of nebula'], correctIndex: 0, explanation: 'A black hole is a region of spacetime where gravity is so strong that nothing, not even light, can escape from its event horizon.' },
  { id: 'g_m19', difficulty: 'medium', question: 'What is genetic engineering?', options: ['Direct manipulation of an organism\'s genes', 'Natural breeding', 'Studying genes without changing them', 'Creating new elements'], correctIndex: 0, explanation: 'Genetic engineering involves directly modifying an organism\'s DNA to introduce new traits or alter existing ones.' },
  { id: 'g_m20', difficulty: 'medium', question: 'What are stem cells?', options: ['Undifferentiated cells that can develop into specialized types', 'Only blood cells', 'Dead cells', 'Plant cells only'], correctIndex: 0, explanation: 'Stem cells can self-renew and differentiate into various specialized cell types, with potential for regenerative medicine.' },
  { id: 'g_m21', difficulty: 'medium', question: 'What is the greenhouse effect?', options: ['Atmospheric gases trapping heat to warm Earth', 'Cooling effect of clouds', 'Ozone depletion', 'Solar radiation reflection'], correctIndex: 0, explanation: 'Greenhouse gases (CO₂, CH₄, H₂O vapor) absorb infrared radiation from Earth\'s surface, warming the atmosphere.' },
  { id: 'g_m22', difficulty: 'medium', question: 'What is radioactivity?', options: ['Emission of radiation from unstable atomic nuclei', 'Radio wave production', 'Chemical reaction', 'Electrical discharge'], correctIndex: 0, explanation: 'Radioactivity is the spontaneous emission of particles or energy from unstable atomic nuclei as they decay to more stable forms.' },
  { id: 'g_m23', difficulty: 'medium', question: 'What is the pH scale?', options: ['Measures acidity or basicity from 0-14', 'Measures temperature', 'Measures pressure', 'Measures speed'], correctIndex: 0, explanation: 'The pH scale ranges from 0 (most acidic) to 14 (most basic), with 7 being neutral. pH = -log[H⁺].' },
  { id: 'g_m24', difficulty: 'medium', question: 'What is DNA fingerprinting used for?', options: ['Identifying individuals from DNA samples', 'Taking fingerprints', 'X-ray imaging', 'Blood typing only'], correctIndex: 0, explanation: 'DNA fingerprinting analyzes unique patterns in DNA to identify individuals, used in forensics and paternity testing.' },
  { id: 'g_m25', difficulty: 'medium', question: 'What is nuclear fission?', options: ['Splitting a heavy nucleus into lighter nuclei', 'Combining light nuclei', 'Chemical reaction', 'Radioactive decay'], correctIndex: 0, explanation: 'Nuclear fission splits heavy atomic nuclei (like uranium) into lighter elements, releasing enormous energy.' },
  { id: 'g_m26', difficulty: 'medium', question: 'What is an isotope?', options: ['Atoms with same protons but different neutrons', 'Different elements', 'Identical atoms', 'Ions'], correctIndex: 0, explanation: 'Isotopes are variants of an element with the same number of protons but different numbers of neutrons.' },
  { id: 'g_m27', difficulty: 'medium', question: 'What is the theory of evolution?', options: ['Species change over time through natural selection', 'Species are unchanging', 'Species appear suddenly', 'Only humans evolve'], correctIndex: 0, explanation: 'Evolution theory explains how species change over generations through natural selection, mutation, and genetic drift.' },
  { id: 'g_m28', difficulty: 'medium', question: 'What is nanotechnology?', options: ['Technology at the scale of atoms and molecules (1-100 nm)', 'Very large machines', 'Space technology', 'Underwater technology'], correctIndex: 0, explanation: 'Nanotechnology manipulates matter at the nanoscale (1-100 nm), creating materials with novel properties.' },
  { id: 'g_m29', difficulty: 'medium', question: 'What is the difference between a theory and a law?', options: ['A theory explains why; a law describes what happens', 'A law is an unproven theory', 'They are the same', 'Laws are always wrong'], correctIndex: 0, explanation: 'Scientific laws describe observed patterns (what); theories provide explanations for why those patterns occur.' },
  { id: 'g_m30', difficulty: 'medium', question: 'What is biomimicry?', options: ['Design inspired by biological systems', 'Cloning organisms', 'Artificial intelligence', 'Genetic engineering'], correctIndex: 0, explanation: 'Biomimicry applies solutions found in nature to engineering and design (e.g., Velcro inspired by burrs).' },
  { id: 'g_m31', difficulty: 'medium', question: 'What is the double-slit experiment?', options: ['Demonstrates wave-particle duality of light and matter', 'Tests for color', 'Measures speed', 'Tests density'], correctIndex: 0, explanation: 'The double-slit experiment shows that light and matter exhibit both wave and particle properties, creating an interference pattern.' },
  { id: 'g_m32', difficulty: 'medium', question: 'What is the difference between nuclear fission and fusion?', options: ['Fission splits atoms; fusion combines atoms', 'They are the same', 'Fission combines atoms', 'Fusion splits atoms'], correctIndex: 0, explanation: 'Fission splits heavy nuclei; fusion combines light nuclei. Both release energy, but fusion produces more energy per unit mass.' },
  { id: 'g_m33', difficulty: 'medium', question: 'What is an allotrope?', options: ['Different structural form of the same element', 'A type of compound', 'An isotope', 'A mixture'], correctIndex: 0, explanation: 'Allotropes are different structural forms of the same element (e.g., diamond and graphite are allotropes of carbon).' },
  { id: 'g_m34', difficulty: 'medium', question: 'What is the difference between a conductor and an insulator?', options: ['Conductors allow current flow; insulators resist it', 'They are the same', 'Insulators conduct better', 'Only metals are conductors'], correctIndex: 0, explanation: 'Conductors (metals) have free-moving electrons allowing current flow; insulators (rubber, glass) resist electron movement.' },
  { id: 'g_m35', difficulty: 'medium', question: 'What is artificial intelligence?', options: ['Machines that can perform tasks requiring human intelligence', 'Robot bodies', 'Internet', 'Supercomputers only'], correctIndex: 0, explanation: 'AI refers to computer systems capable of performing tasks that typically require human intelligence: learning, reasoning, and problem-solving.' },
  { id: 'g_m36', difficulty: 'medium', question: 'What is the Richter scale?', options: ['Logarithmic scale measuring earthquake magnitude', 'Linear temperature scale', 'Wind speed scale', 'Sound intensity scale'], correctIndex: 0, explanation: 'The Richter scale is a logarithmic scale where each whole number increase represents a 10× increase in amplitude and ~31.6× more energy.' },
  { id: 'g_m37', difficulty: 'medium', question: 'What is bioluminescence?', options: ['Light produced by living organisms through chemical reactions', 'Reflected sunlight', 'Thermal radiation', 'Phosphorescence only'], correctIndex: 0, explanation: 'Bioluminescence is light produced by chemical reactions within organisms, seen in fireflies, deep-sea fish, and some fungi.' },
  { id: 'g_m38', difficulty: 'medium', question: 'What is a superconductor?', options: ['Material with zero electrical resistance below critical temperature', 'Perfect insulator', 'Normal conductor', 'Semiconductor'], correctIndex: 0, explanation: 'Superconductors conduct electricity with zero resistance when cooled below a critical temperature.' },
  { id: 'g_m39', difficulty: 'medium', question: 'What is the placebo effect?', options: ['Beneficial effect from a treatment with no active ingredient, due to belief', 'Actual drug effect', 'Side effect', 'Allergic reaction'], correctIndex: 0, explanation: 'The placebo effect occurs when patients improve simply because they believe they are receiving treatment.' },
  { id: 'g_m40', difficulty: 'medium', question: 'What is the Coriolis effect?', options: ['Deflection of moving objects due to Earth\'s rotation', 'Gravity changes', 'Magnetic deflection', 'Wind resistance'], correctIndex: 0, explanation: 'The Coriolis effect deflects freely moving objects to the right in the Northern Hemisphere and left in the Southern.' },
  { id: 'g_m41', difficulty: 'medium', question: 'What is climate change?', options: ['Long-term shift in global temperatures and weather patterns', 'Daily weather variation', 'Seasonal changes', 'Wind speed changes'], correctIndex: 0, explanation: 'Climate change refers to significant, long-term changes in global or regional climate patterns, currently driven primarily by human activities.' },
  { id: 'g_m42', difficulty: 'medium', question: 'What is gene therapy?', options: ['Treatment that modifies genes to treat or prevent disease', 'Physical therapy', 'Drug therapy', 'Radiation therapy'], correctIndex: 0, explanation: 'Gene therapy introduces, alters, or replaces genetic material within cells to treat or prevent disease at the molecular level.' },
  { id: 'g_m43', difficulty: 'medium', question: 'What is the Fibonacci sequence?', options: ['Number series where each number is the sum of the two preceding ones', 'Random numbers', 'Prime numbers', 'Even numbers only'], correctIndex: 0, explanation: 'The Fibonacci sequence (0, 1, 1, 2, 3, 5, 8, 13...) appears frequently in nature, from flower petals to galaxy spirals.' },
  { id: 'g_m44', difficulty: 'medium', question: 'What is spectroscopy?', options: ['Analysis of matter through its interaction with electromagnetic radiation', 'Microscopy', 'Photography', 'Acoustics'], correctIndex: 0, explanation: 'Spectroscopy analyzes the absorption, emission, or scattering of electromagnetic radiation by matter to determine composition and properties.' },
  { id: 'g_m45', difficulty: 'medium', question: 'What is a semiconductor?', options: ['Material with conductivity between conductor and insulator', 'Perfect conductor', 'Perfect insulator', 'Superconductor'], correctIndex: 0, explanation: 'Semiconductors (silicon, germanium) have intermediate conductivity that can be controlled, forming the basis of modern electronics.' },
  { id: 'g_m46', difficulty: 'medium', question: 'What is the difference between weather and climate?', options: ['Weather is short-term; climate is long-term average', 'They are identical', 'Climate is daily', 'Weather is over decades'], correctIndex: 0, explanation: 'Weather describes atmospheric conditions over hours or days; climate represents the average weather over 30+ years.' },
  { id: 'g_m47', difficulty: 'medium', question: 'What is CRISPR?', options: ['Gene-editing technology using guided enzymes', 'A type of microscope', 'A drug', 'A vaccine'], correctIndex: 0, explanation: 'CRISPR-Cas9 is a revolutionary gene-editing tool that allows precise modifications to DNA sequences.' },
  { id: 'g_m48', difficulty: 'medium', question: 'What is the carbon footprint?', options: ['Total greenhouse gases produced by human activities', 'Shoe size', 'Fossil print', 'Carbon dating result'], correctIndex: 0, explanation: 'A carbon footprint measures the total greenhouse gas emissions caused by an individual, event, organization, or product.' },
  { id: 'g_m49', difficulty: 'medium', question: 'What is the difference between mass and weight?', options: ['Mass is amount of matter; weight is gravitational force on that mass', 'They are the same', 'Weight is constant', 'Mass varies with location'], correctIndex: 0, explanation: 'Mass (kg) is the amount of matter in an object and is constant; weight (N) is the gravitational force on that mass and varies by location.' },
  { id: 'g_m50', difficulty: 'medium', question: 'What is forensic science?', options: ['Application of science to legal matters and criminal investigation', 'Study of forests', 'Study of fossils', 'Weather forecasting'], correctIndex: 0, explanation: 'Forensic science applies scientific methods to analyze evidence in criminal investigations and legal proceedings.' },

  // ── HARD (50) ──
  { id: 'g_h1', difficulty: 'hard', question: 'What is quantum entanglement?', options: ['Linked quantum states where measuring one instantly affects the other', 'Chemical bonding', 'Nuclear fusion', 'Gravitational attraction'], correctIndex: 0, explanation: 'Quantum entanglement links particles so that the quantum state of one instantly correlates with the other, regardless of distance.' },
  { id: 'g_h2', difficulty: 'hard', question: 'What is the anthropic principle?', options: ['Universe\'s properties must be compatible with observers existing', 'Human evolution theory', 'Climate change principle', 'Population growth theory'], correctIndex: 0, explanation: 'The anthropic principle states that the universe\'s fundamental constants must be compatible with the existence of observers.' },
  { id: 'g_h3', difficulty: 'hard', question: "What is Schrödinger's cat?", options: ['Thought experiment illustrating quantum superposition', 'A real experiment', 'A cat breed', 'A physics law'], correctIndex: 0, explanation: 'Schrödinger\'s cat is a thought experiment where a cat in a box is simultaneously alive and dead until observed, illustrating quantum superposition.' },
  { id: 'g_h4', difficulty: 'hard', question: "What is Occam's razor?", options: ['Simplest explanation is usually correct', 'A sharp instrument', 'Mathematical proof method', 'A logical fallacy'], correctIndex: 0, explanation: 'Occam\'s razor is a problem-solving principle: among competing hypotheses, the one with the fewest assumptions should be preferred.' },
  { id: 'g_h5', difficulty: 'hard', question: 'What is the theory of everything?', options: ['Hypothetical framework unifying all fundamental forces', 'Biology law', 'Chemical principle', 'Mathematical theorem'], correctIndex: 0, explanation: 'The theory of everything seeks to unify all four fundamental forces (gravity, electromagnetism, strong and weak nuclear) into one framework.' },
  { id: 'g_h6', difficulty: 'hard', question: 'What is the Heisenberg Uncertainty Principle?', options: ['Cannot simultaneously know exact position and momentum of a particle', 'Everything is uncertain', 'Measurements are always wrong', 'Physics has no laws'], correctIndex: 0, explanation: 'The Uncertainty Principle: Δx·Δp ≥ ℏ/2. Precisely knowing a particle\'s position means less precisely knowing its momentum.' },
  { id: 'g_h7', difficulty: 'hard', question: 'What is CRISPR-Cas9\'s mechanism?', options: ['Guide RNA directs Cas9 enzyme to cut DNA at specific sites', 'Random DNA cutting', 'Protein folding', 'RNA transcription only'], correctIndex: 0, explanation: 'CRISPR uses a guide RNA complementary to the target sequence to direct Cas9 nuclease to make precise double-strand cuts in DNA.' },
  { id: 'g_h8', difficulty: 'hard', question: 'What is the multiverse hypothesis?', options: ['Theory that multiple universes exist alongside ours', 'One universe only', 'Parallel dimensions', 'Time travel theory'], correctIndex: 0, explanation: 'The multiverse hypothesis suggests our universe is one of potentially infinite universes, each with different physical constants or laws.' },
  { id: 'g_h9', difficulty: 'hard', question: 'What is the Chandrasekhar limit?', options: ['Maximum mass of a stable white dwarf star', 'Speed of light', 'Universe age', 'Minimum star mass'], correctIndex: 0, explanation: 'The Chandrasekhar limit (~1.4 solar masses) is the maximum mass a white dwarf can have before electron degeneracy pressure fails.' },
  { id: 'g_h10', difficulty: 'hard', question: 'What is the EPR paradox?', options: ['Thought experiment questioning quantum mechanics\' completeness via entanglement', 'A chemical paradox', 'Thermodynamic paradox', 'Biological paradox'], correctIndex: 0, explanation: 'The EPR paradox (Einstein-Podolsky-Rosen) argued that quantum mechanics was incomplete because entanglement seemed to require "spooky action at a distance."' },
  { id: 'g_h11', difficulty: 'hard', question: 'What is Bell\'s theorem?', options: ['No local hidden variable theory can reproduce all quantum mechanical predictions', 'All theories are local', 'Hidden variables always exist', 'Quantum mechanics is wrong'], correctIndex: 0, explanation: 'Bell\'s theorem proves mathematically that no local hidden variable theory can fully reproduce the predictions of quantum mechanics.' },
  { id: 'g_h12', difficulty: 'hard', question: 'What is the measurement problem in quantum mechanics?', options: ['How and why quantum superposition collapses upon observation', 'Inaccurate instruments', 'Statistical errors', 'Calibration issues'], correctIndex: 0, explanation: 'The measurement problem asks why quantum systems appear to "collapse" from superposition to a definite state when measured.' },
  { id: 'g_h13', difficulty: 'hard', question: 'What is the holographic principle?', options: ['All information in a volume can be encoded on its boundary', 'Holograms are real objects', '3D printing theory', 'Optical illusion theory'], correctIndex: 0, explanation: 'The holographic principle suggests that all information within a region of space can be described by data on its boundary.' },
  { id: 'g_h14', difficulty: 'hard', question: 'What is the Turing test?', options: ['Test of a machine\'s ability to exhibit intelligent behavior indistinguishable from a human', 'Hardware test', 'Speed test', 'Memory test'], correctIndex: 0, explanation: 'The Turing test evaluates whether a machine can exhibit intelligent behavior equivalent to or indistinguishable from a human.' },
  { id: 'g_h15', difficulty: 'hard', question: 'What is the many-worlds interpretation?', options: ['Every quantum measurement causes the universe to branch into multiple copies', 'Only one outcome exists', 'Probabilities are wrong', 'Universe is deterministic'], correctIndex: 0, explanation: 'The many-worlds interpretation proposes that all possible quantum measurement outcomes are physically realized in branching parallel universes.' },
  { id: 'g_h16', difficulty: 'hard', question: 'What is decoherence in quantum mechanics?', options: ['Loss of quantum coherence through interaction with environment', 'Gaining coherence', 'Creating entanglement', 'Measuring spin'], correctIndex: 0, explanation: 'Decoherence explains how quantum systems lose superposition through interactions with the environment, appearing classical.' },
  { id: 'g_h17', difficulty: 'hard', question: 'What is the Kardashev scale?', options: ['Classification of civilizations by energy consumption', 'Temperature scale', 'Earthquake scale', 'Sound scale'], correctIndex: 0, explanation: 'The Kardashev scale classifies civilizations: Type I uses all energy available on its planet, Type II its star, Type III its galaxy.' },
  { id: 'g_h18', difficulty: 'hard', question: 'What is Gödel\'s incompleteness theorem relevant to?', options: ['No consistent mathematical system can prove all truths about itself', 'All math is complete', 'Physics only', 'Chemistry only'], correctIndex: 0, explanation: 'Gödel showed that any sufficiently powerful mathematical system contains true statements that cannot be proved within that system.' },
  { id: 'g_h19', difficulty: 'hard', question: 'What is the Boltzmann brain?', options: ['Hypothetical self-aware entity arising from random fluctuations in equilibrium', 'A real brain', 'A computer', 'An AI system'], correctIndex: 0, explanation: 'A Boltzmann brain is a thought experiment: a fully formed brain could theoretically arise spontaneously from random thermodynamic fluctuations.' },
  { id: 'g_h20', difficulty: 'hard', question: 'What is the significance of the fine structure constant?', options: ['Dimensionless constant characterizing the strength of electromagnetic interaction (~1/137)', 'Speed of light', 'Planck\'s constant', 'Gravitational constant'], correctIndex: 0, explanation: 'The fine structure constant α ≈ 1/137 determines the strength of electromagnetic interactions and appears throughout physics.' },
  { id: 'g_h21', difficulty: 'hard', question: 'What is the Penrose-Hawking singularity theorem?', options: ['Under general relativity, gravitational collapse inevitably leads to singularities', 'Singularities don\'t exist', 'Only in special cases', 'Only for small objects'], correctIndex: 0, explanation: 'The Penrose-Hawking theorems prove that under general relativity with reasonable energy conditions, singularities are inevitable in gravitational collapse.' },
  { id: 'g_h22', difficulty: 'hard', question: 'What is the Maxwell\'s demon thought experiment?', options: ['Hypothetical being that appears to violate the second law of thermodynamics', 'A real particle', 'A chemical compound', 'An equation'], correctIndex: 0, explanation: 'Maxwell\'s demon is a thought experiment where a being selectively sorts molecules to decrease entropy, resolved by the thermodynamic cost of information.' },
  { id: 'g_h23', difficulty: 'hard', question: 'What is the Casimir effect?', options: ['Attractive force between two uncharged plates from quantum vacuum fluctuations', 'Magnetic repulsion', 'Gravitational attraction', 'Static electricity'], correctIndex: 0, explanation: 'The Casimir effect demonstrates a measurable force between uncharged conducting plates due to quantum vacuum energy fluctuations.' },
  { id: 'g_h24', difficulty: 'hard', question: 'What is the P vs NP problem?', options: ['Whether problems whose solutions can be verified quickly can also be solved quickly', 'A physics equation', 'A chemical formula', 'A biological question'], correctIndex: 0, explanation: 'P vs NP asks whether every problem whose solution can be verified in polynomial time can also be solved in polynomial time — one of the greatest unsolved problems.' },
  { id: 'g_h25', difficulty: 'hard', question: 'What is topological quantum computing?', options: ['Computing using anyons and topological states resistant to decoherence', 'Classical computing', 'Regular quantum computing', 'Analog computing'], correctIndex: 0, explanation: 'Topological quantum computing uses anyons — quasiparticles with topological properties that make qubits inherently resistant to errors.' },
  { id: 'g_h26', difficulty: 'hard', question: 'What is the AdS/CFT correspondence?', options: ['Duality between gravity in anti-de Sitter space and conformal field theory on its boundary', 'A chemical reaction', 'A biological process', 'A classical mechanics principle'], correctIndex: 0, explanation: 'The AdS/CFT correspondence (Maldacena conjecture) relates quantum gravity in anti-de Sitter space to a conformal field theory on its boundary.' },
  { id: 'g_h27', difficulty: 'hard', question: 'What is the cosmological constant problem?', options: ['Predicted vacuum energy is ~10¹²⁰ times larger than observed', 'No discrepancy exists', 'A mathematical error', 'An experimental artifact'], correctIndex: 0, explanation: 'The cosmological constant problem is the enormous discrepancy (~10¹²⁰) between theoretical quantum vacuum energy predictions and the observed value.' },
  { id: 'g_h28', difficulty: 'hard', question: 'What is quantum chromodynamics?', options: ['Theory of the strong force between quarks mediated by gluons', 'Study of colors', 'Chemical bonding theory', 'Electromagnetic theory'], correctIndex: 0, explanation: 'QCD describes the strong nuclear force: quarks interact by exchanging gluons, with the force characterized by "color charge."' },
  { id: 'g_h29', difficulty: 'hard', question: 'What is the hierarchy problem in physics?', options: ['Why the weak force is so much stronger than gravity', 'Organizational structure', 'Classification system', 'Naming convention'], correctIndex: 0, explanation: 'The hierarchy problem asks why the weak force is ~10³² times stronger than gravity, or equivalently why the Higgs mass is so small.' },
  { id: 'g_h30', difficulty: 'hard', question: 'What is the Planck scale?', options: ['Smallest meaningful scales of length, time, and energy in physics', 'Astronomical scale', 'Human scale', 'Molecular scale'], correctIndex: 0, explanation: 'The Planck scale (~10⁻³⁵ m, ~10⁻⁴³ s) represents the scales where quantum gravity effects become significant.' },
  { id: 'g_h31', difficulty: 'hard', question: 'What is supersymmetry (SUSY)?', options: ['Theory proposing a partner particle for each known particle', 'Mirror symmetry', 'Time symmetry', 'Charge symmetry'], correctIndex: 0, explanation: 'Supersymmetry proposes that each fermion has a bosonic superpartner and vice versa, potentially solving the hierarchy problem.' },
  { id: 'g_h32', difficulty: 'hard', question: 'What is the Bekenstein bound?', options: ['Maximum entropy that can be contained in a given region', 'Minimum energy', 'Maximum speed', 'Temperature limit'], correctIndex: 0, explanation: 'The Bekenstein bound limits the maximum entropy (information) that can be contained in a finite region with finite energy.' },
  { id: 'g_h33', difficulty: 'hard', question: 'What is the strong CP problem?', options: ['Why QCD doesn\'t violate CP symmetry despite having no reason not to', 'Strong nuclear force strength', 'Chemical bonding issue', 'Biological problem'], correctIndex: 0, explanation: 'The strong CP problem asks why quantum chromodynamics preserves CP symmetry when its equations allow for CP violation.' },
  { id: 'g_h34', difficulty: 'hard', question: 'What is loop quantum gravity?', options: ['Theory quantizing spacetime into discrete loops', 'String theory', 'Classical gravity', 'Newtonian mechanics'], correctIndex: 0, explanation: 'Loop quantum gravity quantizes spacetime itself into discrete units (spin networks), proposing a granular structure at the Planck scale.' },
  { id: 'g_h35', difficulty: 'hard', question: 'What is the black hole information paradox?', options: ['Whether information is destroyed when entering a black hole', 'Black holes don\'t exist', 'Information is always preserved classically', 'No paradox exists'], correctIndex: 0, explanation: 'The information paradox asks whether quantum information is truly lost in black holes, conflicting with unitarity in quantum mechanics.' },
  { id: 'g_h36', difficulty: 'hard', question: 'What is the Landauer principle?', options: ['Erasing one bit of information dissipates minimum kT ln2 energy', 'Information is free', 'Computation costs no energy', 'Entropy can decrease freely'], correctIndex: 0, explanation: 'Landauer\'s principle sets a fundamental lower limit on energy dissipation when erasing information: E ≥ kT ln2 per bit.' },
  { id: 'g_h37', difficulty: 'hard', question: 'What is the Mpemba effect?', options: ['Under certain conditions, hot water freezes faster than cold water', 'Cold water always freezes first', 'Temperature doesn\'t affect freezing', 'Only pure water freezes'], correctIndex: 0, explanation: 'The Mpemba effect is the counterintuitive observation that hot water can sometimes freeze faster than cold water under certain conditions.' },
  { id: 'g_h38', difficulty: 'hard', question: 'What is the Kessler syndrome?', options: ['Cascading collisions of space debris making orbits unusable', 'A medical condition', 'A chemical reaction', 'An earthquake pattern'], correctIndex: 0, explanation: 'Kessler syndrome describes a scenario where collisions between space debris cascade, generating more debris and potentially rendering orbits unusable.' },
  { id: 'g_h39', difficulty: 'hard', question: 'What is quantum decoherence?', options: ['Process by which quantum systems lose coherence through environmental interaction', 'Maintaining coherence', 'Creating superposition', 'Quantum tunneling'], correctIndex: 0, explanation: 'Quantum decoherence occurs when a quantum system interacts with its environment, causing loss of superposition and apparent classical behavior.' },
  { id: 'g_h40', difficulty: 'hard', question: 'What is the simulation hypothesis?', options: ['Proposition that reality might be a computer simulation', 'Proven theory', 'Disproven idea', 'A programming language'], correctIndex: 0, explanation: 'The simulation hypothesis, popularized by Bostrom, proposes that we might be living in a computer simulation created by an advanced civilization.' },
  { id: 'g_h41', difficulty: 'hard', question: 'What is the observer effect in quantum mechanics?', options: ['Act of measurement fundamentally alters the system being measured', 'Observers don\'t affect systems', 'Only affects macroscopic objects', 'A classical concept'], correctIndex: 0, explanation: 'In quantum mechanics, measurement disturbs the system: observing a particle\'s position changes its momentum, for example.' },
  { id: 'g_h42', difficulty: 'hard', question: 'What is emergent behavior?', options: ['Complex patterns arising from simple rules of individual components', 'Predetermined outcomes', 'Random noise', 'Designed complexity'], correctIndex: 0, explanation: 'Emergence occurs when complex patterns, structures, or behaviors arise from relatively simple underlying rules or interactions.' },
  { id: 'g_h43', difficulty: 'hard', question: 'What is the ship of Theseus paradox in relation to biology?', options: ['Whether an organism remains the same if all cells are gradually replaced', 'A boat design', 'A navigation problem', 'A engineering challenge'], correctIndex: 0, explanation: 'The biological Ship of Theseus asks: since most human cells are replaced over time, are you the same person you were years ago?' },
  { id: 'g_h44', difficulty: 'hard', question: 'What is the concept of falsifiability?', options: ['Scientific theories must be testable and potentially disprovable', 'Theories must be proven true', 'All theories are false', 'No theory can be tested'], correctIndex: 0, explanation: 'Falsifiability (Popper\'s criterion) requires that scientific claims must be structured so they can potentially be proven wrong through observation.' },
  { id: 'g_h45', difficulty: 'hard', question: 'What is the Fermi estimation technique?', options: ['Making rough calculations with limited data using logical reasoning', 'Exact computation', 'Random guessing', 'Statistical sampling'], correctIndex: 0, explanation: 'Fermi estimation uses logical reasoning and approximation to make rough calculations when exact data is unavailable.' },
  { id: 'g_h46', difficulty: 'hard', question: 'What is the Dunning-Kruger effect in science?', options: ['Cognitive bias where people overestimate their competence in areas where they lack expertise', 'Expert confidence', 'Normal learning', 'Scientific method step'], correctIndex: 0, explanation: 'The Dunning-Kruger effect is a cognitive bias where people with limited knowledge in an area overestimate their own competence.' },
  { id: 'g_h47', difficulty: 'hard', question: 'What is quantum supremacy?', options: ['Point where quantum computers solve problems impossible for classical computers', 'Classical computer superiority', 'Fastest computer', 'Most memory'], correctIndex: 0, explanation: 'Quantum supremacy is when a quantum computer performs a calculation that no classical computer can do in a reasonable time.' },
  { id: 'g_h48', difficulty: 'hard', question: 'What is the ergodic hypothesis?', options: ['Time averages equal ensemble averages for a system exploring all accessible states', 'Systems never reach equilibrium', 'Only applies to gases', 'Time is irreversible'], correctIndex: 0, explanation: 'The ergodic hypothesis states that over long times, a system visits all accessible microstates, so time averages equal ensemble averages.' },
  { id: 'g_h49', difficulty: 'hard', question: 'What is the concept of scientific paradigm shift?', options: ['Fundamental change in the basic concepts and practices of a scientific discipline', 'Minor update', 'Gradual change only', 'No change ever occurs'], correctIndex: 0, explanation: 'Thomas Kuhn described paradigm shifts as revolutionary changes in fundamental scientific frameworks (e.g., Newtonian to Einsteinian physics).' },
  { id: 'g_h50', difficulty: 'hard', question: 'What is the Sapir-Whorf hypothesis relevant to cognitive science?', options: ['Language structure influences the way its speakers perceive the world', 'Language doesn\'t affect thought', 'All languages are identical', 'Only written language matters'], correctIndex: 0, explanation: 'The Sapir-Whorf hypothesis proposes that the language we speak shapes our thoughts and perception of reality (linguistic relativity).' },
];

